window.DD_FULL = window.DD_FULL || {}; window.DD_FULL["satit-1"] = {"questions":[{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"e","skill":{"en":"Applying number properties","th":"การใช้สมบัติของจำนวน"},"topic":{"en":"Number sense and divisibility","th":"จำนวนและการหารลงตัว"},"passage":"","table":null,"lang":"th","stem":"ถ้า ห.ร.ม. ของ 72 และ 120 คือ ก และ ค.ร.น. ของ 72 และ 120 คือ ข แล้ว ก × ข มีค่าเท่าใด","choices":["360","4,320","17,280","8,640"],"answer":3,"explanation":{"en":"The HCF is 24 and the LCM is 360, so their product is 24 × 360 = 8,640. Shortcut: for two numbers, HCF × LCM always equals the product of the numbers, 72 × 120 = 8,640.","th":"ห.ร.ม. = 24 และ ค.ร.น. = 360 ผลคูณ = 24 × 360 = 8,640 วิธีลัด: สำหรับจำนวนสองจำนวน ห.ร.ม. × ค.ร.น. = ผลคูณของสองจำนวนนั้นเสมอ คือ 72 × 120 = 8,640"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"m","skill":{"en":"Multi-step problem solving","th":"การแก้โจทย์ปัญหาหลายขั้นตอน"},"topic":{"en":"Number sense and divisibility","th":"จำนวนและการหารลงตัว"},"passage":"","table":null,"lang":"th","stem":"จำนวนนับที่น้อยที่สุดซึ่งเมื่อหารด้วย 4, 5 และ 6 จะเหลือเศษ 3 ทุกครั้ง และหารด้วย 11 ลงตัว คือจำนวนใด","choices":["363","123","243","483"],"answer":0,"explanation":{"en":"A number that leaves remainder 3 when divided by 4, 5 and 6 is 3 more than a multiple of their LCM 60: 63, 123, 183, 243, 303, 363, … Testing for divisibility by 11, the first one that works is 363 = 11 × 33. 123, 243 and 483 fit the remainders but are not multiples of 11.","th":"จำนวนที่หารด้วย 4, 5, 6 เหลือเศษ 3 คือ (พหุคูณของ ค.ร.น. 60) + 3 ได้แก่ 63, 123, 183, 243, 303, 363, … ตรวจการหารด้วย 11 ลงตัว ตัวแรกที่ได้คือ 363 = 11 × 33 ส่วน 123, 243, 483 เหลือเศษตามเงื่อนไขแต่หารด้วย 11 ไม่ลงตัว"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"e","skill":{"en":"Multi-step problem solving","th":"การแก้โจทย์ปัญหาหลายขั้นตอน"},"topic":{"en":"Fractions and decimals","th":"เศษส่วนและทศนิยม"},"passage":"","table":null,"lang":"th","stem":"น้ำมันในถังใบหนึ่ง ใช้ไป 2/5 ของที่มีอยู่ แล้วใช้ต่ออีก 1/3 ของส่วนที่เหลือ ปรากฏว่ายังเหลือน้ำมัน 24 ลิตร เดิมมีน้ำมันกี่ลิตร","choices":["40 ลิตร","72 ลิตร","60 ลิตร","90 ลิตร"],"answer":2,"explanation":{"en":"After using 2/5, 3/5 remains; using 1/3 of that leaves 2/3 × 3/5 = 2/5 of the original. 2/5 of the tank = 24 litres, so the tank held 24 × 5/2 = 60 litres.","th":"ใช้ไป 2/5 เหลือ 3/5 ใช้อีก 1/3 ของที่เหลือ จะเหลือ 2/3 × 3/5 = 2/5 ของเดิม ดังนั้น 2/5 ของเดิม = 24 ลิตร เดิมมี 24 × 5/2 = 60 ลิตร"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"m","skill":{"en":"Accurate computation","th":"การคำนวณอย่างแม่นยำ"},"topic":{"en":"Fractions and decimals","th":"เศษส่วนและทศนิยม"},"passage":"","table":null,"lang":"th","stem":"ค่าของ 1 + 1 ÷ (2 + 1 ÷ (3 + 1/2)) เท่ากับข้อใด","choices":["23/16","16/23","9/7","17/12"],"answer":0,"explanation":{"en":"Work from the inside: 3 + 1/2 = 7/2, so 1 ÷ 7/2 = 2/7; 2 + 2/7 = 16/7; 1 ÷ 16/7 = 7/16; 1 + 7/16 = 23/16.","th":"คำนวณจากวงเล็บในสุด: 3 + 1/2 = 7/2 ได้ 1 ÷ 7/2 = 2/7 ต่อมา 2 + 2/7 = 16/7 ได้ 1 ÷ 16/7 = 7/16 สุดท้าย 1 + 7/16 = 23/16"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"h","skill":{"en":"Modelling a situation with equations","th":"การสร้างแบบจำลองสมการจากสถานการณ์"},"topic":{"en":"Percentage and profit–loss","th":"ร้อยละและกำไรขาดทุน"},"passage":"","table":null,"lang":"th","stem":"ร้านค้าตั้งราคาสินค้าสูงกว่าราคาทุนร้อยละ 40 ต่อมาลดราคาให้ลูกค้าร้อยละ 15 จากราคาที่ตั้งไว้ ปรากฏว่ายังได้กำไร 76 บาท สินค้านี้มีราคาทุนกี่บาท","choices":["304 บาท","380 บาท","760 บาท","400 บาท"],"answer":3,"explanation":{"en":"Let the cost be 100%. Marked price = 140%; after a 15% discount the selling price is 140% × 0.85 = 119% of cost, so the profit is 19% of cost. 19% = 76 baht, so cost = 76 × 100/19 = 400 baht. (304 baht comes from wrongly taking the profit as 40% − 15% = 25% of cost; the discount is taken from the marked price, not the cost.)","th":"ให้ทุน = 100% ราคาตั้ง = 140% ลด 15% เหลือ 140% × 0.85 = 119% ของทุน จึงกำไร 19% ของทุน 19% = 76 บาท ทุน = 76 × 100/19 = 400 บาท (ถ้าคิดกำไรเป็น 40% − 15% = 25% จะได้ 304 บาท ซึ่งผิด เพราะส่วนลดคิดจากราคาตั้ง ไม่ใช่จากทุน)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"m","skill":{"en":"Modelling a situation with equations","th":"การสร้างแบบจำลองสมการจากสถานการณ์"},"topic":{"en":"Percentage and profit–loss","th":"ร้อยละและกำไรขาดทุน"},"passage":"","table":null,"lang":"th","stem":"ห้องเรียนหนึ่งมีนักเรียน 40 คน เป็นนักเรียนชายร้อยละ 35 ต่อมามีนักเรียนชายย้ายเข้ามาเพิ่ม (ไม่มีใครย้ายออก) ทำให้นักเรียนชายคิดเป็นร้อยละ 48 ของห้อง มีนักเรียนชายย้ายเข้ามากี่คน","choices":["10 คน","5 คน","8 คน","13 คน"],"answer":0,"explanation":{"en":"There are 35% × 40 = 14 boys. If x boys join, (14 + x)/(40 + x) = 48/100, so 1,400 + 100x = 1,920 + 48x, giving 52x = 520 and x = 10. Check: 24 boys out of 50 = 48%. (5 comes from forgetting that the class size also grows.)","th":"เดิมมีชาย 35% × 40 = 14 คน ให้ย้ายเข้า x คน จะได้ (14 + x)/(40 + x) = 48/100 → 1,400 + 100x = 1,920 + 48x → 52x = 520 → x = 10 ตรวจ: ชาย 24 คนจาก 50 คน = 48% (ถ้าลืมว่าจำนวนนักเรียนทั้งห้องเพิ่มขึ้นด้วย จะได้คำตอบผิดเป็น 5 คน)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"m","skill":{"en":"Modelling a situation with equations","th":"การสร้างแบบจำลองสมการจากสถานการณ์"},"topic":{"en":"Ratio and proportion","th":"อัตราส่วนและสัดส่วน"},"passage":"","table":null,"lang":"th","stem":"ปัจจุบันอายุพ่อเป็น 4 เท่าของอายุลูก อีก 6 ปีข้างหน้าอายุพ่อจะเป็น 3 เท่าของอายุลูก ปัจจุบันพ่อและลูกมีอายุรวมกันกี่ปี","choices":["60 ปี","48 ปี","66 ปี","72 ปี"],"answer":0,"explanation":{"en":"Let the son be k now, father 4k. In 6 years: 4k + 6 = 3(k + 6), so k = 12. Father 48, son 12, total 60. (72 is their total in 6 years' time.)","th":"ให้อายุลูกปัจจุบัน k ปี พ่อ 4k ปี อีก 6 ปี: 4k + 6 = 3(k + 6) → k = 12 พ่อ 48 ปี ลูก 12 ปี รวม 60 ปี (72 ปีคืออายุรวมในอีก 6 ปีข้างหน้า)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"h","skill":{"en":"Multi-step problem solving","th":"การแก้โจทย์ปัญหาหลายขั้นตอน"},"topic":{"en":"Ratio and proportion","th":"อัตราส่วนและสัดส่วน"},"passage":"","table":null,"lang":"th","stem":"เงินของ ก ต่อเงินของ ข เป็น 3 : 5 และเงินของ ข ต่อเงินของ ค เป็น 2 : 3 ถ้า ค มีเงินมากกว่า ก อยู่ 54 บาท ทั้งสามคนมีเงินรวมกันกี่บาท","choices":["155 บาท","210 บาท","186 บาท","248 บาท"],"answer":2,"explanation":{"en":"Make B's share the same in both ratios: A : B = 6 : 10 and B : C = 10 : 15, so A : B : C = 6 : 10 : 15. C − A = 9 parts = 54 baht, so 1 part = 6 baht and the total is 31 × 6 = 186 baht.","th":"ทำส่วนของ ข ให้เท่ากัน: ก : ข = 6 : 10 และ ข : ค = 10 : 15 จึงได้ ก : ข : ค = 6 : 10 : 15 ค มากกว่า ก 9 ส่วน = 54 บาท 1 ส่วน = 6 บาท รวม 31 ส่วน = 186 บาท"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"e","skill":{"en":"Geometric reasoning","th":"การให้เหตุผลทางเรขาคณิต"},"topic":{"en":"Plane geometry and angles","th":"เรขาคณิตและมุม"},"passage":"","table":null,"lang":"th","stem":"รูปหกเหลี่ยมด้านเท่ามุมเท่า มีขนาดของมุมภายในแต่ละมุมเท่ากับกี่องศา","choices":["120 องศา","60 องศา","108 องศา","135 องศา"],"answer":0,"explanation":{"en":"The interior angles of a hexagon add up to (6 − 2) × 180° = 720°. A regular hexagon has six equal angles: 720° ÷ 6 = 120°. (108° is a regular pentagon's angle, 60° is the exterior angle.)","th":"ผลรวมมุมภายในของรูปหกเหลี่ยม = (6 − 2) × 180° = 720° หกเหลี่ยมด้านเท่ามุมเท่ามีมุมเท่ากัน 6 มุม จึงได้มุมละ 720° ÷ 6 = 120° (108° เป็นมุมภายในของห้าเหลี่ยมด้านเท่า ส่วน 60° เป็นมุมภายนอก)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"h","skill":{"en":"Geometric reasoning","th":"การให้เหตุผลทางเรขาคณิต"},"topic":{"en":"Plane geometry and angles","th":"เรขาคณิตและมุม"},"passage":"","table":null,"lang":"th","stem":"รูปสามเหลี่ยม ABC มี AB = AC และมุม BAC = 50° ลากเส้นแบ่งครึ่งมุม ABC ไปตัดด้าน AC ที่จุด D มุม BDC มีขนาดกี่องศา","choices":["65 องศา","82.5 องศา","97.5 องศา","115 องศา"],"answer":1,"explanation":{"en":"AB = AC, so angles B and C are equal: (180° − 50°) ÷ 2 = 65° each. BD halves angle B, so angle ABD = 32.5°. Angle BDC is an exterior angle of triangle ABD, so it equals 50° + 32.5° = 82.5°. Check in triangle BDC: 32.5° + 65° + 82.5° = 180°. (97.5° is angle ADB.)","th":"AB = AC มุม B = มุม C = (180° − 50°) ÷ 2 = 65° BD แบ่งครึ่งมุม B จึงได้มุม ABD = 32.5° มุม BDC เป็นมุมภายนอกของสามเหลี่ยม ABD จึงเท่ากับ 50° + 32.5° = 82.5° ตรวจในสามเหลี่ยม BDC: 32.5° + 65° + 82.5° = 180° (97.5° คือมุม ADB)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"m","skill":{"en":"Geometric reasoning","th":"การให้เหตุผลทางเรขาคณิต"},"topic":{"en":"Area, perimeter and volume","th":"พื้นที่ ความยาวรอบรูป และปริมาตร"},"passage":"","table":null,"lang":"th","stem":"กระดาษแข็งรูปสี่เหลี่ยมผืนผ้ายาว 12 ซม. กว้าง 8 ซม. ตัดรูปสี่เหลี่ยมจัตุรัสยาวด้านละ 2 ซม. ออกที่มุมทั้งสี่ แล้วพับขึ้นเป็นกล่องไม่มีฝา กล่องนี้มีปริมาตรกี่ลูกบาศก์เซนติเมตร","choices":["96","64","128","192"],"answer":1,"explanation":{"en":"Cutting 2 cm from both ends of each side leaves a base of (12 − 4) × (8 − 4) = 8 × 4 cm, and the folded flaps make the box 2 cm high. Volume = 8 × 4 × 2 = 64 cm³. (192 forgets to shorten the base; 96 subtracts only 2 cm from each side.)","th":"ตัดมุมด้านละ 2 ซม. ทั้งสองปลาย ฐานกล่องจะเหลือ (12 − 4) × (8 − 4) = 8 × 4 ซม. และสูง 2 ซม. ปริมาตร = 8 × 4 × 2 = 64 ลบ.ซม. (192 คือคิดฐานเต็มแผ่นโดยไม่ลดความยาว ส่วน 96 ลดด้านละ 2 ซม. เพียงครั้งเดียว)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"h","skill":{"en":"Geometric reasoning","th":"การให้เหตุผลทางเรขาคณิต"},"topic":{"en":"Area, perimeter and volume","th":"พื้นที่ ความยาวรอบรูป และปริมาตร"},"passage":"","table":null,"lang":"th","stem":"วงกลมรัศมี 7 ซม. มีรูปสี่เหลี่ยมจัตุรัสแนบในวงกลม (มุมทั้งสี่ของจัตุรัสอยู่บนเส้นรอบวง) พื้นที่ส่วนที่อยู่ในวงกลมแต่อยู่นอกรูปสี่เหลี่ยมจัตุรัสเท่ากับกี่ตารางเซนติเมตร (ใช้ π ≈ 22/7)","choices":["42","98","56","105"],"answer":2,"explanation":{"en":"Circle area = 22/7 × 7 × 7 = 154 cm². The square's diagonal is a diameter, 14 cm, and a square's area is diagonal² ÷ 2 = 196 ÷ 2 = 98 cm². The region inside the circle but outside the square is 154 − 98 = 56 cm². (42 is the gap between a circle and the square drawn around it.)","th":"พื้นที่วงกลม = 22/7 × 7 × 7 = 154 ตร.ซม. เส้นทแยงมุมของจัตุรัสแนบในคือเส้นผ่านศูนย์กลาง 14 ซม. พื้นที่จัตุรัส = (เส้นทแยงมุม)² ÷ 2 = 196 ÷ 2 = 98 ตร.ซม. พื้นที่ที่ต้องการ = 154 − 98 = 56 ตร.ซม. (42 คือพื้นที่ระหว่างวงกลมกับจัตุรัสที่ล้อมรอบวงกลม)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"m","skill":{"en":"Generalising a pattern","th":"การหาความสัมพันธ์ทั่วไปของแบบรูป"},"topic":{"en":"Patterns and sequences","th":"แบบรูปและลำดับ"},"passage":"","table":null,"lang":"th","stem":"ลำดับ 3, 7, 13, 21, 31, … มีพจน์ที่ 20 เท่ากับเท่าใด","choices":["421","401","381","441"],"answer":0,"explanation":{"en":"The differences are 4, 6, 8, 10, … so the n-th term is n² + n + 1 (check: 1 + 1 + 1 = 3, 4 + 2 + 1 = 7, 9 + 3 + 1 = 13). The 20th term is 400 + 20 + 1 = 421.","th":"ผลต่างระหว่างพจน์เป็น 4, 6, 8, 10, … พจน์ทั่วไปคือ n² + n + 1 (ตรวจ: 1+1+1 = 3, 4+2+1 = 7, 9+3+1 = 13) พจน์ที่ 20 = 400 + 20 + 1 = 421"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"h","skill":{"en":"Generalising a pattern","th":"การหาความสัมพันธ์ทั่วไปของแบบรูป"},"topic":{"en":"Patterns and sequences","th":"แบบรูปและลำดับ"},"passage":"","table":null,"lang":"th","stem":"ใช้ไม้ขีดต่อเป็นตารางรูปสี่เหลี่ยมจัตุรัสขนาด 1 × 1, 2 × 2, 3 × 3, … ช่อง โดยใช้ไม้ขีด 4, 12, 24, … ก้าน ตามลำดับ ถ้ามีไม้ขีด 200 ก้าน และต้องการต่อตารางขนาด n × n ที่ใหญ่ที่สุดเท่าที่ทำได้เพียงรูปเดียว จะเหลือไม้ขีดกี่ก้าน","choices":["0 ก้าน","10 ก้าน","40 ก้าน","20 ก้าน"],"answer":3,"explanation":{"en":"An n × n grid has n + 1 horizontal lines of n sticks and n + 1 vertical lines of n sticks, so it needs 2n(n + 1) sticks (4, 12, 24 ✓). A 9 × 9 grid needs 2 × 9 × 10 = 180 sticks; a 10 × 10 grid needs 220, which is too many. So 200 − 180 = 20 sticks are left.","th":"ตาราง n × n มีเส้นแนวนอน n + 1 เส้น เส้นละ n ก้าน และแนวตั้งอีก n + 1 เส้น เส้นละ n ก้าน รวม 2n(n + 1) ก้าน (ตรวจ 4, 12, 24 ถูก) ตาราง 9 × 9 ใช้ 2 × 9 × 10 = 180 ก้าน ตาราง 10 × 10 ใช้ 220 ก้าน เกิน 200 จึงต่อได้ใหญ่สุด 9 × 9 เหลือ 200 − 180 = 20 ก้าน"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"m","skill":{"en":"Interpreting data","th":"การแปลความหมายข้อมูล"},"topic":{"en":"Data and averages","th":"ข้อมูลและค่าเฉลี่ย"},"passage":"","table":null,"lang":"th","stem":"นักเรียน 8 คนสอบได้คะแนนเฉลี่ย 65 คะแนน เมื่อตัดคะแนนของคนที่ได้สูงสุดและต่ำสุดออก คะแนนเฉลี่ยของ 6 คนที่เหลือเป็น 64 คะแนน ถ้าคะแนนสูงสุดมากกว่าคะแนนต่ำสุดอยู่ 30 คะแนน คะแนนสูงสุดคือเท่าใด","choices":["53","68","83","79"],"answer":2,"explanation":{"en":"Total for 8 students = 8 × 65 = 520; total for the 6 = 6 × 64 = 384. The highest and lowest together = 520 − 384 = 136. With a difference of 30: highest = (136 + 30) ÷ 2 = 83, lowest = 53.","th":"คะแนนรวม 8 คน = 8 × 65 = 520 คะแนนรวม 6 คน = 6 × 64 = 384 คะแนนสูงสุดรวมกับต่ำสุด = 520 − 384 = 136 ต่างกัน 30 จึงได้ คะแนนสูงสุด = (136 + 30) ÷ 2 = 83 (ต่ำสุด 53)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"m","skill":{"en":"Interpreting data","th":"การแปลความหมายข้อมูล"},"topic":{"en":"Data and averages","th":"ข้อมูลและค่าเฉลี่ย"},"passage":"","table":{"title":"จำนวนขนมปังที่ขายได้ (ชิ้น)","rows":[["วัน","จันทร์","อังคาร","พุธ","พฤหัสบดี"],["จำนวน","120","150","?","100"]]},"lang":"th","stem":"ตารางแสดงจำนวนขนมปังที่ร้านหนึ่งขายได้ใน 4 วัน ถ้าค่าเฉลี่ยของ 4 วันคือ 125 ชิ้นต่อวัน วันพุธขายได้มากกว่าวันพฤหัสบดีร้อยละเท่าใด","choices":["ร้อยละ 30","ร้อยละ 23","ร้อยละ 25","ร้อยละ 130"],"answer":0,"explanation":{"en":"Total for 4 days = 4 × 125 = 500, so Wednesday = 500 − 120 − 150 − 100 = 130 loaves. Wednesday sold 30 more than Thursday; as a percentage of Thursday's 100 that is 30%. (23% divides by Wednesday's 130 instead of Thursday's figure.)","th":"ยอดรวม 4 วัน = 4 × 125 = 500 ชิ้น วันพุธ = 500 − 120 − 150 − 100 = 130 ชิ้น มากกว่าวันพฤหัสบดี 30 ชิ้น เทียบกับยอดวันพฤหัสบดี 100 ชิ้น = ร้อยละ 30 (ร้อยละ 23 เกิดจากการหารด้วย 130 ซึ่งเป็นฐานที่ผิด)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"m","skill":{"en":"Modelling a situation with equations","th":"การสร้างแบบจำลองสมการจากสถานการณ์"},"topic":{"en":"Rate, speed and work","th":"อัตรา ความเร็ว และงาน"},"passage":"","table":null,"lang":"th","stem":"รถยนต์คันที่หนึ่งออกจากจุด P เวลา 08.00 น. ด้วยอัตราเร็วคงตัว 60 กม./ชม. รถยนต์คันที่สองออกจากจุด P ตามไปบนเส้นทางเดียวกันเวลา 09.30 น. ด้วยอัตราเร็วคงตัว 90 กม./ชม. รถคันที่สองจะตามทันคันแรกเวลาใด","choices":["12.30 น.","11.30 น.","12.00 น.","13.00 น."],"answer":0,"explanation":{"en":"By 09.30 the first car has driven 1.5 h × 60 = 90 km. The second car closes the gap at 90 − 60 = 30 km/h, so it needs 90 ÷ 30 = 3 hours: 09.30 + 3 h = 12.30.","th":"เวลา 09.30 น. รถคันแรกไปแล้ว 1.5 ชม. × 60 = 90 กม. รถคันที่สองไล่ระยะห่างได้ชั่วโมงละ 90 − 60 = 30 กม. ต้องใช้เวลา 90 ÷ 30 = 3 ชม. จึงทันกันเวลา 09.30 + 3 ชม. = 12.30 น."}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"h","skill":{"en":"Multi-step problem solving","th":"การแก้โจทย์ปัญหาหลายขั้นตอน"},"topic":{"en":"Rate, speed and work","th":"อัตรา ความเร็ว และงาน"},"passage":"","table":null,"lang":"th","stem":"ก ทำงานชิ้นหนึ่งคนเดียวเสร็จใน 12 วัน ข ทำงานชิ้นเดียวกันคนเดียวเสร็จใน 18 วัน ทั้งสองช่วยกันทำ 4 วัน แล้ว ก ลาออก ข ต้องทำต่ออีกกี่วันงานจึงจะเสร็จ","choices":["6 วัน","7.2 วัน","10 วัน","8 วัน"],"answer":3,"explanation":{"en":"Per day A does 1/12 and B does 1/18 of the job; together 1/12 + 1/18 = 5/36. In 4 days: 20/36 = 5/9 done, 4/9 left. B alone needs 4/9 × 18 = 8 days.","th":"ใน 1 วัน ก ทำได้ 1/12 ข ทำได้ 1/18 ของงาน ช่วยกันวันละ 1/12 + 1/18 = 5/36 ทำ 4 วันได้ 20/36 = 5/9 เหลือ 4/9 ข ทำคนเดียวต้องใช้ 4/9 × 18 = 8 วัน"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"h","skill":{"en":"Systematic counting","th":"การนับอย่างเป็นระบบ"},"topic":{"en":"Logical reasoning and counting","th":"การให้เหตุผลและการนับ"},"passage":"","table":null,"lang":"th","stem":"จำนวนคู่ที่มีสามหลัก และเลขโดดในแต่ละหลักไม่ซ้ำกันเลย มีทั้งหมดกี่จำนวน","choices":["320","360","450","328"],"answer":3,"explanation":{"en":"Split by the units digit. Units 0: hundreds 9 ways (1–9), tens 8 ways → 72. Units 2, 4, 6 or 8 (4 ways): hundreds cannot be 0 or the units digit → 8 ways, tens 8 ways → 4 × 64 = 256. Total 72 + 256 = 328. (360 ignores the zero problem; 450 allows repeated digits.)","th":"แยกกรณีตามหลักหน่วย กรณีหลักหน่วยเป็น 0: หลักร้อยเลือกได้ 9 แบบ (1–9) หลักสิบ 8 แบบ ได้ 72 จำนวน กรณีหลักหน่วยเป็น 2, 4, 6, 8 (4 แบบ): หลักร้อยห้ามเป็น 0 และห้ามซ้ำหลักหน่วย เหลือ 8 แบบ หลักสิบ 8 แบบ ได้ 4 × 64 = 256 จำนวน รวม 72 + 256 = 328 จำนวน (360 เกิดจากไม่แยกกรณีเลข 0 ส่วน 450 คือจำนวนคู่สามหลักทั้งหมดเมื่อยอมให้เลขซ้ำ)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"m","skill":{"en":"Logical deduction","th":"การให้เหตุผลเชิงตรรกะ"},"topic":{"en":"Logical reasoning and counting","th":"การให้เหตุผลและการนับ"},"passage":"","table":null,"lang":"th","stem":"เพื่อน 5 คน คือ ก ข ค ง และ จ สูงไม่เท่ากันเลย ก สูงกว่า ข, ค เตี้ยกว่า ง แต่สูงกว่า ก และ จ เตี้ยที่สุดในกลุ่ม ใครสูงเป็นอันดับที่สาม","choices":["ข","ค","ง","ก"],"answer":3,"explanation":{"en":"From the clues: D (ง) is taller than C (ค), C is taller than A (ก), A is taller than B (ข), and E (จ) is shortest. The order from tallest is ง, ค, ก, ข, จ, so ก is third.","th":"จากเงื่อนไข ง สูงกว่า ค, ค สูงกว่า ก, ก สูงกว่า ข และ จ เตี้ยที่สุด เรียงจากสูงไปเตี้ยได้ ง ค ก ข จ ผู้ที่สูงเป็นอันดับสามคือ ก"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"e","skill":{"en":"Accurate computation","th":"การคำนวณอย่างแม่นยำ"},"topic":{"en":"Percentage and profit–loss","th":"ร้อยละและกำไรขาดทุน"},"passage":"","table":null,"lang":"en","stem":"What is 15% of 240 added to 2/3 of 45?","choices":["56","69","76","66"],"answer":3,"explanation":{"en":"15% of 240 = 0.15 × 240 = 36, and 2/3 of 45 = 30. 36 + 30 = 66.","th":"15% ของ 240 = 0.15 × 240 = 36 และ 2/3 ของ 45 = 30 รวมกันได้ 36 + 30 = 66"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"m","skill":{"en":"Geometric reasoning","th":"การให้เหตุผลทางเรขาคณิต"},"topic":{"en":"Plane geometry and angles","th":"เรขาคณิตและมุม"},"passage":"","table":null,"lang":"en","stem":"The three angles of a triangle are in the ratio 2 : 3 : 7. How big is the largest angle?","choices":["105°","70°","84°","120°"],"answer":0,"explanation":{"en":"The angles add up to 180°, and 2 + 3 + 7 = 12 parts, so one part is 15°. The largest angle is 7 × 15° = 105°. (This makes the triangle obtuse.)","th":"มุมภายในรวม 180° แบ่งเป็น 2 + 3 + 7 = 12 ส่วน ส่วนละ 15° มุมที่ใหญ่ที่สุด = 7 × 15° = 105° (เป็นสามเหลี่ยมมุมป้าน)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"h","skill":{"en":"Multi-step problem solving","th":"การแก้โจทย์ปัญหาหลายขั้นตอน"},"topic":{"en":"Area, perimeter and volume","th":"พื้นที่ ความยาวรอบรูป และปริมาตร"},"passage":"","table":null,"lang":"en","stem":"A cylindrical water tank has a radius of 35 cm and a height of 80 cm. It is 3/4 full. How many litres of water are in the tank? (Use π ≈ 22/7 and 1 litre = 1,000 cm³.)","choices":["77 litres","308 litres","2,310 litres","231 litres"],"answer":3,"explanation":{"en":"Full volume = πr²h = 22/7 × 35 × 35 × 80 = 308,000 cm³ = 308 litres. Three quarters of that is 231 litres. (308 litres is the full tank; 77 litres is the empty quarter.)","th":"ปริมาตรถังเต็ม = πr²h = 22/7 × 35 × 35 × 80 = 308,000 ลบ.ซม. = 308 ลิตร น้ำ 3/4 ถัง = 231 ลิตร (308 ลิตรคือถังเต็ม ส่วน 77 ลิตรคือส่วนที่ยังว่าง)"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"e","skill":{"en":"Accurate computation","th":"การคำนวณอย่างแม่นยำ"},"topic":{"en":"Percentage and profit–loss","th":"ร้อยละและกำไรขาดทุน"},"passage":"","table":null,"lang":"en","stem":"The price of a shirt goes up by 20%. Later the new price goes down by 20%. How does the final price compare with the original price?","choices":["It is the same.","It is 4% higher.","It is 2% lower.","It is 4% lower."],"answer":3,"explanation":{"en":"Take the original price as 100. After +20% it is 120; 20% of 120 is 24, so the final price is 96 — 4% lower than at the start. The decrease is larger because it is taken from a bigger number.","th":"ให้ราคาเดิม 100 บาท เพิ่ม 20% เป็น 120 บาท แล้วลด 20% ของ 120 คือ 24 บาท เหลือ 96 บาท จึงต่ำกว่าราคาเดิม 4% เพราะการลดคิดจากฐานที่ใหญ่กว่า"}},{"kind":"m1","program":"satit","subject":"math","format":"mcq","difficulty":"h","skill":{"en":"Systematic counting","th":"การนับอย่างเป็นระบบ"},"topic":{"en":"Logical reasoning and counting","th":"การให้เหตุผลและการนับ"},"passage":"","table":null,"lang":"en","stem":"How many whole numbers from 1 to 200 are divisible by 3 or by 5, but NOT by 15?","choices":["67","80","93","106"],"answer":1,"explanation":{"en":"Multiples of 3: 66. Multiples of 5: 40. Multiples of 15 (counted in both): 13. Divisible by 3 or 5: 66 + 40 − 13 = 93. Removing the 13 multiples of 15 leaves 93 − 13 = 80.","th":"พหุคูณของ 3 มี 66 จำนวน พหุคูณของ 5 มี 40 จำนวน พหุคูณของ 15 (นับซ้ำ) มี 13 จำนวน หารด้วย 3 หรือ 5 ลงตัว = 66 + 40 − 13 = 93 จำนวน ตัดพหุคูณของ 15 ออกอีก 13 จำนวน เหลือ 80 จำนวน"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"e","skill":{"en":"Identifying variables","th":"การระบุตัวแปร"},"topic":{"en":"Scientific process skills","th":"ทักษะกระบวนการทางวิทยาศาสตร์"},"passage":"นักเรียนกลุ่มหนึ่งปลูกต้นถั่วเขียวที่งอกแล้วและสูงเท่ากันลงในกระถาง 4 ใบ กระถางละ 1 ต้น ใช้ดินชนิดเดียวกันปริมาณเท่ากัน วางไว้ริมหน้าต่างเดียวกัน แล้วรดน้ำต่างกันทุกวันเป็นเวลา 7 วัน จากนั้นวัดความสูงที่เพิ่มขึ้นของต้นถั่ว ได้ผลดังตาราง","table":{"title":"ความสูงที่เพิ่มขึ้นของต้นถั่วเขียวใน 7 วัน","rows":[["กระถาง","1","2","3","4"],["น้ำที่รดต่อวัน (mL)","10","20","30","40"],["ความสูงที่เพิ่มขึ้น (cm)","4.1","6.8","7.2","3.5"]]},"lang":"th","stem":"ตัวแปรต้นของการทดลองนี้คือข้อใด","choices":["ความสูงที่เพิ่มขึ้นของต้นถั่ว","ชนิดของดินที่ใช้ปลูก","ระยะเวลา 7 วันที่ทดลอง","ปริมาณน้ำที่รดต่อวัน"],"answer":3,"explanation":{"en":"The independent variable is what the students deliberately changed: the volume of water given each day (10–40 mL). Height gained is the dependent variable; soil type and the 7-day period are kept the same (controlled).","th":"ตัวแปรต้นคือสิ่งที่ผู้ทดลองตั้งใจเปลี่ยน คือปริมาณน้ำที่รดต่อวัน (10–40 mL) ความสูงที่เพิ่มขึ้นเป็นตัวแปรตาม ส่วนชนิดดินและระยะเวลา 7 วันเป็นตัวแปรควบคุม"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Identifying variables","th":"การระบุตัวแปร"},"topic":{"en":"Scientific process skills","th":"ทักษะกระบวนการทางวิทยาศาสตร์"},"passage":"นักเรียนกลุ่มหนึ่งปลูกต้นถั่วเขียวที่งอกแล้วและสูงเท่ากันลงในกระถาง 4 ใบ กระถางละ 1 ต้น ใช้ดินชนิดเดียวกันปริมาณเท่ากัน วางไว้ริมหน้าต่างเดียวกัน แล้วรดน้ำต่างกันทุกวันเป็นเวลา 7 วัน จากนั้นวัดความสูงที่เพิ่มขึ้นของต้นถั่ว ได้ผลดังตาราง","table":{"title":"ความสูงที่เพิ่มขึ้นของต้นถั่วเขียวใน 7 วัน","rows":[["กระถาง","1","2","3","4"],["น้ำที่รดต่อวัน (mL)","10","20","30","40"],["ความสูงที่เพิ่มขึ้น (cm)","4.1","6.8","7.2","3.5"]]},"lang":"th","stem":"ข้อใดเป็นตัวแปรควบคุมของการทดลองนี้ทั้งหมด","choices":["ปริมาณน้ำที่รด และชนิดของดิน","ความสูงของต้นถั่ว และปริมาณดิน","ตำแหน่งที่วางกระถาง และความสูงที่เพิ่มขึ้น","ชนิดของดิน ปริมาณดิน และตำแหน่งที่วางกระถาง"],"answer":3,"explanation":{"en":"Controlled variables are the conditions kept the same in every pot: soil type, amount of soil and the window position (light). Water volume is the independent variable and height gained is the dependent variable, so any group containing them is wrong.","th":"ตัวแปรควบคุมคือสิ่งที่ทำให้เหมือนกันทุกกระถาง ได้แก่ ชนิดของดิน ปริมาณดิน และตำแหน่งที่วาง (แสง) ส่วนปริมาณน้ำเป็นตัวแปรต้น และความสูงที่เพิ่มขึ้นเป็นตัวแปรตาม กลุ่มที่มีสองสิ่งนี้ปนอยู่จึงไม่ถูก"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Drawing conclusions from evidence","th":"การลงข้อสรุปจากหลักฐาน"},"topic":{"en":"Scientific process skills","th":"ทักษะกระบวนการทางวิทยาศาสตร์"},"passage":"นักเรียนกลุ่มหนึ่งปลูกต้นถั่วเขียวที่งอกแล้วและสูงเท่ากันลงในกระถาง 4 ใบ กระถางละ 1 ต้น ใช้ดินชนิดเดียวกันปริมาณเท่ากัน วางไว้ริมหน้าต่างเดียวกัน แล้วรดน้ำต่างกันทุกวันเป็นเวลา 7 วัน จากนั้นวัดความสูงที่เพิ่มขึ้นของต้นถั่ว ได้ผลดังตาราง","table":{"title":"ความสูงที่เพิ่มขึ้นของต้นถั่วเขียวใน 7 วัน","rows":[["กระถาง","1","2","3","4"],["น้ำที่รดต่อวัน (mL)","10","20","30","40"],["ความสูงที่เพิ่มขึ้น (cm)","4.1","6.8","7.2","3.5"]]},"lang":"th","stem":"ข้อสรุปใดสอดคล้องกับข้อมูลในตารางมากที่สุด","choices":["ยิ่งรดน้ำมากขึ้น ต้นถั่วยิ่งสูงขึ้นเสมอ","ต้นถั่วเจริญเติบโตได้ดีเมื่อได้รับน้ำประมาณ 20–30 mL ต่อวัน และน้ำที่มากเกินไปทำให้เจริญเติบโตลดลง","ปริมาณน้ำไม่มีผลต่อการเจริญเติบโตของต้นถั่ว","ต้นถั่วต้องได้รับน้ำ 40 mL ต่อวันจึงจะเจริญเติบโตได้"],"answer":1,"explanation":{"en":"Growth rises from 4.1 cm (10 mL) to 6.8 and 7.2 cm (20 and 30 mL) but falls to 3.5 cm at 40 mL. So the best growth is around 20–30 mL a day and too much water reduces growth. 'More water always means taller' is contradicted by the 40 mL pot.","th":"ความสูงเพิ่มจาก 4.1 cm (10 mL) เป็น 6.8 และ 7.2 cm (20 และ 30 mL) แต่ลดลงเหลือ 3.5 cm ที่ 40 mL จึงสรุปได้ว่าต้นถั่วเจริญดีเมื่อได้น้ำประมาณ 20–30 mL ต่อวัน และน้ำมากเกินไปทำให้เจริญลดลง ข้อที่ว่ายิ่งรดน้ำมากยิ่งสูงขัดกับผลของกระถางที่ 4"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Designing fair experiments","th":"การออกแบบการทดลองที่ยุติธรรม"},"topic":{"en":"Scientific process skills","th":"ทักษะกระบวนการทางวิทยาศาสตร์"},"passage":"นักเรียนกลุ่มหนึ่งปลูกต้นถั่วเขียวที่งอกแล้วและสูงเท่ากันลงในกระถาง 4 ใบ กระถางละ 1 ต้น ใช้ดินชนิดเดียวกันปริมาณเท่ากัน วางไว้ริมหน้าต่างเดียวกัน แล้วรดน้ำต่างกันทุกวันเป็นเวลา 7 วัน จากนั้นวัดความสูงที่เพิ่มขึ้นของต้นถั่ว ได้ผลดังตาราง","table":{"title":"ความสูงที่เพิ่มขึ้นของต้นถั่วเขียวใน 7 วัน","rows":[["กระถาง","1","2","3","4"],["น้ำที่รดต่อวัน (mL)","10","20","30","40"],["ความสูงที่เพิ่มขึ้น (cm)","4.1","6.8","7.2","3.5"]]},"lang":"th","stem":"ถ้าต้องการให้ผลการทดลองนี้น่าเชื่อถือมากขึ้น ควรปรับปรุงการทดลองอย่างไร","choices":["ใช้ดินต่างชนิดกันในแต่ละกระถางเพื่อให้ได้ข้อมูลหลากหลาย","ปลูกต้นถั่วหลายต้นในแต่ละชุดการทดลอง แล้วนำความสูงที่เพิ่มขึ้นมาหาค่าเฉลี่ย","วัดความสูงเฉพาะต้นที่สูงที่สุดในแต่ละกระถาง","ลดจำนวนชุดการทดลองให้เหลือเพียง 2 ชุด"],"answer":1,"explanation":{"en":"With only one plant per pot, one unusual seedling could change the result. Using several plants per treatment and averaging (repeating) reduces chance error. Changing the soil would add a second variable, measuring only the tallest plant is biased, and fewer treatments give less information.","th":"การใช้ต้นถั่วเพียง 1 ต้นต่อชุด ถ้าต้นนั้นผิดปกติผลจะคลาดเคลื่อน การปลูกหลายต้นในแต่ละชุดแล้วหาค่าเฉลี่ย (ทำซ้ำ) ช่วยลดความคลาดเคลื่อน ส่วนการเปลี่ยนชนิดดินเป็นการเพิ่มตัวแปรต้นอีกตัว การวัดเฉพาะต้นสูงสุดทำให้ข้อมูลลำเอียง และการลดชุดการทดลองทำให้ข้อมูลน้อยลง"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Forming hypotheses","th":"การตั้งสมมติฐาน"},"topic":{"en":"Scientific process skills","th":"ทักษะกระบวนการทางวิทยาศาสตร์"},"passage":"","table":null,"lang":"th","stem":"นักเรียนสงสัยว่า \"การเติมเกลือลงในน้ำมีผลต่ออุณหภูมิที่น้ำเริ่มเดือดหรือไม่\" สมมติฐานในข้อใดเหมาะสมที่สุด","choices":["เกลือสามารถละลายในน้ำได้ดีเมื่อน้ำร้อน","ถ้าเติมเกลือลงในน้ำมากขึ้น อุณหภูมิที่น้ำเริ่มเดือดจะสูงขึ้น","น้ำเกลือเป็นสารละลายที่มีรสเค็ม","น้ำบริสุทธิ์เดือดที่อุณหภูมิ 100 °C ที่ระดับน้ำทะเล"],"answer":1,"explanation":{"en":"A hypothesis is a testable prediction linking the independent variable (amount of salt) to the dependent variable (boiling temperature), usually in 'if … then …' form. The other statements may be true facts, but they do not predict how salt changes the boiling temperature.","th":"สมมติฐานคือคำตอบที่คาดไว้ล่วงหน้าซึ่งทดสอบได้ และเชื่อมตัวแปรต้น (ปริมาณเกลือ) กับตัวแปรตาม (อุณหภูมิที่น้ำเดือด) มักเขียนในรูป \"ถ้า … แล้ว …\" ข้อความอื่นอาจเป็นข้อเท็จจริง แต่ไม่ได้คาดคะเนผลของเกลือต่อจุดเดือด"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Predicting from patterns in data","th":"การพยากรณ์จากแนวโน้มของข้อมูล"},"topic":{"en":"Scientific process skills","th":"ทักษะกระบวนการทางวิทยาศาสตร์"},"passage":"นักเรียนผูกลูกตุ้มกับเชือกแล้วปล่อยให้แกว่ง จับเวลาที่ลูกตุ้มแกว่งครบ 10 รอบ โดยเปลี่ยนความยาวเชือกและมวลของลูกตุ้ม ปล่อยจากมุมเดียวกันทุกครั้ง ได้ผลดังตาราง","table":{"title":"เวลาที่ลูกตุ้มแกว่งครบ 10 รอบ","rows":[["ครั้งที่","1","2","3","4"],["ความยาวเชือก (cm)","25","50","100","100"],["มวลลูกตุ้ม (g)","50","50","50","100"],["เวลา 10 รอบ (s)","10.0","14.1","20.0","20.0"]]},"lang":"th","stem":"จากแนวโน้มของข้อมูล ถ้าต้องการให้ลูกตุ้มแกว่งครบ 10 รอบในเวลา 30 วินาที ควรใช้เชือกยาวประมาณเท่าใด","choices":["150 cm","200 cm","225 cm","300 cm"],"answer":2,"explanation":{"en":"Each time the string is made 4 times longer (25 → 100 cm) the time only doubles (10 → 20 s), so time grows with the square root of length. To go from 20 s to 30 s (× 1.5) the length must be multiplied by 1.5² = 2.25: 100 × 2.25 = 225 cm. 150 cm assumes time is proportional to length, which the data disproves (25 cm gave 10 s, not 5 s).","th":"เมื่อเชือกยาวขึ้น 4 เท่า (25 → 100 cm) เวลาเพิ่มเพียง 2 เท่า (10 → 20 s) แสดงว่าเวลาแปรตามรากที่สองของความยาว ต้องการให้เวลาเพิ่มจาก 20 s เป็น 30 s (1.5 เท่า) ความยาวต้องเพิ่ม 1.5² = 2.25 เท่า ได้ 100 × 2.25 = 225 cm ถ้าคิดว่าเวลาเป็นสัดส่วนตรงกับความยาวจะได้ 150 cm ซึ่งขัดกับข้อมูล (เชือก 25 cm ใช้เวลา 10 s ไม่ใช่ 5 s)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Drawing conclusions from evidence","th":"การลงข้อสรุปจากหลักฐาน"},"topic":{"en":"Scientific process skills","th":"ทักษะกระบวนการทางวิทยาศาสตร์"},"passage":"นักเรียนผูกลูกตุ้มกับเชือกแล้วปล่อยให้แกว่ง จับเวลาที่ลูกตุ้มแกว่งครบ 10 รอบ โดยเปลี่ยนความยาวเชือกและมวลของลูกตุ้ม ปล่อยจากมุมเดียวกันทุกครั้ง ได้ผลดังตาราง","table":{"title":"เวลาที่ลูกตุ้มแกว่งครบ 10 รอบ","rows":[["ครั้งที่","1","2","3","4"],["ความยาวเชือก (cm)","25","50","100","100"],["มวลลูกตุ้ม (g)","50","50","50","100"],["เวลา 10 รอบ (s)","10.0","14.1","20.0","20.0"]]},"lang":"th","stem":"ผลการทดลองครั้งที่ 3 และ 4 ใช้สรุปเรื่องใดได้","choices":["ลูกตุ้มที่หนักกว่าแกว่งเร็วกว่า","ความยาวเชือกไม่มีผลต่อเวลาที่ใช้แกว่ง","ลูกตุ้มที่เบากว่าแกว่งช้ากว่าเสมอ","มวลของลูกตุ้มไม่มีผลต่อเวลาที่ใช้แกว่ง"],"answer":3,"explanation":{"en":"Trials 3 and 4 have the same string length (100 cm) but different masses (50 g and 100 g), and both take 20.0 s. Only mass changed and the time did not, so mass does not affect the swing time. Length cannot be judged from these two trials because it was not changed.","th":"ครั้งที่ 3 และ 4 ใช้เชือกยาวเท่ากัน (100 cm) แต่มวลต่างกัน (50 g กับ 100 g) และใช้เวลาเท่ากัน 20.0 s เมื่อเปลี่ยนเฉพาะมวลแล้วเวลาไม่เปลี่ยน จึงสรุปได้ว่ามวลไม่มีผลต่อเวลาแกว่ง ส่วนผลของความยาวเชือกสรุปจากสองครั้งนี้ไม่ได้เพราะความยาวไม่ได้เปลี่ยน"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Scientific calculation","th":"การคำนวณทางวิทยาศาสตร์"},"topic":{"en":"Forces and motion","th":"แรงและการเคลื่อนที่"},"passage":"","table":null,"lang":"th","stem":"กล่องใบหนึ่งวางบนพื้น ถูกดึงไปทางขวาด้วยแรง 30 นิวตัน และถูกดึงไปทางซ้ายด้วยแรง 12 นิวตัน กล่องเคลื่อนที่ไปทางขวาโดยมีแรงเสียดทานระหว่างกล่องกับพื้น 6 นิวตัน แรงลัพธ์ที่กระทำต่อกล่องเป็นเท่าใด","choices":["18 นิวตัน ไปทางขวา","24 นิวตัน ไปทางขวา","12 นิวตัน ไปทางขวา","36 นิวตัน ไปทางซ้าย"],"answer":2,"explanation":{"en":"Friction always opposes the motion, so with the box moving right it acts to the left. Right: 30 N; left: 12 N + 6 N = 18 N. Resultant = 30 − 18 = 12 N to the right. (18 N ignores friction.)","th":"แรงเสียดทานมีทิศตรงข้ามกับการเคลื่อนที่ กล่องเคลื่อนที่ไปทางขวา แรงเสียดทานจึงมีทิศไปทางซ้าย แรงทางขวา 30 N แรงทางซ้าย 12 + 6 = 18 N แรงลัพธ์ = 30 − 18 = 12 N ไปทางขวา (18 N คือคำตอบเมื่อลืมแรงเสียดทาน)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Scientific calculation","th":"การคำนวณทางวิทยาศาสตร์"},"topic":{"en":"Forces and motion","th":"แรงและการเคลื่อนที่"},"passage":"","table":null,"lang":"th","stem":"ไม้กระดานหกสมดุลมีจุดหมุนอยู่ตรงกลาง เด็กหนัก 30 กิโลกรัมนั่งห่างจุดหมุน 2 เมตร และเด็กหนัก 20 กิโลกรัมนั่งข้างเดียวกันห่างจุดหมุน 1 เมตร เด็กหนัก 40 กิโลกรัมต้องนั่งอีกข้างหนึ่งห่างจุดหมุนกี่เมตร กระดานจึงจะสมดุล (ไม่คิดน้ำหนักของกระดาน)","choices":["1.5 เมตร","1.25 เมตร","2 เมตร","2.5 เมตร"],"answer":2,"explanation":{"en":"For balance, the turning effects (weight × distance) on each side must be equal. Left: 30 × 2 + 20 × 1 = 80. Right: 40 × d = 80, so d = 2 m. (1.5 m forgets the 20 kg child; 1.25 m adds the masses but not their distances correctly.)","th":"ไม้กระดานสมดุลเมื่อโมเมนต์ทวน = โมเมนต์ตาม (มวล × ระยะ) ข้างหนึ่ง: 30 × 2 + 20 × 1 = 80 อีกข้าง: 40 × d = 80 จะได้ d = 2 เมตร (1.5 เมตรคือคำตอบเมื่อลืมเด็กหนัก 20 กิโลกรัม)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Scientific calculation","th":"การคำนวณทางวิทยาศาสตร์"},"topic":{"en":"Forces and motion","th":"แรงและการเคลื่อนที่"},"passage":"","table":null,"lang":"th","stem":"นักวิ่งคนหนึ่งวิ่ง 300 เมตรแรกด้วยอัตราเร็วคงตัว 6 เมตร/วินาที แล้วเดินอีก 300 เมตรด้วยอัตราเร็วคงตัว 3 เมตร/วินาที อัตราเร็วเฉลี่ยตลอดระยะทาง 600 เมตรเป็นเท่าใด","choices":["4.5 เมตร/วินาที","4 เมตร/วินาที","3 เมตร/วินาที","5 เมตร/วินาที"],"answer":1,"explanation":{"en":"Average speed = total distance ÷ total time. Time for the first 300 m = 300 ÷ 6 = 50 s; for the second = 300 ÷ 3 = 100 s. 600 m ÷ 150 s = 4 m/s. 4.5 m/s is the trap of averaging the two speeds, which ignores that more time is spent at the slower speed.","th":"อัตราเร็วเฉลี่ย = ระยะทางทั้งหมด ÷ เวลาทั้งหมด ช่วงแรกใช้เวลา 300 ÷ 6 = 50 s ช่วงหลัง 300 ÷ 3 = 100 s รวม 150 s อัตราเร็วเฉลี่ย = 600 ÷ 150 = 4 m/s ส่วน 4.5 m/s เกิดจากการเอาอัตราเร็วสองค่ามาเฉลี่ยกัน ซึ่งผิดเพราะช่วงที่ช้าใช้เวลานานกว่า"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"e","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Forces and motion","th":"แรงและการเคลื่อนที่"},"passage":"","table":null,"lang":"th","stem":"ข้อใดเป็นการเพิ่มแรงเสียดทานเพื่อให้เกิดประโยชน์","choices":["การทำดอกยางให้ลึกบนยางรถยนต์","การใส่ลูกปืนในล้อจักรยาน","การหยอดน้ำมันหล่อลื่นที่บานพับประตู","การขัดพื้นลานโบว์ลิ่งให้เรียบลื่น"],"answer":0,"explanation":{"en":"Tyre treads make the surface rougher, increasing friction so the car grips the road and does not skid. Ball bearings, lubricating oil and polishing a floor all reduce friction.","th":"ดอกยางทำให้ผิวสัมผัสขรุขระ เพิ่มแรงเสียดทาน รถจึงยึดเกาะถนนได้ดีไม่ลื่นไถล ส่วนลูกปืน น้ำมันหล่อลื่น และการขัดพื้นให้เรียบ ล้วนเป็นการลดแรงเสียดทาน"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Scientific calculation","th":"การคำนวณทางวิทยาศาสตร์"},"topic":{"en":"Forces and motion","th":"แรงและการเคลื่อนที่"},"passage":"","table":null,"lang":"th","stem":"แขวนก้อนหินกับเครื่องชั่งสปริง อ่านค่าได้ 50 นิวตันในอากาศ เมื่อหย่อนก้อนหินให้จมมิดในน้ำทั้งก้อน อ่านค่าได้ 30 นิวตัน ก้อนหินมีปริมาตรกี่ลูกบาศก์เซนติเมตร (ให้น้ำมีความหนาแน่น 1,000 kg/m³ และ g = 10 m/s²)","choices":["3,000 ลูกบาศก์เซนติเมตร","2,000 ลูกบาศก์เซนติเมตร","5,000 ลูกบาศก์เซนติเมตร","200 ลูกบาศก์เซนติเมตร"],"answer":1,"explanation":{"en":"Buoyant force = loss in reading = 50 − 30 = 20 N. It equals the weight of water pushed aside: 20 N ÷ 10 = 2 kg of water, which has volume 2 kg ÷ 1,000 kg/m³ = 0.002 m³ = 2,000 cm³. Since the stone is fully under water, that is the stone's volume. (3,000 uses 30 N; 5,000 uses 50 N.)","th":"แรงลอยตัว = ค่าที่อ่านได้ลดลง = 50 − 30 = 20 N ซึ่งเท่ากับน้ำหนักของน้ำที่ถูกแทนที่ คิดเป็นมวลน้ำ 20 ÷ 10 = 2 kg ปริมาตร = 2 ÷ 1,000 = 0.002 m³ = 2,000 cm³ หินจมมิดทั้งก้อน ปริมาตรของหินจึงเท่ากับ 2,000 cm³ (3,000 คิดจาก 30 N และ 5,000 คิดจาก 50 N ซึ่งผิด)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Light and sound","th":"แสงและเสียง"},"passage":"","table":null,"lang":"th","stem":"ดาวยืนอยู่หน้ากระจกเงาราบห่าง 1.5 เมตร แล้วเดินตรงเข้าหากระจก 0.5 เมตร ขณะนี้ระยะระหว่างดาวกับภาพของตนเองในกระจกเป็นเท่าใด","choices":["1 เมตร","2 เมตร","3 เมตร","2.5 เมตร"],"answer":1,"explanation":{"en":"In a plane mirror the image is as far behind the mirror as the object is in front. After walking 0.5 m, Dao is 1.0 m from the mirror, so her image is 1.0 m behind it. Distance between Dao and her image = 1.0 + 1.0 = 2 m. (1 m is only the distance to the mirror; 3 m is the starting distance.)","th":"กระจกเงาราบให้ภาพอยู่หลังกระจกห่างเท่ากับวัตถุอยู่หน้ากระจก เมื่อเดินเข้าไป 0.5 m ดาวห่างกระจก 1.0 m ภาพจึงอยู่หลังกระจก 1.0 m ระยะจากดาวถึงภาพ = 1.0 + 1.0 = 2 m (1 m คือระยะถึงกระจกเท่านั้น ส่วน 3 m คือระยะก่อนเดิน)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Light and sound","th":"แสงและเสียง"},"passage":"","table":null,"lang":"th","stem":"ในเวลาเดียวกันของวันหนึ่ง เสาไฟสูง 3 เมตรทอดเงายาว 4.5 เมตร ส่วนต้นไม้ต้นหนึ่งที่อยู่ใกล้กันทอดเงายาว 12 เมตร ต้นไม้นี้สูงประมาณกี่เมตร","choices":["8 เมตร","6 เมตร","9 เมตร","18 เมตร"],"answer":0,"explanation":{"en":"Light travels in straight lines, so at the same moment height : shadow is the same for both objects. The pole's ratio is 3 : 4.5 = 2 : 3. The tree's height = 12 × 2/3 = 8 m. (18 m uses the ratio upside down.)","th":"แสงเดินทางเป็นเส้นตรง ในเวลาเดียวกันอัตราส่วนความสูงต่อความยาวเงาจึงเท่ากัน เสา 3 : 4.5 = 2 : 3 ต้นไม้สูง = 12 × 2/3 = 8 เมตร (18 เมตรเกิดจากกลับอัตราส่วน)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"e","skill":{"en":"Scientific calculation","th":"การคำนวณทางวิทยาศาสตร์"},"topic":{"en":"Light and sound","th":"แสงและเสียง"},"passage":"","table":null,"lang":"th","stem":"นักเรียนเห็นฟ้าแลบ แล้วอีก 4 วินาทีจึงได้ยินเสียงฟ้าร้อง ถ้าเสียงเคลื่อนที่ในอากาศด้วยอัตราเร็ว 340 เมตร/วินาที ฟ้าแลบเกิดขึ้นห่างจากนักเรียนประมาณเท่าใด","choices":["85 เมตร","340 เมตร","680 เมตร","1,360 เมตร"],"answer":3,"explanation":{"en":"Light arrives almost instantly, so the 4 s delay is the time the sound takes. Distance = speed × time = 340 × 4 = 1,360 m. (680 m would be an echo calculation, halving the distance.)","th":"แสงเดินทางเร็วมากจนถือว่ามาถึงทันที เวลา 4 วินาทีจึงเป็นเวลาที่เสียงใช้ ระยะทาง = อัตราเร็ว × เวลา = 340 × 4 = 1,360 เมตร (680 เมตรเป็นการหารสองแบบคิดเสียงสะท้อน ซึ่งไม่ใช่กรณีนี้)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Light and sound","th":"แสงและเสียง"},"passage":"","table":null,"lang":"th","stem":"นำขวดแก้วเหมือนกัน 3 ใบมาใส่น้ำในปริมาณต่างกัน แล้วทดลองทั้ง \"เป่าลมผ่านปากขวด\" และ \"ใช้ช้อนเคาะข้างขวด\" ข้อใดอธิบายผลได้ถูกต้อง","choices":["เมื่อเป่าปากขวด ขวดที่มีน้ำมากที่สุดให้เสียงต่ำที่สุด เพราะลำอากาศที่สั่นสั้นที่สุด","เมื่อเป่าปากขวด ขวดที่มีน้ำมากที่สุดให้เสียงสูงที่สุด เพราะลำอากาศที่สั่นสั้นที่สุด","เมื่อเคาะข้างขวด ขวดที่มีน้ำมากที่สุดให้เสียงสูงที่สุด เพราะขวดหนักที่สุด","ปริมาณน้ำไม่มีผลต่อระดับเสียง เพราะขวดทุกใบมีขนาดเท่ากัน"],"answer":1,"explanation":{"en":"When you blow, the air column vibrates: more water means a shorter air column, a higher frequency and a higher pitch. When you tap, the glass and water vibrate: more water makes the vibrating mass larger and slower, so the pitch is LOWER. That is why the 'tap — most water gives highest pitch' statement is wrong, and a shorter air column cannot give a lower pitch.","th":"เมื่อเป่า ลำอากาศในขวดเป็นตัวสั่น น้ำมากลำอากาศสั้น ความถี่สูง เสียงจึงสูง เมื่อเคาะ ขวดและน้ำเป็นตัวสั่น น้ำมากทำให้สั่นช้าลง เสียงจึงต่ำลง ข้อที่ว่าเคาะแล้วขวดน้ำมากเสียงสูงที่สุดจึงผิด และลำอากาศที่สั้นลงไม่ทำให้เสียงต่ำลง"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Interpreting data tables","th":"การตีความข้อมูลจากตาราง"},"topic":{"en":"Heat and temperature","th":"ความร้อนและอุณหภูมิ"},"passage":"","table":{"title":"อุณหภูมิของน้ำร้อน 200 mL (เริ่มต้น 80 °C)","rows":[["ภาชนะ","X (โลหะ)","Y (แก้ว)","Z (โฟมมีฝา)"],["หลัง 10 นาที (°C)","63","70","77"],["หลัง 20 นาที (°C)","52","61","74"]]},"lang":"th","stem":"นักเรียนเทน้ำร้อนปริมาณเท่ากันลงในภาชนะ 3 ชนิดที่มีขนาดเท่ากัน วางไว้ในห้องเดียวกัน แล้ววัดอุณหภูมิ ได้ผลดังตาราง ข้อใดสรุปได้ถูกต้อง","choices":["ภาชนะ Z เก็บความร้อนได้ดีที่สุด เพราะอุณหภูมิลดลงเพียง 6 °C ใน 20 นาที","ภาชนะ X เก็บความร้อนได้ดีที่สุด เพราะอุณหภูมิเปลี่ยนแปลงมากที่สุด","ภาชนะ Y นำความร้อนได้ดีที่สุด เพราะอุณหภูมิอยู่ตรงกลาง","ภาชนะทั้งสามชนิดเก็บความร้อนได้ใกล้เคียงกัน"],"answer":0,"explanation":{"en":"Z (foam with a lid) dropped only 80 → 74 °C, a 6 °C fall, while Y fell 19 °C and X fell 28 °C. The smallest drop means the least heat escaped, so Z is the best insulator. X lost the most heat, so it is the best conductor, not the best at keeping heat.","th":"ภาชนะ Z (โฟมมีฝา) อุณหภูมิลดจาก 80 เป็น 74 °C ลดเพียง 6 °C ขณะที่ Y ลด 19 °C และ X ลด 28 °C ภาชนะที่อุณหภูมิลดน้อยที่สุดสูญเสียความร้อนน้อยที่สุด จึงเป็นฉนวนที่ดีที่สุด ส่วน X สูญเสียความร้อนมากที่สุด แสดงว่านำความร้อนได้ดี ไม่ใช่เก็บความร้อนได้ดี"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Electricity and magnetism","th":"ไฟฟ้าและแม่เหล็ก"},"passage":"","table":null,"lang":"th","stem":"ต่อหลอดไฟเหมือนกัน 3 หลอดกับแบตเตอรี่ก้อนหนึ่ง โดยหลอด P และหลอด Q ต่อขนานกัน แล้วต่ออนุกรมกับหลอด R ข้อใดถูกต้อง","choices":["หลอด P และ Q สว่างกว่าหลอด R เพราะต่อขนานกัน","ทั้งสามหลอดสว่างเท่ากัน เพราะเป็นหลอดชนิดเดียวกัน","หลอด R สว่างที่สุด เพราะกระแสไฟฟ้าทั้งหมดผ่านหลอด R ก่อนแยกไปยังหลอด P และ Q","ถ้าหลอด P ขาด หลอด Q และ R จะดับทั้งคู่"],"answer":2,"explanation":{"en":"All the current from the battery passes through R; it then splits between P and Q, so each of them carries only half. More current means brighter, so R is brightest. If P breaks, current still flows through R and Q (Q actually gets brighter), so they do not both go out.","th":"กระแสไฟฟ้าทั้งหมดผ่านหลอด R แล้วจึงแบ่งไปยัง P และ Q คนละครึ่ง หลอด R มีกระแสผ่านมากที่สุดจึงสว่างที่สุด ถ้าหลอด P ขาด กระแสยังไหลผ่าน R และ Q ได้ (Q จะสว่างขึ้น) จึงไม่ดับทั้งคู่"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Scientific calculation","th":"การคำนวณทางวิทยาศาสตร์"},"topic":{"en":"Electricity and magnetism","th":"ไฟฟ้าและแม่เหล็ก"},"passage":"","table":null,"lang":"th","stem":"เครื่องปรับอากาศกำลังไฟฟ้า 1,500 วัตต์ เปิดใช้วันละ 8 ชั่วโมง เป็นเวลา 30 วัน ถ้าค่าไฟฟ้าหน่วยละ 4 บาท จะต้องจ่ายค่าไฟฟ้าเฉพาะเครื่องปรับอากาศนี้กี่บาท","choices":["360 บาท","1,200 บาท","1,440 บาท","14,400 บาท"],"answer":2,"explanation":{"en":"Energy in units (kWh) = power in kW × hours = 1.5 × 8 × 30 = 360 kWh. Cost = 360 × 4 = 1,440 baht. (360 is the number of units, not baht; 14,400 forgets to change watts into kilowatts properly.)","th":"พลังงานไฟฟ้า (หน่วย) = กำลังไฟฟ้า (กิโลวัตต์) × เวลา (ชั่วโมง) = 1.5 × 8 × 30 = 360 หน่วย ค่าไฟ = 360 × 4 = 1,440 บาท (360 คือจำนวนหน่วย ไม่ใช่ค่าไฟ)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"e","skill":{"en":"Classifying","th":"การจำแนกประเภท"},"topic":{"en":"Electricity and magnetism","th":"ไฟฟ้าและแม่เหล็ก"},"passage":"","table":null,"lang":"th","stem":"วัตถุใดถูกแม่เหล็กดูดได้","choices":["ช้อนอะลูมิเนียม","แหวนทองคำ","ลวดทองแดง","ตะปูเหล็ก"],"answer":3,"explanation":{"en":"Magnets attract magnetic materials such as iron, steel, nickel and cobalt. An iron nail is attracted; aluminium, gold and copper are metals but are not magnetic.","th":"แม่เหล็กดูดสารแม่เหล็ก เช่น เหล็ก เหล็กกล้า นิกเกิล โคบอลต์ ตะปูเหล็กจึงถูกดูด ส่วนอะลูมิเนียม ทองคำ และทองแดงเป็นโลหะแต่ไม่ใช่สารแม่เหล็ก"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Drawing conclusions from evidence","th":"การลงข้อสรุปจากหลักฐาน"},"topic":{"en":"Electricity and magnetism","th":"ไฟฟ้าและแม่เหล็ก"},"passage":"","table":{"title":"จำนวนลวดเสียบกระดาษที่แม่เหล็กไฟฟ้าดูดได้","rows":[["จำนวนรอบขดลวด","20","40","60","40"],["จำนวนถ่านไฟฉาย (ก้อน)","1","1","1","2"],["ลวดเสียบกระดาษ (ตัว)","5","10","15","19"]]},"lang":"th","stem":"นักเรียนพันลวดทองแดงรอบตะปูเหล็กแล้วต่อกับถ่านไฟฉาย บันทึกผลดังตาราง ข้อสรุปใดถูกต้องที่สุด","choices":["จำนวนรอบขดลวดเท่านั้นที่มีผลต่อแรงดูดของแม่เหล็กไฟฟ้า","การเพิ่มจำนวนถ่านไฟฉายทำให้แรงดูดลดลง","เมื่อจำนวนรอบเพิ่มเป็นสองเท่า จำนวนลวดเสียบกระดาษที่ดูดได้ลดลงครึ่งหนึ่ง","การเพิ่มจำนวนรอบขดลวดและการเพิ่มจำนวนถ่านไฟฉายต่างก็ทำให้แม่เหล็กไฟฟ้ามีแรงดูดมากขึ้น"],"answer":3,"explanation":{"en":"With 1 cell, 20 → 40 → 60 turns gives 5 → 10 → 15 clips: more turns, stronger magnet. With 40 turns, going from 1 to 2 cells raises 10 to 19 clips: more current, stronger magnet. So both factors increase the strength.","th":"เมื่อใช้ถ่าน 1 ก้อน เพิ่มรอบจาก 20 → 40 → 60 ดูดได้ 5 → 10 → 15 ตัว (รอบมาก แรงดูดมาก) และเมื่อใช้ 40 รอบ เพิ่มถ่านจาก 1 เป็น 2 ก้อน ดูดได้จาก 10 เป็น 19 ตัว (กระแสมาก แรงดูดมาก) จึงสรุปได้ว่าทั้งสองปัจจัยทำให้แรงดูดเพิ่มขึ้น"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"e","skill":{"en":"Classifying","th":"การจำแนกประเภท"},"topic":{"en":"Properties and changes of matter","th":"สมบัติและการเปลี่ยนแปลงของสาร"},"passage":"","table":null,"lang":"th","stem":"ข้อใดเป็นการเปลี่ยนแปลงทางเคมี","choices":["ก้อนน้ำแข็งละลายเป็นน้ำ","เกลือละลายในน้ำ","การบดเมล็ดกาแฟให้เป็นผง","ตะปูเหล็กที่ทิ้งไว้กลางแจ้งเกิดสนิม"],"answer":3,"explanation":{"en":"Rusting makes a new substance (iron oxide) with different properties, so it is a chemical change. Melting, dissolving and grinding change only the state, mixing or size — no new substance is formed.","th":"การเกิดสนิมได้สารใหม่ (สนิมเหล็ก) ที่มีสมบัติต่างจากเดิม จึงเป็นการเปลี่ยนแปลงทางเคมี ส่วนการละลายของน้ำแข็ง การละลายของเกลือ และการบดกาแฟ เปลี่ยนเพียงสถานะ การผสม หรือขนาด ไม่เกิดสารใหม่"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Scientific calculation","th":"การคำนวณทางวิทยาศาสตร์"},"topic":{"en":"Properties and changes of matter","th":"สมบัติและการเปลี่ยนแปลงของสาร"},"passage":"","table":{"title":"มวลและปริมาตรของวัตถุตัน 4 ชิ้น","rows":[["วัตถุ","P","Q","R","S"],["มวล (g)","30","54","45","57"],["ปริมาตร (cm³)","40","20","50","60"]]},"lang":"th","stem":"จากตาราง ถ้าน้ำมีความหนาแน่น 1.00 g/cm³ และน้ำมันพืชมีความหนาแน่น 0.92 g/cm³ วัตถุใดจมในน้ำมันพืชแต่ลอยในน้ำ","choices":["วัตถุ P","วัตถุ Q","วัตถุ R","วัตถุ S"],"answer":3,"explanation":{"en":"Density = mass ÷ volume: P = 0.75, Q = 2.7, R = 0.90, S = 0.95 g/cm³. An object sinks if it is denser than the liquid. S (0.95) is denser than oil (0.92) but less dense than water (1.00), so it sinks in oil and floats in water. P and R float in both; Q sinks in both.","th":"ความหนาแน่น = มวล ÷ ปริมาตร: P = 0.75, Q = 2.7, R = 0.90, S = 0.95 g/cm³ วัตถุจมเมื่อหนาแน่นกว่าของเหลว วัตถุ S (0.95) หนาแน่นกว่าน้ำมัน (0.92) แต่น้อยกว่าน้ำ (1.00) จึงจมในน้ำมันแต่ลอยในน้ำ ส่วน P และ R ลอยทั้งสองอย่าง และ Q จมทั้งสองอย่าง"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Interpreting data tables","th":"การตีความข้อมูลจากตาราง"},"topic":{"en":"Properties and changes of matter","th":"สมบัติและการเปลี่ยนแปลงของสาร"},"passage":"","table":{"title":"จุดหลอมเหลวและจุดเดือดของสาร 4 ชนิด","rows":[["สาร","จุดหลอมเหลว (°C)","จุดเดือด (°C)"],["A","−39","357"],["B","0","100"],["C","−114","78"],["D","801","1,413"]]},"lang":"th","stem":"จากตาราง ที่อุณหภูมิ 90 °C สารใดอยู่ในสถานะแก๊ส","choices":["สาร A","สาร B","สาร D","สาร C"],"answer":3,"explanation":{"en":"A substance is a gas above its boiling point. Only C boils below 90 °C (at 78 °C). A (boils at 357 °C) and B (boils at 100 °C) are liquids at 90 °C, and D is still a solid because it melts at 801 °C.","th":"สารจะเป็นแก๊สเมื่ออุณหภูมิสูงกว่าจุดเดือด มีเพียงสาร C ที่มีจุดเดือด 78 °C ต่ำกว่า 90 °C สาร A (เดือดที่ 357 °C) และ B (เดือดที่ 100 °C) ยังเป็นของเหลว ส่วนสาร D ยังเป็นของแข็งเพราะหลอมเหลวที่ 801 °C"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Interpreting data tables","th":"การตีความข้อมูลจากตาราง"},"topic":{"en":"Properties and changes of matter","th":"สมบัติและการเปลี่ยนแปลงของสาร"},"passage":"","table":{"title":"จุดหลอมเหลวและจุดเดือดของสาร 4 ชนิด","rows":[["สาร","จุดหลอมเหลว (°C)","จุดเดือด (°C)"],["A","−39","357"],["B","0","100"],["C","−114","78"],["D","801","1,413"]]},"lang":"th","stem":"จากตาราง ที่อุณหภูมิ −50 °C สารใดอยู่ในสถานะของเหลว","choices":["สาร A และสาร C","สาร A เพียงชนิดเดียว","สาร B และสาร C","สาร C เพียงชนิดเดียว"],"answer":3,"explanation":{"en":"A liquid lies between its melting and boiling points. At −50 °C: A melts at −39 °C, so it is still solid (the trap); B is solid; D is solid; C melts at −114 °C and boils at 78 °C, so it is liquid. Only C is liquid.","th":"สารเป็นของเหลวเมื่ออุณหภูมิอยู่ระหว่างจุดหลอมเหลวกับจุดเดือด ที่ −50 °C สาร A มีจุดหลอมเหลว −39 °C จึงยังเป็นของแข็ง (เป็นจุดหลอก) สาร B และ D เป็นของแข็ง ส่วนสาร C หลอมเหลวที่ −114 °C และเดือดที่ 78 °C จึงเป็นของเหลว มีเพียงสาร C ชนิดเดียว"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Designing fair experiments","th":"การออกแบบการทดลองที่ยุติธรรม"},"topic":{"en":"Mixtures and separation","th":"สารผสมและการแยกสาร"},"passage":"","table":null,"lang":"th","stem":"สารผสมประกอบด้วยเกลือแกง ทราย และผงเหล็ก ลำดับวิธีแยกในข้อใดเหมาะสมที่สุด เพื่อให้ได้สารทั้งสามชนิดแยกจากกัน","choices":["เติมน้ำแล้วระเหยแห้ง → ใช้แม่เหล็กดูดผงเหล็ก → กรองแยกทราย","กรองสารผสมแห้ง → ระเหยน้ำ → ใช้แม่เหล็กดูดผงเหล็ก","ใช้แม่เหล็กดูดผงเหล็ก → เติมน้ำให้เกลือละลายแล้วกรองแยกทราย → ระเหยน้ำออกจากสารละลายจะได้เกลือ","เติมน้ำแล้วกรอง → ใช้แม่เหล็กดูดผงเหล็กออกจากสารละลายเกลือ → ระเหยน้ำ"],"answer":2,"explanation":{"en":"Iron is the only magnetic part, so remove it first with a magnet while everything is dry. Then add water: salt dissolves but sand does not, so filtering leaves sand on the paper. Evaporating the filtrate gives back the salt. Evaporating before filtering would mix salt back with sand; filtering with water first traps the iron with the sand, not in the salt solution.","th":"ผงเหล็กเป็นสารแม่เหล็กเพียงชนิดเดียว จึงใช้แม่เหล็กดูดออกก่อนขณะยังแห้ง จากนั้นเติมน้ำ เกลือละลายแต่ทรายไม่ละลาย กรองจะได้ทรายบนกระดาษกรอง แล้วระเหยน้ำจากสารละลายที่ผ่านกระดาษกรองจะได้เกลือ ถ้าระเหยก่อนกรองเกลือจะกลับไปปนกับทราย และถ้าเติมน้ำแล้วกรองก่อน ผงเหล็กจะค้างอยู่กับทรายบนกระดาษกรอง ไม่ได้อยู่ในสารละลายเกลือ"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Interpreting data tables","th":"การตีความข้อมูลจากตาราง"},"topic":{"en":"Mixtures and separation","th":"สารผสมและการแยกสาร"},"passage":"","table":{"title":"ระยะทางที่จุดสีเคลื่อนที่บนกระดาษโครมาโทกราฟี (ตัวทำละลายเคลื่อนที่ 8.0 cm ทุกแผ่น)","rows":[["ตัวอย่าง","จุดสีที่พบ (ระยะจากจุดเริ่มต้น, cm)"],["สีผสม M","2.0 และ 4.5"],["สีมาตรฐาน P","2.0"],["สีมาตรฐาน Q","3.0"],["สีมาตรฐาน R","4.5"],["สีมาตรฐาน S","6.0"]]},"lang":"th","stem":"นักเรียนแยกสีผสม M และสีมาตรฐานด้วยโครมาโทกราฟีกระดาษ ภายใต้สภาวะเดียวกัน ได้ผลดังตาราง สีผสม M น่าจะประกอบด้วยสีมาตรฐานใด","choices":["สี Q และสี S","สี P และสี Q","สี P และสี R","สี P, Q, R และ S"],"answer":2,"explanation":{"en":"Under the same conditions each pure dye always travels the same distance (same Rf). M splits into spots at 2.0 cm and 4.5 cm, matching dye P (2.0 cm) and dye R (4.5 cm). Q (3.0 cm) and S (6.0 cm) do not appear in M.","th":"ภายใต้สภาวะเดียวกัน สารแต่ละชนิดเคลื่อนที่ได้ระยะเท่าเดิมเสมอ (ค่า Rf เท่ากัน) สีผสม M แยกเป็นจุดที่ 2.0 cm และ 4.5 cm ตรงกับสี P (2.0 cm) และสี R (4.5 cm) ส่วนสี Q (3.0 cm) และ S (6.0 cm) ไม่ปรากฏใน M"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Properties and changes of matter","th":"สมบัติและการเปลี่ยนแปลงของสาร"},"passage":"","table":{"title":"ค่า pH ของสารละลาย","rows":[["สารละลาย","น้ำมะนาว","น้ำกลั่น","น้ำสบู่","น้ำขี้เถ้า"],["pH","2","7","10","11"]]},"lang":"th","stem":"จากตาราง ข้อใดกล่าวถูกต้อง","choices":["น้ำกลั่นเปลี่ยนสีกระดาษลิตมัสจากสีแดงเป็นสีน้ำเงิน","น้ำมะนาวเปลี่ยนสีกระดาษลิตมัสจากสีน้ำเงินเป็นสีแดง","น้ำสบู่เป็นกรด เพราะมีค่า pH มากกว่า 7","น้ำขี้เถ้าเป็นกลาง เพราะได้มาจากธรรมชาติ"],"answer":1,"explanation":{"en":"pH below 7 is acidic, 7 is neutral, above 7 is basic. Lemon juice (pH 2) is an acid, and acids turn blue litmus red. Distilled water is neutral and changes neither litmus colour; soap water (pH 10) is a base, not an acid; ash water (pH 11) is basic — being 'natural' does not make it neutral.","th":"pH ต่ำกว่า 7 เป็นกรด เท่ากับ 7 เป็นกลาง สูงกว่า 7 เป็นเบส น้ำมะนาว (pH 2) เป็นกรด กรดเปลี่ยนลิตมัสสีน้ำเงินเป็นสีแดง น้ำกลั่นเป็นกลางจึงไม่เปลี่ยนสีลิตมัส น้ำสบู่ (pH 10) เป็นเบสไม่ใช่กรด และน้ำขี้เถ้า (pH 11) เป็นเบส การได้มาจากธรรมชาติไม่ได้ทำให้เป็นกลาง"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"e","skill":{"en":"Classifying","th":"การจำแนกประเภท"},"topic":{"en":"Cells and living things","th":"เซลล์และสิ่งมีชีวิต"},"passage":"","table":null,"lang":"th","stem":"โครงสร้างใดพบในเซลล์พืช แต่ไม่พบในเซลล์สัตว์","choices":["เยื่อหุ้มเซลล์","ผนังเซลล์","นิวเคลียส","ไซโทพลาซึม"],"answer":1,"explanation":{"en":"Plant cells have a cell wall (and chloroplasts and a large vacuole) that animal cells lack. Both plant and animal cells have a cell membrane, a nucleus and cytoplasm.","th":"เซลล์พืชมีผนังเซลล์ (รวมทั้งคลอโรพลาสต์และแวคิวโอลขนาดใหญ่) ซึ่งเซลล์สัตว์ไม่มี ส่วนเยื่อหุ้มเซลล์ นิวเคลียส และไซโทพลาซึมพบทั้งในเซลล์พืชและเซลล์สัตว์"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Scientific calculation","th":"การคำนวณทางวิทยาศาสตร์"},"topic":{"en":"Cells and living things","th":"เซลล์และสิ่งมีชีวิต"},"passage":"","table":null,"lang":"th","stem":"นักเรียนส่องเซลล์ด้วยกล้องจุลทรรศน์ที่ใช้เลนส์ใกล้ตากำลังขยาย 10× และเลนส์ใกล้วัตถุ 40× ภาพเซลล์ที่มองเห็นมีขนาดเทียบได้ 8 มิลลิเมตร เซลล์จริงมีขนาดประมาณเท่าใด","choices":["2 ไมโครเมตร","20 ไมโครเมตร","80 ไมโครเมตร","200 ไมโครเมตร"],"answer":1,"explanation":{"en":"Total magnification = 10 × 40 = 400×. Real size = image size ÷ magnification = 8 mm ÷ 400 = 0.02 mm. 1 mm = 1,000 µm, so 0.02 mm = 20 µm. (200 µm divides by 40 only; 80 µm forgets to multiply the two lenses.)","th":"กำลังขยายรวม = 10 × 40 = 400 เท่า ขนาดจริง = ขนาดภาพ ÷ กำลังขยาย = 8 mm ÷ 400 = 0.02 mm และ 1 mm = 1,000 ไมโครเมตร จึงได้ 20 ไมโครเมตร (200 ไมโครเมตรคือการหารด้วย 40 อย่างเดียว)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Drawing conclusions from evidence","th":"การลงข้อสรุปจากหลักฐาน"},"topic":{"en":"Plants and photosynthesis","th":"พืชและการสังเคราะห์ด้วยแสง"},"passage":"","table":null,"lang":"th","stem":"นำใบไม้ด่างที่มีทั้งส่วนสีเขียวและส่วนสีขาว ซึ่งได้รับแสงตลอดวัน มาสกัดคลอโรฟิลล์ออกแล้วหยดสารละลายไอโอดีน พบว่าเฉพาะบริเวณที่เคยเป็นสีเขียวเปลี่ยนเป็นสีน้ำเงินเข้ม ข้อสรุปใดถูกต้องที่สุด","choices":["แสงจำเป็นต่อการสร้างแป้งของพืช","ส่วนสีขาวของใบสร้างแป้งได้มากกว่าส่วนสีเขียว","สารละลายไอโอดีนทำลายคลอโรฟิลล์ในใบไม้","คลอโรฟิลล์จำเป็นต่อการสร้างแป้งของพืช"],"answer":3,"explanation":{"en":"Iodine turns blue-black where there is starch. The whole leaf got the same light, but only the green (chlorophyll-containing) parts made starch, so the variable tested is chlorophyll. Light was not varied, so this experiment cannot conclude that light is needed.","th":"ไอโอดีนเปลี่ยนเป็นสีน้ำเงินเข้มเมื่อมีแป้ง ใบทั้งใบได้รับแสงเท่ากัน แต่มีแป้งเฉพาะส่วนสีเขียวที่มีคลอโรฟิลล์ ตัวแปรที่ต่างกันจึงเป็นคลอโรฟิลล์ ส่วนแสงไม่ได้ถูกเปลี่ยน จึงสรุปเรื่องความจำเป็นของแสงจากการทดลองนี้ไม่ได้"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Drawing conclusions from evidence","th":"การลงข้อสรุปจากหลักฐาน"},"topic":{"en":"Plants and photosynthesis","th":"พืชและการสังเคราะห์ด้วยแสง"},"passage":"","table":{"title":"จำนวนฟองแก๊สจากสาหร่ายหางกระรอกต่อนาที","rows":[["ระยะจากหลอดไฟ (cm)","10","20","30","40"],["ฟองแก๊สต่อนาที","40","24","12","5"]]},"lang":"th","stem":"นำสาหร่ายหางกระรอกใส่ในบีกเกอร์น้ำ วางห่างจากหลอดไฟในระยะต่าง ๆ ในห้องมืด นับฟองแก๊สที่เกิดขึ้น ได้ผลดังตาราง ข้อใดอธิบายได้ถูกต้องที่สุด","choices":["ฟองแก๊สส่วนใหญ่เป็นแก๊สออกซิเจน และอัตราการสังเคราะห์ด้วยแสงลดลงเมื่อพืชได้รับแสงน้อยลง","ฟองแก๊สส่วนใหญ่เป็นแก๊สคาร์บอนไดออกไซด์ และอัตราการสังเคราะห์ด้วยแสงลดลงเมื่อได้รับแสงน้อยลง","ฟองแก๊สส่วนใหญ่เป็นแก๊สออกซิเจน และอัตราการสังเคราะห์ด้วยแสงเพิ่มขึ้นเมื่อหลอดไฟอยู่ไกลขึ้น","ระยะห่างจากหลอดไฟไม่มีผลต่อการสังเคราะห์ด้วยแสง เพราะสาหร่ายอยู่ในน้ำ"],"answer":0,"explanation":{"en":"Photosynthesis releases oxygen, so the bubbles are mainly oxygen. Moving the lamp from 10 to 40 cm lowers the light reaching the plant and the bubbles fall from 40 to 5 per minute, so the rate drops as light decreases. Carbon dioxide is taken in, not given off, during photosynthesis.","th":"การสังเคราะห์ด้วยแสงปล่อยแก๊สออกซิเจน ฟองแก๊สจึงเป็นออกซิเจนเป็นส่วนใหญ่ เมื่อเลื่อนหลอดไฟจาก 10 เป็น 40 cm แสงที่ได้รับน้อยลง ฟองแก๊สลดจาก 40 เหลือ 5 ฟองต่อนาที แสดงว่าอัตราการสังเคราะห์ด้วยแสงลดลงเมื่อแสงน้อยลง ส่วนคาร์บอนไดออกไซด์เป็นแก๊สที่พืชใช้ ไม่ใช่แก๊สที่ปล่อยออกมา"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Recalling key concepts","th":"ความเข้าใจมโนทัศน์พื้นฐาน"},"topic":{"en":"Human body systems","th":"ระบบร่างกายมนุษย์"},"passage":"","table":null,"lang":"th","stem":"เลือดที่ออกจากหัวใจห้องล่างขวาจะไหลไปที่ใดเป็นอันดับแรก","choices":["สมอง","หัวใจห้องบนซ้าย","ปอด","ทุกส่วนของร่างกาย"],"answer":2,"explanation":{"en":"The right ventricle pumps deoxygenated blood along the pulmonary artery to the lungs to pick up oxygen. The oxygen-rich blood then returns to the left atrium, and the left ventricle sends it to the rest of the body.","th":"หัวใจห้องล่างขวาสูบฉีดเลือดที่มีออกซิเจนต่ำผ่านหลอดเลือดอาร์เตอรีไปยังปอดเพื่อรับออกซิเจน แล้วเลือดจึงกลับเข้าหัวใจห้องบนซ้าย และห้องล่างซ้ายส่งเลือดไปทั่วร่างกาย"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Drawing conclusions from evidence","th":"การลงข้อสรุปจากหลักฐาน"},"topic":{"en":"Human body systems","th":"ระบบร่างกายมนุษย์"},"passage":"","table":{"title":"ผลการทดสอบด้วยสารละลายไอโอดีนหลัง 20 นาที","rows":[["หลอด","สิ่งที่ใส่","อุณหภูมิ","สีเมื่อหยดไอโอดีน"],["1","น้ำแป้ง + น้ำลาย","37 °C","ไม่เปลี่ยนเป็นสีน้ำเงินเข้ม"],["2","น้ำแป้ง + น้ำลายที่ต้มเดือดแล้วทำให้เย็น","37 °C","สีน้ำเงินเข้ม"],["3","น้ำแป้ง + น้ำกลั่น","37 °C","สีน้ำเงินเข้ม"],["4","น้ำแป้ง + น้ำลาย","0 °C","สีน้ำเงินเข้ม"]]},"lang":"th","stem":"จากผลการทดลองในตาราง ข้อสรุปใดถูกต้องที่สุด","choices":["เอนไซม์ในน้ำลายย่อยแป้งได้ที่ 37 °C แต่ย่อยไม่ได้หรือย่อยได้น้อยมากเมื่อถูกต้มเดือดหรืออยู่ที่ 0 °C","น้ำกลั่นย่อยแป้งได้เช่นเดียวกับน้ำลาย","อุณหภูมิไม่มีผลต่อการย่อยแป้งของน้ำลาย","หลอดที่ 3 ไม่จำเป็นต้องมีในการทดลองนี้"],"answer":0,"explanation":{"en":"Blue-black means starch is still present. Only tube 1 (saliva at 37 °C) lost its starch. Tube 2 shows boiling destroys the enzyme, tube 4 shows the enzyme hardly works at 0 °C, and tube 3 is the control showing water alone does not digest starch — so tube 3 is needed.","th":"สีน้ำเงินเข้มแสดงว่ายังมีแป้งอยู่ มีเพียงหลอด 1 (น้ำลาย 37 °C) ที่แป้งถูกย่อยหมด หลอด 2 แสดงว่าการต้มทำให้เอนไซม์เสียสภาพ หลอด 4 แสดงว่าที่ 0 °C เอนไซม์ทำงานได้น้อยมาก และหลอด 3 เป็นชุดควบคุมที่แสดงว่าน้ำกลั่นย่อยแป้งไม่ได้ จึงจำเป็นต้องมี"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Ecosystems and food webs","th":"ระบบนิเวศและโซ่อาหาร"},"passage":"ในนาข้าวแห่งหนึ่งมีความสัมพันธ์ในการกินดังนี้ ตั๊กแตนและหนูกินต้นข้าว กบกินตั๊กแตน งูกินกบและหนู ส่วนเหยี่ยวกินงูและหนู","table":null,"lang":"th","stem":"ถ้ากบในนาข้าวนี้ถูกจับไปจนเกือบหมด ผลใดน่าจะเกิดขึ้นเป็นอันดับแรก","choices":["จำนวนหนูลดลง","จำนวนตั๊กแตนเพิ่มขึ้น","จำนวนเหยี่ยวเพิ่มขึ้น","จำนวนต้นข้าวเพิ่มขึ้น"],"answer":1,"explanation":{"en":"Frogs are the only predator of grasshoppers in this web, so removing frogs first lets grasshoppers increase. More grasshoppers would then eat more rice, so rice is more likely to decrease, not increase. Snakes may later eat more mice, but that is a later, indirect effect.","th":"ในสายใยอาหารนี้ กบเป็นผู้ล่าตั๊กแตนเพียงชนิดเดียว เมื่อกบหายไป ผลแรกคือตั๊กแตนเพิ่มขึ้น ตั๊กแตนที่มากขึ้นจะกินข้าวมากขึ้น ต้นข้าวจึงมีแนวโน้มลดลง ไม่ใช่เพิ่มขึ้น ส่วนการที่งูหันไปกินหนูมากขึ้นเป็นผลทางอ้อมที่เกิดตามมาภายหลัง"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Scientific calculation","th":"การคำนวณทางวิทยาศาสตร์"},"topic":{"en":"Ecosystems and food webs","th":"ระบบนิเวศและโซ่อาหาร"},"passage":"ในนาข้าวแห่งหนึ่งมีความสัมพันธ์ในการกินดังนี้ ตั๊กแตนและหนูกินต้นข้าว กบกินตั๊กแตน งูกินกบและหนู ส่วนเหยี่ยวกินงูและหนู","table":null,"lang":"th","stem":"ในโซ่อาหาร ต้นข้าว → ตั๊กแตน → กบ → งู ถ้าต้นข้าวมีพลังงาน 50,000 กิโลจูล และพลังงานถ่ายทอดไปยังผู้บริโภคลำดับถัดไปได้ประมาณร้อยละ 10 งูจะได้รับพลังงานประมาณเท่าใด","choices":["5 กิโลจูล","500 กิโลจูล","5,000 กิโลจูล","50 กิโลจูล"],"answer":3,"explanation":{"en":"Only about 10% passes to each next level: grasshopper 5,000 kJ, frog 500 kJ, snake 50 kJ. The snake is three steps from the rice, so divide by 10 three times. (500 kJ is the frog's share.)","th":"พลังงานถ่ายทอดได้ประมาณ 10% ในแต่ละลำดับ ตั๊กแตนได้ 5,000 kJ กบได้ 500 kJ งูได้ 50 kJ งูอยู่ห่างจากต้นข้าว 3 ลำดับ จึงหารด้วย 10 สามครั้ง (500 kJ คือพลังงานของกบ)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Heredity and classification","th":"การถ่ายทอดลักษณะและการจำแนกสิ่งมีชีวิต"},"passage":"","table":null,"lang":"th","stem":"ลักษณะต้นสูงของถั่วชนิดหนึ่งเป็นลักษณะเด่น (T) และต้นเตี้ยเป็นลักษณะด้อย (t) ถ้านำต้นสูงพันธุ์ทาง (Tt) ผสมกับต้นสูงพันธุ์ทาง (Tt) แล้วได้ต้นลูก 400 ต้น จะมีต้นเตี้ยประมาณกี่ต้น","choices":["0 ต้น","200 ต้น","100 ต้น","300 ต้น"],"answer":2,"explanation":{"en":"Tt × Tt gives TT : Tt : tt in the ratio 1 : 2 : 1. Only tt plants are short, which is 1/4 of the offspring: 400 × 1/4 = 100 plants. (300 is the number of tall plants.)","th":"Tt × Tt ได้ลูก TT : Tt : tt = 1 : 2 : 1 ต้นเตี้ยต้องเป็น tt เท่านั้น คิดเป็น 1/4 ของลูก = 400 × 1/4 = 100 ต้น (300 ต้นคือจำนวนต้นสูง)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"e","skill":{"en":"Classifying","th":"การจำแนกประเภท"},"topic":{"en":"Heredity and classification","th":"การถ่ายทอดลักษณะและการจำแนกสิ่งมีชีวิต"},"passage":"","table":null,"lang":"th","stem":"ข้อใดจัดกลุ่มสัตว์ไม่ถูกต้อง","choices":["เพนกวิน — นก","วาฬ — ปลา","ค้างคาว — สัตว์เลี้ยงลูกด้วยน้ำนม","เต่า — สัตว์เลื้อยคลาน"],"answer":1,"explanation":{"en":"A whale lives in water but breathes air with lungs, gives birth to live young and feeds them milk, so it is a mammal, not a fish. Penguins are birds (feathers, eggs), bats are mammals and turtles are reptiles.","th":"วาฬอาศัยในน้ำแต่หายใจด้วยปอด ออกลูกเป็นตัว และเลี้ยงลูกด้วยน้ำนม จึงเป็นสัตว์เลี้ยงลูกด้วยน้ำนม ไม่ใช่ปลา ส่วนเพนกวินเป็นนก (มีขนนก ออกไข่) ค้างคาวเป็นสัตว์เลี้ยงลูกด้วยน้ำนม และเต่าเป็นสัตว์เลื้อยคลาน"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Earth, weather and the water cycle","th":"โลก ลมฟ้าอากาศ และวัฏจักรน้ำ"},"passage":"","table":null,"lang":"th","stem":"ชาวประมงชายฝั่งนิยมออกเรือไปทะเลในตอนกลางคืนหรือเช้ามืด เพราะได้อาศัยลมช่วยพัดเรือออกจากฝั่ง ข้อใดอธิบายปรากฏการณ์นี้ได้ถูกต้อง","choices":["กลางคืนพื้นดินคายความร้อนเร็วกว่าน้ำ อากาศเหนือทะเลอุ่นกว่าและลอยตัวขึ้น ลมจึงพัดจากฝั่งออกสู่ทะเล","กลางคืนพื้นดินร้อนกว่าน้ำ อากาศเหนือฝั่งลอยตัวขึ้น ลมจึงพัดจากทะเลเข้าหาฝั่ง","กลางคืนน้ำทะเลเย็นกว่าพื้นดิน ลมจึงพัดจากฝั่งออกสู่ทะเล","ลมบกเกิดจากการที่ดวงจันทร์ดึงดูดอากาศเหนือทะเลในเวลากลางคืน"],"answer":0,"explanation":{"en":"At night land loses heat faster than water, so the air over the sea is warmer, rises and creates lower pressure there. Cooler, denser air over the land flows out to sea — the land breeze that carries boats out. The other statements get the temperatures backwards or give an unrelated cause.","th":"กลางคืนพื้นดินคายความร้อนได้เร็วกว่าน้ำ อากาศเหนือทะเลจึงอุ่นกว่า ลอยตัวขึ้น ความกดอากาศเหนือทะเลต่ำลง อากาศเย็นเหนือฝั่งจึงเคลื่อนออกไปแทนที่ เกิดลมบกพัดเรือออกสู่ทะเล ข้ออื่นสลับอุณหภูมิของดินกับน้ำ หรืออ้างสาเหตุที่ไม่ถูกต้อง"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Astronomy and space","th":"ดาราศาสตร์และอวกาศ"},"passage":"","table":null,"lang":"th","stem":"คืนนี้เป็นคืนวันขึ้น 15 ค่ำ (ดวงจันทร์เต็มดวง) อีกประมาณ 7 วันข้างหน้า จะเห็นดวงจันทร์มีลักษณะใด และขึ้นจากขอบฟ้าทิศตะวันออกประมาณเวลาใด","choices":["สว่างประมาณครึ่งดวง ขึ้นประมาณเที่ยงวัน","เต็มดวง ขึ้นประมาณหัวค่ำ","สว่างประมาณครึ่งดวง ขึ้นประมาณเที่ยงคืน","มองไม่เห็นดวงจันทร์ เพราะเป็นคืนเดือนมืด"],"answer":2,"explanation":{"en":"About 7 days after full moon is the waning half moon (แรม 7–8 ค่ำ, last quarter). The Moon rises about 50 minutes later each day: full moon rises around sunset, so a week later it rises around midnight. The half moon rising near noon is the waxing half moon a week BEFORE full moon; the dark moon comes about 15 days after full moon.","th":"หลังวันเพ็ญประมาณ 7 วันคือแรม 7–8 ค่ำ ดวงจันทร์สว่างครึ่งดวง ดวงจันทร์ขึ้นช้าลงวันละประมาณ 50 นาที วันเพ็ญขึ้นตอนหัวค่ำ อีก 7 วันจึงขึ้นประมาณเที่ยงคืน ส่วนครึ่งดวงที่ขึ้นตอนเที่ยงวันคือขึ้น 7–8 ค่ำ (ก่อนวันเพ็ญ) และเดือนมืดเกิดหลังวันเพ็ญประมาณ 15 วัน"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"e","skill":{"en":"Recalling key concepts","th":"ความเข้าใจมโนทัศน์พื้นฐาน"},"topic":{"en":"Cells and living things","th":"เซลล์และสิ่งมีชีวิต"},"passage":"","table":null,"lang":"en","stem":"In which part of a plant cell does photosynthesis take place?","choices":["Nucleus","Cell wall","Vacuole","Chloroplast"],"answer":3,"explanation":{"en":"Chloroplasts contain chlorophyll, which absorbs light energy to make glucose from carbon dioxide and water. The nucleus controls the cell, the cell wall gives support and the vacuole stores water and substances.","th":"คลอโรพลาสต์มีคลอโรฟิลล์ที่ดูดกลืนพลังงานแสงเพื่อสร้างกลูโคสจากคาร์บอนไดออกไซด์และน้ำ ส่วนนิวเคลียสควบคุมการทำงานของเซลล์ ผนังเซลล์ให้ความแข็งแรง และแวคิวโอลเก็บน้ำและสารต่าง ๆ"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Identifying variables","th":"การระบุตัวแปร"},"topic":{"en":"Scientific process skills","th":"ทักษะกระบวนการทางวิทยาศาสตร์"},"passage":"","table":null,"lang":"en","stem":"A student fills three identical cans — one black, one white and one silver — with the same volume of water at 25 °C and leaves them in the sun. After 30 minutes she measures the water temperature in each can. What is the dependent variable?","choices":["The colour of the can","The temperature of the water after 30 minutes","The volume of water in each can","The time the cans are left in the sun"],"answer":1,"explanation":{"en":"The dependent variable is what is measured as the result: the water temperature after 30 minutes. The can colour is the independent variable (deliberately changed); the volume of water and the time are controlled variables.","th":"ตัวแปรตามคือสิ่งที่วัดเป็นผลการทดลอง คืออุณหภูมิของน้ำหลัง 30 นาที สีของกระป๋องเป็นตัวแปรต้น ส่วนปริมาตรน้ำและเวลาเป็นตัวแปรควบคุม"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Interpreting data tables","th":"การตีความข้อมูลจากตาราง"},"topic":{"en":"Scientific process skills","th":"ทักษะกระบวนการทางวิทยาศาสตร์"},"passage":"","table":null,"lang":"en","stem":"A class measured how long a sugar cube took to dissolve in water at different temperatures: 20 °C — 120 s, 40 °C — 75 s, 60 °C — 45 s, 80 °C — 30 s. Which statement is best supported by these results?","choices":["Doubling the temperature always halves the dissolving time.","Sugar cannot dissolve in water below 20 °C.","Temperature stops affecting the dissolving time above 60 °C.","Sugar dissolves faster at higher temperatures, but each 20 °C rise saves less time than the one before."],"answer":3,"explanation":{"en":"The times fall as temperature rises (120 → 75 → 45 → 30 s), so sugar dissolves faster when hotter. The time saved shrinks: 45 s, then 30 s, then 15 s. 'Doubling halves the time' fails (20 → 40 °C only goes from 120 to 75 s); nothing was tested below 20 °C; and the time still fell from 45 to 30 s above 60 °C.","th":"เวลาลดลงเมื่ออุณหภูมิสูงขึ้น (120 → 75 → 45 → 30 s) แสดงว่าน้ำตาลละลายเร็วขึ้นเมื่อร้อนขึ้น และเวลาที่ลดลงแต่ละช่วงน้อยลงเรื่อย ๆ (45, 30, 15 s) ข้อที่ว่าอุณหภูมิเพิ่ม 2 เท่าเวลาลดครึ่งหนึ่งไม่จริง (20 → 40 °C เวลาลดจาก 120 เป็น 75 s) ไม่มีข้อมูลต่ำกว่า 20 °C และเหนือ 60 °C เวลายังลดลงจาก 45 เป็น 30 s"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"e","skill":{"en":"Scientific calculation","th":"การคำนวณทางวิทยาศาสตร์"},"topic":{"en":"Forces and motion","th":"แรงและการเคลื่อนที่"},"passage":"","table":null,"lang":"en","stem":"A bus travels 150 km in 2 hours 30 minutes. What is its average speed?","choices":["60 km/h","50 km/h","65 km/h","75 km/h"],"answer":0,"explanation":{"en":"2 hours 30 minutes = 2.5 hours. Average speed = distance ÷ time = 150 ÷ 2.5 = 60 km/h. (65 km/h comes from wrongly using 2.30 hours.)","th":"2 ชั่วโมง 30 นาที = 2.5 ชั่วโมง อัตราเร็วเฉลี่ย = ระยะทาง ÷ เวลา = 150 ÷ 2.5 = 60 km/h (ถ้าใช้ 2.30 ชั่วโมงจะได้ประมาณ 65 km/h ซึ่งผิด)"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Electricity and magnetism","th":"ไฟฟ้าและแม่เหล็ก"},"passage":"","table":null,"lang":"en","stem":"Two identical bulbs are connected to the same battery, first in series and then in parallel. Which statement is correct?","choices":["The bulbs are brighter in parallel, because each bulb receives the full voltage of the battery.","The bulbs are brighter in series, because the current passes through both bulbs.","The bulbs are equally bright in both circuits, because the battery is the same.","In parallel, removing one bulb makes the other bulb go out."],"answer":0,"explanation":{"en":"In series the battery's voltage is shared between the two bulbs, so each glows dimly. In parallel each bulb is connected directly across the battery and gets the full voltage, so both are brighter. In parallel each bulb has its own path, so removing one does not switch off the other.","th":"เมื่อต่ออนุกรม ความต่างศักย์ของแบตเตอรี่ถูกแบ่งให้สองหลอด แต่ละหลอดจึงหรี่ เมื่อต่อขนาน แต่ละหลอดได้รับความต่างศักย์เต็มของแบตเตอรี่ จึงสว่างกว่า และแต่ละหลอดมีทางเดินกระแสของตัวเอง ถอดหลอดหนึ่งออกอีกหลอดยังสว่าง"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"e","skill":{"en":"Classifying","th":"การจำแนกประเภท"},"topic":{"en":"Properties and changes of matter","th":"สมบัติและการเปลี่ยนแปลงของสาร"},"passage":"","table":null,"lang":"en","stem":"Which of the following is a pure substance?","choices":["Air","Seawater","Orange juice","Distilled water"],"answer":3,"explanation":{"en":"Distilled water contains only water particles, so it is a pure substance (a compound). Air is a mixture of gases, seawater is a solution of salts in water, and orange juice is a mixture of many substances.","th":"น้ำกลั่นมีเพียงอนุภาคของน้ำ จึงเป็นสารบริสุทธิ์ (สารประกอบ) ส่วนอากาศเป็นสารผสมของแก๊สหลายชนิด น้ำทะเลเป็นสารละลายของเกลือในน้ำ และน้ำส้มเป็นสารผสมของสารหลายชนิด"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Recalling key concepts","th":"ความเข้าใจมโนทัศน์พื้นฐาน"},"topic":{"en":"Ecosystems and food webs","th":"ระบบนิเวศและโซ่อาหาร"},"passage":"","table":null,"lang":"en","stem":"What is the main role of decomposers such as fungi and bacteria in an ecosystem?","choices":["They break down dead organisms and return nutrients to the soil.","They make food from sunlight for other organisms.","They hunt and control the number of herbivores.","They carry pollen from flower to flower."],"answer":0,"explanation":{"en":"Decomposers feed on dead plants, animals and waste and break them down, releasing nutrients back into the soil for plants to reuse. Making food from sunlight is what producers do; hunting is what predators do; carrying pollen is what pollinators do.","th":"ผู้ย่อยสลายกินซากพืช ซากสัตว์ และของเสีย แล้วย่อยสลายให้กลายเป็นธาตุอาหารกลับคืนสู่ดินให้พืชนำไปใช้ใหม่ การสร้างอาหารจากแสงเป็นหน้าที่ของผู้ผลิต การล่าเป็นของผู้ล่า และการพาเรณูเป็นของสัตว์ผสมเกสร"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Astronomy and space","th":"ดาราศาสตร์และอวกาศ"},"passage":"","table":null,"lang":"en","stem":"People on Earth always see the same side of the Moon. Why?","choices":["The Moon spins once on its axis in the same time that it takes to orbit Earth once.","The Moon does not spin on its axis at all.","Earth's shadow always covers the other side of the Moon.","The Moon orbits Earth once every 24 hours, as Earth spins."],"answer":0,"explanation":{"en":"The Moon rotates once about every 27 days, the same time it takes to go around Earth once, so the same face keeps pointing towards us. If it did not spin, we would see all sides during an orbit. Earth's shadow only falls on the Moon during a lunar eclipse, and the Moon takes about a month, not a day, to orbit Earth.","th":"ดวงจันทร์หมุนรอบตัวเองครบ 1 รอบใช้เวลาประมาณ 27 วัน เท่ากับเวลาที่โคจรรอบโลก 1 รอบ ด้านเดิมจึงหันเข้าหาโลกเสมอ ถ้าดวงจันทร์ไม่หมุนรอบตัวเองเราจะเห็นทุกด้านใน 1 รอบการโคจร เงาของโลกตกบนดวงจันทร์เฉพาะตอนจันทรุปราคา และดวงจันทร์ใช้เวลาประมาณ 1 เดือนในการโคจรรอบโลก ไม่ใช่ 1 วัน"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"m","skill":{"en":"Recalling key concepts","th":"ความเข้าใจมโนทัศน์พื้นฐาน"},"topic":{"en":"Earth, weather and the water cycle","th":"โลก ลมฟ้าอากาศ และวัฏจักรน้ำ"},"passage":"","table":null,"lang":"en","stem":"In the water cycle, which process changes water vapour high in the air into the tiny droplets that form clouds?","choices":["Evaporation","Precipitation","Condensation","Transpiration"],"answer":2,"explanation":{"en":"As water vapour rises it cools and condenses into tiny droplets, forming clouds. Evaporation is liquid water turning into vapour, precipitation is rain or snow falling, and transpiration is water vapour lost from plant leaves.","th":"ไอน้ำที่ลอยสูงขึ้นจะเย็นลงและควบแน่นเป็นละอองน้ำเล็ก ๆ กลายเป็นเมฆ ส่วนการระเหยคือน้ำเปลี่ยนเป็นไอ หยาดน้ำฟ้าคือฝนหรือหิมะที่ตกลงมา และการคายน้ำคือการที่พืชปล่อยไอน้ำทางใบ"}},{"kind":"m1","program":"satit","subject":"sci","format":"mcq","difficulty":"h","skill":{"en":"Applying concepts to situations","th":"การนำความรู้ไปใช้ในสถานการณ์"},"topic":{"en":"Heat and temperature","th":"ความร้อนและอุณหภูมิ"},"passage":"","table":null,"lang":"en","stem":"A glass of water with lots of ice is stirred in a warm room. A thermometer shows 0 °C for several minutes while the ice melts. Why does the temperature stay at 0 °C?","choices":["The heat taken in is used to melt the ice, not to raise the temperature.","The ice stops heat from entering the glass.","The thermometer cannot measure temperatures above 0 °C.","Water always stays at 0 °C until it is heated on a stove."],"answer":0,"explanation":{"en":"While ice melts, the energy absorbed from the warm room is used to change solid into liquid (latent heat), so the temperature of the ice–water mixture stays at the melting point, 0 °C. Only when all the ice has melted does the temperature start to rise. Heat does enter the glass — that is what melts the ice.","th":"ขณะที่น้ำแข็งกำลังละลาย พลังงานความร้อนที่ได้รับจากห้องถูกใช้ในการเปลี่ยนสถานะจากของแข็งเป็นของเหลว (ความร้อนแฝง) อุณหภูมิของน้ำผสมน้ำแข็งจึงคงที่ที่จุดหลอมเหลว 0 °C จนน้ำแข็งละลายหมดอุณหภูมิจึงเริ่มสูงขึ้น ความร้อนยังเข้าสู่แก้วอยู่ตลอด จึงทำให้น้ำแข็งละลาย"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Sounds, tones and syllables","th":"เสียงในภาษา วรรณยุกต์ และพยางค์"},"passage":"","table":null,"lang":"th","stem":"คำใดมีเสียงสระประสม","choices":["เมฆ","เมือง","แมว","โมง"],"answer":1,"explanation":{"en":"Thai has three diphthongs: เอีย, เอือ and อัว. เมือง uses เอือ. เมฆ has เอ, แมว has แอ followed by the final ว, and โมง has โอ — all single (pure) vowels.","th":"สระประสมในภาษาไทยมี 3 เสียง คือ เอีย เอือ อัว คำว่า เมือง ใช้สระเอือ ส่วน เมฆ ใช้สระเอ แมว ใช้สระแอ มี ว เป็นตัวสะกด และ โมง ใช้สระโอ ซึ่งเป็นสระเดี่ยวทั้งหมด"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Sounds, tones and syllables","th":"เสียงในภาษา วรรณยุกต์ และพยางค์"},"passage":"","table":null,"lang":"th","stem":"ข้อใดออกเสียงวรรณยุกต์ตรีทุกคำ","choices":["โต๊ะ ป้า จ๊ะ","รัก ซื้อ มาก","ค้า นะ ช้าง","ร้อง ขัด นก"],"answer":2,"explanation":{"en":"ค้า and ช้าง are low-class consonants with mai tho, giving a high (ตรี) tone; นะ is a low-class dead syllable with a short vowel, also high tone. In the other groups: ป้า (mid class + mai tho) is falling (โท); มาก (low class, dead, long vowel) is falling; ขัด (high class, dead) is low (เอก).","th":"ค้า และ ช้าง เป็นอักษรต่ำมีไม้โท ออกเสียงตรี ส่วน นะ เป็นอักษรต่ำคำตายสระเสียงสั้น ออกเสียงตรีเช่นกัน กลุ่มอื่นมีคำที่ไม่ใช่เสียงตรี ได้แก่ ป้า (อักษรกลางไม้โท = เสียงโท) มาก (อักษรต่ำคำตายสระเสียงยาว = เสียงโท) และ ขัด (อักษรสูงคำตาย = เสียงเอก)"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Sounds, tones and syllables","th":"เสียงในภาษา วรรณยุกต์ และพยางค์"},"passage":"","table":null,"lang":"th","stem":"คำใดมี 3 พยางค์","choices":["ราชการ","สมุด","ตลาด","ขนม"],"answer":0,"explanation":{"en":"ราชการ is read ราด-ชะ-กาน: three syllables. สมุด (สะ-หมุด), ตลาด (ตะ-หลาด) and ขนม (ขะ-หนม) each have two syllables, even though they look short or long on paper.","th":"ราชการ อ่านว่า ราด-ชะ-กาน มี 3 พยางค์ ส่วน สมุด (สะ-หมุด) ตลาด (ตะ-หลาด) และ ขนม (ขะ-หนม) มีคำละ 2 พยางค์"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Spelling and pronunciation","th":"การสะกดคำและการอ่านออกเสียง"},"passage":"","table":null,"lang":"th","stem":"ข้อใดมีตัวสะกดอยู่ในมาตราแม่กดทุกคำ","choices":["บาป ราช ภาพ","สุข เมฆ ครุฑ","กาล พุธ ยศ","อากาศ พิษ รถ"],"answer":3,"explanation":{"en":"ศ in อากาศ, ษ in พิษ and ถ in รถ all sound like ด, so all three are แม่กด. Others: บาป and ภาพ end in บ sounds (แม่กบ); สุข and เมฆ end in ก sounds (แม่กก); กาล ends in น (แม่กน).","th":"ศ ใน อากาศ ษ ใน พิษ และ ถ ใน รถ ออกเสียงเป็น ด จึงอยู่ในแม่กดทั้งหมด กลุ่มอื่นมีคำต่างมาตรา คือ บาป และ ภาพ เป็นแม่กบ สุข และ เมฆ เป็นแม่กก และ กาล เป็นแม่กน"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Spelling and pronunciation","th":"การสะกดคำและการอ่านออกเสียง"},"passage":"","table":null,"lang":"th","stem":"ข้อใดสะกดถูกต้องทุกคำ","choices":["อนุญาต สังเกต บิณฑบาต","อนุญาติ ผาสุก ลายเซ็น","สังเกตุ กะทันหัน ปรากฏ","บิณฑบาตร โอกาส ผลัด"],"answer":0,"explanation":{"en":"The correct spellings are อนุญาต, สังเกต and บิณฑบาต. The other groups each contain a common misspelling: อนุญาติ (should be อนุญาต), สังเกตุ (should be สังเกต) and บิณฑบาตร (should be บิณฑบาต).","th":"คำที่สะกดถูกคือ อนุญาต สังเกต บิณฑบาต กลุ่มอื่นมีคำที่มักเขียนผิด ได้แก่ อนุญาติ (ที่ถูกคือ อนุญาต) สังเกตุ (ที่ถูกคือ สังเกต) และ บิณฑบาตร (ที่ถูกคือ บิณฑบาต)"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Spelling and pronunciation","th":"การสะกดคำและการอ่านออกเสียง"},"passage":"","table":null,"lang":"th","stem":"ประโยคใดมีคำที่สะกดผิด","choices":["ทุกคนต้องเคารพกฏหมายของบ้านเมือง","นักเรียนต้องรักษาระเบียบวินัยและหลีกเลี่ยงการทะเลาะวิวาท","แม่ค้าคิดค่าบริการเพิ่มโดยไม่บอกกล่าวล่วงหน้า","คุณตาชอบนั่งอ่านหนังสือพิมพ์ที่ระเบียงบ้าน"],"answer":0,"explanation":{"en":"The word 'law' is spelled กฎหมาย with ฎ (ชฎา), not ฏ (ปฏัก). Every word in the other sentences, such as ทะเลาะวิวาท, บอกกล่าว and ระเบียง, is spelled correctly.","th":"คำว่า กฎหมาย ต้องเขียนด้วย ฎ ชฎา ไม่ใช่ ฏ ปฏัก ส่วนประโยคอื่นสะกดถูกทุกคำ เช่น ทะเลาะวิวาท บอกกล่าว ระเบียง"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Spelling and pronunciation","th":"การสะกดคำและการอ่านออกเสียง"},"passage":"","table":null,"lang":"th","stem":"ข้อใดบอกคำอ่านได้ถูกต้อง","choices":["สรรพสินค้า อ่านว่า สับ-สิน-ค้า","เกียรติยศ อ่านว่า เกียด-ยด","กาลเทศะ อ่านว่า กา-ละ-เท-สะ","คุณประโยชน์ อ่านว่า คุน-ประ-โหยด"],"answer":2,"explanation":{"en":"กาลเทศะ is read กา-ละ-เท-สะ, with the linking ละ sound. The others drop a required linking syllable: สรรพสินค้า is สับ-พะ-สิน-ค้า, เกียรติยศ is เกียด-ติ-ยด and คุณประโยชน์ is คุน-นะ-ประ-โหยด.","th":"กาลเทศะ อ่านว่า กา-ละ-เท-สะ ถูกต้อง ส่วนข้ออื่นอ่านขาดเสียงที่ต้องอ่านเชื่อม ได้แก่ สรรพสินค้า อ่านว่า สับ-พะ-สิน-ค้า เกียรติยศ อ่านว่า เกียด-ติ-ยด และ คุณประโยชน์ อ่านว่า คุน-นะ-ประ-โหยด"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Word types and word formation","th":"ชนิดของคำและการสร้างคำ"},"passage":"","table":null,"lang":"th","stem":"คำว่า «กับ» ในข้อใดทำหน้าที่เป็นคำสันธาน","choices":["น้องเล่นกับแมวที่สนาม","ครูคุยกับผู้ปกครองหน้าห้อง","พ่อกับแม่ไปตลาดตั้งแต่เช้า","เขาวางแก้วไว้กับพื้น"],"answer":2,"explanation":{"en":"In 'พ่อกับแม่ไปตลาด' กับ joins two nouns that together form the subject, so it is a conjunction (สันธาน) meaning 'and'. In the other sentences กับ links a verb to its object or place — เล่นกับแมว, คุยกับผู้ปกครอง, วางไว้กับพื้น — so it is a preposition (บุพบท).","th":"ใน \"พ่อกับแม่ไปตลาด\" คำว่า กับ เชื่อมคำนาม 2 คำที่รวมกันเป็นประธาน จึงเป็นคำสันธาน (มีความหมายว่า และ) ส่วนประโยคอื่น กับ นำหน้าคำนามเพื่อบอกความสัมพันธ์กับกริยา เช่น เล่นกับแมว คุยกับผู้ปกครอง วางไว้กับพื้น จึงเป็นคำบุพบท"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Word types and word formation","th":"ชนิดของคำและการสร้างคำ"},"passage":"","table":null,"lang":"th","stem":"ข้อใดใช้คำลักษณนามถูกต้องทุกคำ","choices":["เสื้อ 2 ตัว แหวน 1 อัน ถนน 3 สาย","พระภิกษุ 3 รูป ร่ม 2 คัน ปากกา 1 ด้าม","บ้าน 2 หลัง กระดาษ 5 ผืน ช้อน 3 คัน","รถยนต์ 1 คัน ฟัน 2 ตัว ปี่ 1 เลา"],"answer":1,"explanation":{"en":"Monks are counted with รูป, umbrellas with คัน and pens with ด้าม — all correct. The other groups each contain one wrong classifier: rings take วง (not อัน), paper takes แผ่น (not ผืน) and teeth take ซี่ (not ตัว).","th":"พระภิกษุใช้ลักษณนาม รูป ร่มใช้ คัน ปากกาใช้ ด้าม ถูกทั้งหมด กลุ่มอื่นมีลักษณนามที่ผิด คือ แหวนต้องใช้ วง กระดาษต้องใช้ แผ่น และฟันต้องใช้ ซี่"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Word types and word formation","th":"ชนิดของคำและการสร้างคำ"},"passage":"","table":null,"lang":"th","stem":"ข้อใดเป็นคำประสมทุกคำ","choices":["เสื่อสาด บ้านเรือน แม่ทัพ","ทหาร สมุด นาฬิกา","แม่น้ำ ลูกเสือ น้ำแข็ง","พัดลม ถ้วยชาม เด็ก ๆ"],"answer":2,"explanation":{"en":"แม่น้ำ, ลูกเสือ and น้ำแข็ง are compound words: two root words combine to make a new meaning. เสื่อสาด and บ้านเรือน are doublets (คำซ้อน), ทหาร, สมุด and นาฬิกา are single root words (คำมูล), and ถ้วยชาม is a doublet while เด็ก ๆ is a reduplicated word (คำซ้ำ).","th":"แม่น้ำ ลูกเสือ น้ำแข็ง เป็นคำประสม คือนำคำมูลมารวมกันแล้วเกิดความหมายใหม่ ส่วน เสื่อสาด บ้านเรือน เป็นคำซ้อน ทหาร สมุด นาฬิกา เป็นคำมูล และ ถ้วยชาม เป็นคำซ้อน เด็ก ๆ เป็นคำซ้ำ"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Word types and word formation","th":"ชนิดของคำและการสร้างคำ"},"passage":"","table":null,"lang":"th","stem":"ข้อใดเป็นคำซ้อนที่เกิดจากคำซึ่งมีความหมายตรงกันข้ามกัน","choices":["ผิดชอบ","ทรัพย์สิน","เสื่อสาด","ใหญ่โต"],"answer":0,"explanation":{"en":"ผิดชอบ joins ผิด (wrong) and ชอบ (right, proper) — words with opposite meanings — to mean 'responsibility / sense of right and wrong'. ทรัพย์สิน, เสื่อสาด and ใหญ่โต join words with similar meanings.","th":"ผิดชอบ เกิดจาก ผิด กับ ชอบ (ถูกต้อง) ซึ่งมีความหมายตรงข้ามกัน รวมกันหมายถึงความรู้จักผิดและถูก ส่วน ทรัพย์สิน เสื่อสาด และ ใหญ่โต เกิดจากคำที่มีความหมายคล้ายกัน"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Interpreting meaning in context","th":"การตีความหมายตามบริบท"},"topic":{"en":"Word types and word formation","th":"ชนิดของคำและการสร้างคำ"},"passage":"","table":null,"lang":"th","stem":"ข้อใดใช้คำซ้ำแล้วทำให้ความหมายเปลี่ยนไปจากคำเดิม","choices":["เด็ก ๆ วิ่งเล่นกันในสนาม","ดอกไม้สีแดง ๆ บานเต็มต้น","เขาทำการบ้านส่ง ๆ ไม่ตั้งใจเลย","น้องค่อย ๆ เดินขึ้นบันได"],"answer":2,"explanation":{"en":"ส่ง means 'send', but ส่ง ๆ means 'carelessly, just to get it done' — a new meaning. เด็ก ๆ only shows plurality, แดง ๆ softens the colour (reddish), and ค่อย ๆ keeps the meaning 'gently, gradually'.","th":"ส่ง แปลว่า นำไปให้ แต่ ส่ง ๆ หมายถึง ทำอย่างลวก ๆ ไม่ตั้งใจ ความหมายจึงเปลี่ยนไป ส่วน เด็ก ๆ บอกพหูพจน์ แดง ๆ บอกลักษณะสีที่ไม่เข้มมาก และ ค่อย ๆ ยังคงความหมายเดิมคือช้า ๆ เบา ๆ"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Loanwords","th":"คำยืมในภาษาไทย"},"passage":"","table":null,"lang":"th","stem":"ข้อใดเป็นคำที่มาจากภาษาเขมรทุกคำ","choices":["ก๋วยเตี๋ยว ตะหลิว เก้าอี้","กษัตริย์ ศึกษา ปรารถนา","เสวย ดำเนิน บรรทม","คอมพิวเตอร์ ฟุตบอล ไอศกรีม"],"answer":2,"explanation":{"en":"เสวย, ดำเนิน and บรรทม are Khmer loanwords, often used as royal vocabulary; the ดำ- and บรร- prefixes are typical Khmer features. The other groups are Chinese (ก๋วยเตี๋ยว, ตะหลิว, เก้าอี้), Sanskrit (กษัตริย์, ศึกษา, ปรารถนา) and English loanwords.","th":"เสวย ดำเนิน บรรทม เป็นคำยืมจากภาษาเขมร มักใช้เป็นราชาศัพท์ และคำที่ขึ้นต้นด้วย ดำ- บรร- มักมาจากภาษาเขมร กลุ่มอื่นเป็นคำจากภาษาจีน (ก๋วยเตี๋ยว ตะหลิว เก้าอี้) ภาษาสันสกฤต (กษัตริย์ ศึกษา ปรารถนา) และภาษาอังกฤษ"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Loanwords","th":"คำยืมในภาษาไทย"},"passage":"","table":null,"lang":"th","stem":"คำใดเป็นคำที่มาจากภาษาสันสกฤต","choices":["สิกขา","ขัตติยะ","วิชา","ศึกษา"],"answer":3,"explanation":{"en":"ศึกษา is the Sanskrit form (ศ and the cluster กษ are Sanskrit features); its Pali counterpart is สิกขา. ขัตติยะ is the Pali form of Sanskrit กษัตริย์, and วิชา is the Pali form of Sanskrit วิทยา.","th":"ศึกษา เป็นคำสันสกฤต (ใช้ ศ และมีอักษร ษ ซึ่งเป็นลักษณะของสันสกฤต) คำบาลีที่คู่กันคือ สิกขา ส่วน ขัตติยะ เป็นคำบาลีของ กษัตริย์ และ วิชา เป็นคำบาลีของ วิทยา"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Sentences and usage","th":"ประโยคและการใช้ภาษา"},"passage":"","table":null,"lang":"th","stem":"ข้อใดเป็นประโยคความซ้อน","choices":["ฉันกินข้าวแล้วจึงไปโรงเรียน","พี่ชอบอ่านหนังสือ แต่น้องชอบเล่นเกม","นกบินสูงเหนือทุ่งนา","ฉันเห็นนกที่เกาะอยู่บนกิ่งไม้"],"answer":3,"explanation":{"en":"In 'ฉันเห็นนกที่เกาะอยู่บนกิ่งไม้' the clause 'ที่เกาะอยู่บนกิ่งไม้' is a relative clause describing นก inside the main sentence, so it is a complex sentence (ความซ้อน). แล้วจึง and แต่ join two equal clauses (compound sentences, ความรวม), and the last one is a simple sentence (ความเดียว).","th":"ใน \"ฉันเห็นนกที่เกาะอยู่บนกิ่งไม้\" ส่วน \"ที่เกาะอยู่บนกิ่งไม้\" เป็นอนุประโยคที่ขยายคำว่า นก ซ้อนอยู่ในประโยคหลัก จึงเป็นประโยคความซ้อน ส่วนประโยคที่ใช้ แล้วจึง และ แต่ เป็นประโยคความรวม และ \"นกบินสูงเหนือทุ่งนา\" เป็นประโยคความเดียว"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Sentences and usage","th":"ประโยคและการใช้ภาษา"},"passage":"","table":null,"lang":"th","stem":"ข้อใดเป็นประโยคที่ประธานเป็นผู้ถูกกระทำ","choices":["จดหมายฉบับนี้ถูกส่งมาจากเชียงใหม่","แม่ส่งจดหมายถึงยายทุกเดือน","ฉันถูกรางวัลที่หนึ่งจากการจับสลาก","เขาได้รับจดหมายจากเพื่อนเก่า"],"answer":0,"explanation":{"en":"In 'จดหมายฉบับนี้ถูกส่งมา' the letter receives the action of sending, so the subject is acted upon (a passive sentence). In 'ฉันถูกรางวัล' ถูก means 'to win', not a passive marker — the trap. The other two have subjects who do the action.","th":"\"จดหมายฉบับนี้ถูกส่งมา\" จดหมายเป็นผู้ถูกกระทำ (ถูกส่ง) จึงเป็นประโยคที่ประธานเป็นผู้ถูกกระทำ ส่วน \"ฉันถูกรางวัล\" คำว่า ถูก หมายถึง ได้รางวัล ไม่ได้แสดงการถูกกระทำ (เป็นตัวลวง) อีกสองประโยคประธานเป็นผู้กระทำ"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Royal and polite vocabulary","th":"ราชาศัพท์และคำสุภาพ"},"passage":"","table":null,"lang":"th","stem":"ข้อใดใช้ราชาศัพท์ถูกต้อง","choices":["พระองค์ทรงเสด็จไปยังวัดประจำรัชกาล","พระบาทสมเด็จพระเจ้าอยู่หัวเสด็จพระราชดำเนินไปทรงเปิดสะพาน","พระราชาทรงรับประทานอาหารร่วมกับแขกเมือง","พระภิกษุบรรทมแต่หัวค่ำ"],"answer":1,"explanation":{"en":"For the king, 'to go' is เสด็จพระราชดำเนิน, and ทรง + an ordinary verb (ทรงเปิด) is correct. ทรงเสด็จ is wrong because เสด็จ is already a royal verb and must not take ทรง. A king 'eats' with เสวย, not ทรงรับประทาน. Monks 'sleep' with จำวัด; บรรทม is for royalty.","th":"สำหรับพระมหากษัตริย์ \"ไป\" ใช้ว่า เสด็จพระราชดำเนิน และ ทรง + กริยาสามัญ (ทรงเปิด) ใช้ถูก ส่วน \"ทรงเสด็จ\" ผิดเพราะ เสด็จ เป็นกริยาราชาศัพท์อยู่แล้ว ห้ามใช้ ทรง นำหน้า กษัตริย์ \"กิน\" ใช้ เสวย ไม่ใช่ ทรงรับประทาน และพระภิกษุ \"นอน\" ใช้ จำวัด คำว่า บรรทม ใช้กับเจ้านาย"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Royal and polite vocabulary","th":"ราชาศัพท์และคำสุภาพ"},"passage":"","table":null,"lang":"th","stem":"ข้อใดใช้ถ้อยคำสำหรับพระภิกษุได้ถูกต้อง","choices":["หลวงพ่ออาพาธ จึงเสด็จไปโรงพยาบาล","พระครูประทับนั่งบนอาสนะ","หลวงตาสวรรคตเมื่อคืนนี้","หลวงพ่อจำวัดตั้งแต่สามทุ่ม"],"answer":3,"explanation":{"en":"จำวัด is the correct word for a monk sleeping. อาพาธ (to be ill) is right, but an ordinary monk does not เสด็จ — he simply ไป. ประทับ is for royalty; a monk นั่ง. สวรรคต is used for a king; a monk's death is มรณภาพ.","th":"จำวัด เป็นคำที่ใช้กับพระภิกษุเมื่อนอนถูกต้อง ส่วน อาพาธ ใช้ถูกแต่พระภิกษุทั่วไปไม่ใช้ เสด็จ ใช้ ไป เท่านั้น ประทับ ใช้กับเจ้านาย พระภิกษุใช้ นั่ง และ สวรรคต ใช้กับพระมหากษัตริย์ พระภิกษุตายใช้ มรณภาพ"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Applying grammar rules","th":"การใช้หลักภาษา"},"topic":{"en":"Royal and polite vocabulary","th":"ราชาศัพท์และคำสุภาพ"},"passage":"","table":null,"lang":"th","stem":"คำราชาศัพท์ \"พระเนตร\" หมายถึงอวัยวะใด","choices":["ตา","หู","จมูก","คิ้ว"],"answer":0,"explanation":{"en":"พระเนตร means eyes. Ears are พระกรรณ, the nose is พระนาสิก and eyebrows are พระขนง.","th":"พระเนตร หมายถึง ตา ส่วน หู คือ พระกรรณ จมูก คือ พระนาสิก และ คิ้ว คือ พระขนง"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Interpreting meaning in context","th":"การตีความหมายตามบริบท"},"topic":{"en":"Idioms, proverbs and sayings","th":"สำนวน สุภาษิต และคำพังเพย"},"passage":"","table":null,"lang":"th","stem":"สำนวน \"ชักแม่น้ำทั้งห้า\" หมายความว่าอย่างไร","choices":["พูดจาโอ้อวดเกินความจริง","พูดยกยอหว่านล้อมเพื่อให้ได้สิ่งที่ตนต้องการ","ทำงานหลายอย่างพร้อมกัน","เดินทางไกลไปหลายแห่ง"],"answer":1,"explanation":{"en":"ชักแม่น้ำทั้งห้า describes someone who talks at length, flattering and persuading, in order to get what they want. It is not about boasting, multitasking or travelling.","th":"ชักแม่น้ำทั้งห้า หมายถึง พูดยกยอหรือพูดอ้อมค้อมหว่านล้อมเพื่อให้ได้สิ่งที่ตนต้องการ ไม่ได้หมายถึงการโอ้อวด การทำงานหลายอย่าง หรือการเดินทาง"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Interpreting meaning in context","th":"การตีความหมายตามบริบท"},"topic":{"en":"Idioms, proverbs and sayings","th":"สำนวน สุภาษิต และคำพังเพย"},"passage":"","table":null,"lang":"th","stem":"\"สมชายรู้ว่าเพื่อนลอกการบ้าน แต่ก็ทำเป็นไม่รู้ไม่เห็น เพราะไม่อยากมีเรื่อง\" พฤติกรรมของสมชายตรงกับสำนวนใด","choices":["เอาหูไปนา เอาตาไปไร่","ปิดทองหลังพระ","น้ำนิ่งไหลลึก","ตีวัวกระทบคราด"],"answer":0,"explanation":{"en":"เอาหูไปนา เอาตาไปไร่ means pretending not to hear or see something to avoid getting involved — exactly what Somchai does. ปิดทองหลังพระ is doing good without credit, น้ำนิ่งไหลลึก is a quiet person who is deep or clever, and ตีวัวกระทบคราด is venting anger at one thing to hit another.","th":"เอาหูไปนา เอาตาไปไร่ หมายถึง ทำเป็นไม่รับรู้ไม่สนใจเพื่อไม่ให้ตนต้องเข้าไปมีเรื่อง ตรงกับพฤติกรรมของสมชาย ส่วน ปิดทองหลังพระ คือทำความดีโดยไม่มีใครเห็น น้ำนิ่งไหลลึก คือคนเงียบแต่ลึกซึ้งหรือมีความคิด และ ตีวัวกระทบคราด คือโกรธคนหนึ่งแล้วไปแสดงกับอีกสิ่งหนึ่ง"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Interpreting meaning in context","th":"การตีความหมายตามบริบท"},"topic":{"en":"Idioms, proverbs and sayings","th":"สำนวน สุภาษิต และคำพังเพย"},"passage":"","table":null,"lang":"th","stem":"\"ต้นเป็นนักเรียนขยัน แต่ช่วงหลังไปสนิทกับเพื่อนกลุ่มที่ชอบโดดเรียน จนผลการเรียนตกลงอย่างมาก\" สถานการณ์นี้ตรงกับสุภาษิตใด","choices":["รักวัวให้ผูก รักลูกให้ตี","คบคนพาล พาลพาไปหาผิด","น้ำขึ้นให้รีบตัก","ช้า ๆ ได้พร้าเล่มงาม"],"answer":1,"explanation":{"en":"คบคนพาล พาลพาไปหาผิด warns that bad company leads you into wrongdoing, which is what happened to Ton. The others are about discipline in raising children, seizing opportunities, and patience producing good results.","th":"คบคนพาล พาลพาไปหาผิด สอนว่าคบคนไม่ดีจะพาให้ทำผิดหรือเสียหาย ตรงกับเรื่องของต้น ส่วนสุภาษิตอื่นเกี่ยวกับการอบรมลูก การฉวยโอกาส และความใจเย็นทำให้ได้ผลดี"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Interpreting meaning in context","th":"การตีความหมายตามบริบท"},"topic":{"en":"Idioms, proverbs and sayings","th":"สำนวน สุภาษิต และคำพังเพย"},"passage":"","table":null,"lang":"th","stem":"คำพังเพย \"ขี่ช้างจับตั๊กแตน\" มีความหมายตรงกับข้อใด","choices":["ลงทุนหรือใช้ความพยายามมากเกินกว่าผลที่จะได้รับ","ทำงานใหญ่ต้องอาศัยคนจำนวนมาก","ผู้มีอำนาจรังแกผู้ที่อ่อนแอกว่า","ทำสิ่งใดต้องอาศัยความรอบคอบ"],"answer":0,"explanation":{"en":"Riding an elephant to catch a grasshopper means spending a huge effort or cost for a tiny result. It does not refer to teamwork, bullying or carefulness.","th":"ขี่ช้างจับตั๊กแตน หมายถึง ลงทุนหรือลงแรงมากแต่ได้ผลเพียงเล็กน้อยไม่คุ้มกัน ไม่ได้เกี่ยวกับการใช้คนมาก การรังแกผู้อ่อนแอ หรือความรอบคอบ"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Figurative language and register","th":"ภาพพจน์ โวหาร และระดับภาษา"},"passage":"","table":null,"lang":"th","stem":"ข้อใดใช้ภาษาระดับทางการ","choices":["ครูบอกว่าสอบเลื่อนไปวันที่ 15 แล้วนะ","ที่ประชุมมีมติให้เลื่อนการสอบออกไปเป็นวันที่ 15 มีนาคม","สอบเลื่อนไปตั้งอาทิตย์นึงแน่ะ","เลื่อนสอบอีกแล้วเหรอเนี่ย"],"answer":1,"explanation":{"en":"'ที่ประชุมมีมติ' with complete, neutral wording and no particles is formal register, used in announcements and official reports. The others use conversational particles and forms such as นะ, แน่ะ, นึง, เหรอ and เนี่ย, which are informal.","th":"\"ที่ประชุมมีมติ\" ใช้ถ้อยคำสมบูรณ์ เป็นกลาง ไม่มีคำลงท้าย เป็นภาษาระดับทางการที่ใช้ในประกาศหรือรายงาน ส่วนข้ออื่นมีคำแสดงภาษาพูด เช่น นะ แน่ะ นึง เหรอ เนี่ย จึงเป็นภาษาระดับไม่เป็นทางการ"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Figurative language and register","th":"ภาพพจน์ โวหาร และระดับภาษา"},"passage":"","table":null,"lang":"th","stem":"ข้อใดใช้ภาพพจน์บุคคลวัต","choices":["เธองามดุจดอกไม้แรกแย้ม","เขาร้องไห้จนน้ำตาท่วมโลก","สายลมกระซิบบอกความในใจแก่ดอกไม้","เปรี้ยง! ฟ้าผ่าลงกลางทุ่ง"],"answer":2,"explanation":{"en":"Personification (บุคคลวัต) gives human actions to non-human things: the wind 'whispers its feelings'. ดุจ marks a simile (อุปมา), 'tears flooding the world' is hyperbole (อติพจน์), and 'เปรี้ยง' imitates a sound (สัทพจน์).","th":"บุคคลวัตคือการทำให้สิ่งที่ไม่ใช่คนแสดงกิริยาเหมือนคน \"สายลมกระซิบบอกความในใจ\" จึงเป็นบุคคลวัต ส่วน \"งามดุจดอกไม้\" เป็นอุปมา \"น้ำตาท่วมโลก\" เป็นอติพจน์ และ \"เปรี้ยง\" เป็นสัทพจน์"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Figurative language and register","th":"ภาพพจน์ โวหาร และระดับภาษา"},"passage":"","table":null,"lang":"th","stem":"ข้อใดใช้ภาพพจน์อุปลักษณ์","choices":["ครูคือเรือจ้างที่พาศิษย์ข้ามฟากไปสู่ฝั่งฝัน","ใจของเขาดำเหมือนถ่านไฟเก่า","คิดถึงจนกินข้าวไม่ลงเป็นปี","ฝนตกพรำ ๆ ทั้งคืน"],"answer":0,"explanation":{"en":"A metaphor (อุปลักษณ์) says one thing IS another, often with คือ or เป็น: the teacher IS a ferry boat. 'ดำเหมือนถ่าน' uses เหมือน, so it is a simile (อุปมา); 'not eating for a year' is hyperbole; 'พรำ ๆ' imitates sound.","th":"อุปลักษณ์คือการเปรียบว่าสิ่งหนึ่ง \"เป็น\" อีกสิ่งหนึ่ง มักใช้คำว่า คือ หรือ เป็น \"ครูคือเรือจ้าง\" จึงเป็นอุปลักษณ์ ส่วน \"ดำเหมือนถ่าน\" ใช้คำว่า เหมือน เป็นอุปมา \"กินข้าวไม่ลงเป็นปี\" เป็นอติพจน์ และ \"พรำ ๆ\" เป็นสัทพจน์"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Sentences and usage","th":"ประโยคและการใช้ภาษา"},"passage":"","table":null,"lang":"th","stem":"ข้อใดเป็นประโยคกำกวม","choices":["ฉันชอบเขามากกว่าที่เธอชอบเขา","แม่ซื้อผลไม้มาสามชนิด","ฉันชอบเขามากกว่าเธอ","น้องอ่านหนังสือในห้องสมุดทุกเย็น"],"answer":2,"explanation":{"en":"'ฉันชอบเขามากกว่าเธอ' can mean 'I like him more than I like you' or 'I like him more than you like him', so it is ambiguous. The longer version spells out the second meaning and is clear; the other two sentences have only one reading.","th":"\"ฉันชอบเขามากกว่าเธอ\" ตีความได้ 2 แบบ คือ ฉันชอบเขามากกว่าชอบเธอ หรือ ฉันชอบเขามากกว่าที่เธอชอบเขา จึงกำกวม ส่วน \"ฉันชอบเขามากกว่าที่เธอชอบเขา\" ระบุชัดแล้ว และอีกสองประโยคมีความหมายเดียว"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Sentences and usage","th":"ประโยคและการใช้ภาษา"},"passage":"","table":null,"lang":"th","stem":"ข้อใดใช้ภาษาได้กระชับ ไม่ใช้คำฟุ่มเฟือย","choices":["นักเรียนทุกคนต้องส่งรายงานภายในวันศุกร์นี้","นักเรียนทุก ๆ คนทั้งหมดต้องส่งรายงานภายในวันศุกร์นี้","เขากลับมาบ้านเกิดอีกครั้งหนึ่งเป็นครั้งที่สอง","ผู้ชนะเลิศได้รับรางวัลที่หนึ่งเป็นอันดับแรก"],"answer":0,"explanation":{"en":"The sentence about handing in reports by Friday says it once and clearly. The others repeat the same idea: ทุก ๆ คนทั้งหมด (every… all), อีกครั้งหนึ่งเป็นครั้งที่สอง (again… for the second time) and ชนะเลิศ… ที่หนึ่ง… อันดับแรก (winner… first… first place).","th":"ประโยคเรื่องส่งรายงานภายในวันศุกร์ใช้คำกระชับ ไม่ซ้ำความ ส่วนข้ออื่นใช้คำที่มีความหมายซ้ำกัน ได้แก่ ทุก ๆ คนทั้งหมด อีกครั้งหนึ่งเป็นครั้งที่สอง และ ชนะเลิศ ที่หนึ่ง อันดับแรก"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Sentences and usage","th":"ประโยคและการใช้ภาษา"},"passage":"","table":null,"lang":"th","stem":"เรียงประโยคต่อไปนี้ให้เป็นข้อความที่ต่อเนื่องสมเหตุสมผล (1) จากนั้นนำไปตากแดดจนแห้งสนิท (2) เริ่มจากเก็บใบเตยสดมาล้างให้สะอาด (3) สุดท้ายบรรจุใส่ถุงปิดสนิทเพื่อเก็บไว้ใช้ได้นาน (4) แล้วหั่นเป็นชิ้นเล็ก ๆ เพื่อให้แห้งเร็วขึ้น","choices":["2 – 1 – 4 – 3","4 – 2 – 1 – 3","2 – 4 – 3 – 1","2 – 4 – 1 – 3"],"answer":3,"explanation":{"en":"The connecting words show the order: เริ่มจาก (start: wash the leaves, 2), แล้ว (then cut them small, 4), จากนั้น (after that dry them, 1), สุดท้าย (finally pack them, 3). Cutting must come before drying because it is done 'so they dry faster'.","th":"คำเชื่อมบอกลำดับ: เริ่มจาก (ล้างใบเตย ประโยค 2) แล้ว (หั่นชิ้นเล็ก ประโยค 4) จากนั้น (ตากแดด ประโยค 1) สุดท้าย (บรรจุถุง ประโยค 3) และการหั่นต้องมาก่อนการตากเพราะหั่น \"เพื่อให้แห้งเร็วขึ้น\""}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Sentences and usage","th":"ประโยคและการใช้ภาษา"},"passage":"","table":null,"lang":"th","stem":"ข้อใดเติมคำเชื่อมลงในช่องว่างได้เหมาะสมที่สุด \"____ฝนจะตกหนัก ____เขาก็ยังออกไปวิ่งตามปกติ\"","choices":["เพราะ … จึง","แม้ … แต่","หาก … จึง","เมื่อ … และ"],"answer":1,"explanation":{"en":"The sentence contrasts two ideas: heavy rain, yet he still goes running (ก็ยัง signals 'still, despite'). แม้ … แต่ expresses this contrast. เพราะ … จึง and หาก … จึง show cause or condition, which does not fit ก็ยัง, and เมื่อ … และ only joins events in time.","th":"ประโยคนี้มีความขัดแย้งกัน คือฝนตกหนักแต่เขาก็ยังไปวิ่ง (คำว่า ก็ยัง แสดงการขัดแย้ง) จึงใช้ แม้ … แต่ ส่วน เพราะ … จึง และ หาก … จึง แสดงเหตุผลหรือเงื่อนไข ไม่เข้ากับ ก็ยัง และ เมื่อ … และ เพียงเรียงเหตุการณ์ตามเวลา"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Analysing language use","th":"การวิเคราะห์การใช้ภาษา"},"topic":{"en":"Word types and word formation","th":"ชนิดของคำและการสร้างคำ"},"passage":"","table":null,"lang":"th","stem":"ข้อใดเป็นคำพ้องรูป (เขียนเหมือนกัน แต่อ่านออกเสียงต่างกัน และความหมายต่างกัน)","choices":["ขัน (ภาชนะตักน้ำ) – ขัน (น่าหัวเราะ)","การ – กาล","เพลา (เวลา) – เพลา (แกนล้อ)","สัน – สรรค์"],"answer":2,"explanation":{"en":"เพลา meaning 'time' is read เพ-ลา, while เพลา meaning 'axle' is read as one syllable เพฺลา — same spelling, different sounds, so it is a homograph (คำพ้องรูป). ขัน is spelled and pronounced the same in both meanings (คำพ้องรูปพ้องเสียง / คำหลายความหมาย). การ–กาล and สัน–สรรค์ sound the same but are spelled differently (คำพ้องเสียง).","th":"เพลา ที่แปลว่าเวลา อ่านว่า เพ-ลา ส่วน เพลา ที่แปลว่าแกนล้อ อ่านว่า เพฺลา เขียนเหมือนกันแต่อ่านต่างกัน จึงเป็นคำพ้องรูป ส่วน ขัน เขียนและอ่านเหมือนกันทั้งสองความหมาย และ การ–กาล กับ สัน–สรรค์ อ่านเหมือนกันแต่เขียนต่างกัน เป็นคำพ้องเสียง"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Knowledge of literature","th":"ความรู้เรื่องวรรณคดี"},"topic":{"en":"Thai literature","th":"วรรณคดีไทย"},"passage":"","table":null,"lang":"th","stem":"ผู้แต่งเรื่อง \"พระอภัยมณี\" คือใคร","choices":["สุนทรภู่","ศรีปราชญ์","เจ้าพระยาพระคลัง (หน)","พระยาอุปกิตศิลปสาร"],"answer":0,"explanation":{"en":"พระอภัยมณี, the long verse tale about a prince who plays a magic flute, was written by Sunthorn Phu (สุนทรภู่). Chao Phraya Phra Khlang (Hon) is known for the prose translation สามก๊ก, and Phraya Upakit Silapasan wrote Thai grammar textbooks.","th":"พระอภัยมณี เป็นกลอนนิทานของสุนทรภู่ ส่วนเจ้าพระยาพระคลัง (หน) มีผลงานเด่นคือสามก๊ก และพระยาอุปกิตศิลปสารเป็นผู้แต่งตำราหลักภาษาไทย"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Knowledge of literature","th":"ความรู้เรื่องวรรณคดี"},"topic":{"en":"Thai literature","th":"วรรณคดีไทย"},"passage":"","table":null,"lang":"th","stem":"ในเรื่องพระอภัยมณี \"สุดสาคร\" เป็นโอรสของพระอภัยมณีกับใคร","choices":["นางผีเสื้อสมุทร","นางเงือก","นางสุวรรณมาลี","นางละเวงวัณฬา"],"answer":1,"explanation":{"en":"Sudsakhon is the son of Phra Aphai Mani and the mermaid (นางเงือก). The ogress นางผีเสื้อสมุทร is the mother of สินสมุทร, a different son — a common confusion.","th":"สุดสาครเป็นโอรสของพระอภัยมณีกับนางเงือก ส่วนนางผีเสื้อสมุทรเป็นมารดาของสินสมุทร ซึ่งมักถูกจำสับสนกัน"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Knowledge of literature","th":"ความรู้เรื่องวรรณคดี"},"topic":{"en":"Thai literature","th":"วรรณคดีไทย"},"passage":"","table":null,"lang":"th","stem":"\"นิราศภูเขาทอง\" ของสุนทรภู่ แต่งด้วยคำประพันธ์ประเภทใด","choices":["กลอนนิราศ","โคลงสี่สุภาพ","กาพย์ยานี 11","ร่ายสุภาพ"],"answer":0,"explanation":{"en":"นิราศภูเขาทอง is a travel poem (นิราศ) in Sunthorn Phu's eight-syllable กลอน, so its form is กลอนนิราศ. It is not written in โคลง, กาพย์ or ร่าย.","th":"นิราศภูเขาทองเป็นวรรณคดีประเภทนิราศที่สุนทรภู่แต่งด้วยกลอนแปด เรียกว่า กลอนนิราศ ไม่ได้แต่งด้วยโคลง กาพย์ หรือร่าย"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Knowledge of literature","th":"ความรู้เรื่องวรรณคดี"},"topic":{"en":"Thai literature","th":"วรรณคดีไทย"},"passage":"","table":null,"lang":"th","stem":"\"กาพย์เห่เรือ\" เป็นพระนิพนธ์ของผู้ใด","choices":["สุนทรภู่","สมเด็จพระมหาสมณเจ้า กรมพระปรมานุชิตชิโนรส","เจ้าฟ้าธรรมธิเบศร (เจ้าฟ้ากุ้ง)","เจ้าพระยาพระคลัง (หน)"],"answer":2,"explanation":{"en":"กาพย์เห่เรือ was composed by Prince Thammathibet (เจ้าฟ้ากุ้ง) of the late Ayutthaya period. Prince Paramanuchitchinorot wrote ลิลิตตะเลงพ่าย, and Chao Phraya Phra Khlang (Hon) is known for สามก๊ก.","th":"กาพย์เห่เรือเป็นพระนิพนธ์ของเจ้าฟ้าธรรมธิเบศร (เจ้าฟ้ากุ้ง) สมัยอยุธยาตอนปลาย ส่วนสมเด็จพระมหาสมณเจ้า กรมพระปรมานุชิตชิโนรส ทรงนิพนธ์ลิลิตตะเลงพ่าย และเจ้าพระยาพระคลัง (หน) มีผลงานเด่นคือสามก๊ก"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Recognising verse forms","th":"การวิเคราะห์ลักษณะคำประพันธ์"},"topic":{"en":"Thai literature","th":"วรรณคดีไทย"},"passage":"","table":null,"lang":"th","stem":"วรรณคดีเรื่องใดแต่งด้วยร่ายสุภาพ","choices":["พระอภัยมณี","กาพย์เห่เรือ","สุภาษิตพระร่วง","นิราศภูเขาทอง"],"answer":2,"explanation":{"en":"สุภาษิตพระร่วง, a collection of short teachings, is written in ร่ายสุภาพ. พระอภัยมณี and นิราศภูเขาทอง are in กลอน, and กาพย์เห่เรือ is in กาพย์ยานี with โคลง.","th":"สุภาษิตพระร่วงเป็นคำสอนสั้น ๆ ที่แต่งด้วยร่ายสุภาพ ส่วนพระอภัยมณีและนิราศภูเขาทองแต่งด้วยกลอน และกาพย์เห่เรือแต่งด้วยกาพย์ยานีและโคลง"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Recognising verse forms","th":"การวิเคราะห์ลักษณะคำประพันธ์"},"topic":{"en":"Thai literature","th":"วรรณคดีไทย"},"passage":"","table":null,"lang":"th","stem":"วรรณคดีเรื่องใดแต่งเป็นร้อยแก้ว","choices":["ขุนช้างขุนแผน","ลิลิตตะเลงพ่าย","กาพย์เห่เรือ","สามก๊ก ฉบับเจ้าพระยาพระคลัง (หน)"],"answer":3,"explanation":{"en":"สามก๊ก, translated from a Chinese historical novel under Chao Phraya Phra Khlang (Hon), is written in prose. ขุนช้างขุนแผน is a เสภา (verse for recitation), ลิลิตตะเลงพ่าย is a ลิลิต (mixed ร่าย and โคลง) and กาพย์เห่เรือ is verse.","th":"สามก๊ก ฉบับเจ้าพระยาพระคลัง (หน) แปลจากพงศาวดารจีนและแต่งเป็นร้อยแก้ว ส่วนขุนช้างขุนแผนเป็นเสภา ลิลิตตะเลงพ่ายเป็นลิลิต (ร่ายกับโคลง) และกาพย์เห่เรือเป็นร้อยกรอง"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Knowledge of literature","th":"ความรู้เรื่องวรรณคดี"},"topic":{"en":"Thai literature","th":"วรรณคดีไทย"},"passage":"","table":null,"lang":"th","stem":"ในเรื่องรามเกียรติ์ \"หนุมาน\" เป็นทหารเอกของฝ่ายใด","choices":["ฝ่ายทศกัณฐ์","ฝ่ายอินทรชิต","ฝ่ายพระราม","ฝ่ายไมยราพ"],"answer":2,"explanation":{"en":"Hanuman, the white monkey warrior, is Phra Ram's (Rama's) chief soldier in the war against the giants of Longka. Thotsakan (Ravana), his son Inthorachit and the giant Maiyarap are all on the opposing giant side.","th":"หนุมาน ลิงเผือกผู้เก่งกล้า เป็นทหารเอกของพระรามในการรบกับฝ่ายยักษ์แห่งกรุงลงกา ส่วนทศกัณฐ์ อินทรชิต (โอรสของทศกัณฐ์) และไมยราพ ล้วนเป็นยักษ์ฝ่ายตรงข้าม"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Identifying the main idea","th":"การจับใจความสำคัญ"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ป่าชายเลนเป็นระบบนิเวศที่อยู่ตรงรอยต่อระหว่างแผ่นดินกับทะเล บริเวณปากแม่น้ำและชายฝั่งที่น้ำทะเลท่วมถึงในช่วงน้ำขึ้นและลดลงในช่วงน้ำลง พืชที่ขึ้นอยู่ในป่าชนิดนี้จึงต้องปรับตัวให้อยู่รอดในดินเลนที่อ่อนนุ่ม ขาดออกซิเจน และมีความเค็มเปลี่ยนแปลงอยู่ตลอดเวลา โกงกางมีรากค้ำจุนแตกออกจากลำต้นโค้งลงปักดินคล้ายขาหยั่ง ช่วยพยุงต้นไม่ให้ล้มเมื่อคลื่นซัด ส่วนแสมและลำพูมีรากหายใจโผล่พ้นเลนขึ้นมาเป็นแท่งเล็ก ๆ เพื่อรับอากาศในช่วงที่น้ำลด\n\nนอกจากรูปร่างที่แปลกตาแล้ว ป่าชายเลนยังมีบทบาทสำคัญที่คนจำนวนมากมองข้าม รากที่สานกันแน่นทำหน้าที่เหมือนตาข่ายดักตะกอนที่ไหลมากับน้ำ ทำให้แผ่นดินค่อย ๆ งอกออกไปในทะเล และลดความรุนแรงของคลื่นลมก่อนจะถึงหมู่บ้านริมฝั่ง ใต้ร่มเงาของต้นไม้ยังเป็นที่วางไข่และอนุบาลสัตว์น้ำวัยอ่อน ทั้งกุ้ง หอย ปู และปลาอีกหลายชนิด ชาวประมงพื้นบ้านจึงเปรียบป่าชายเลนว่าเป็น \"ห้องครัวของทะเล\" เพราะหากไม่มีป่า สัตว์น้ำที่พวกเขาจับได้ในทะเลก็จะลดลงตามไปด้วย\n\nอย่างไรก็ตาม ในช่วงหลายสิบปีที่ผ่านมา ป่าชายเลนหลายแห่งถูกถางเพื่อทำบ่อเลี้ยงกุ้ง สร้างท่าเรือ และขยายชุมชน ผลที่ตามมาไม่ได้เกิดขึ้นทันที แต่ค่อย ๆ ปรากฏให้เห็น ชายฝั่งบางแห่งถูกกัดเซาะลึกเข้ามาหลายสิบเมตร บ้านเรือนต้องย้ายหนีน้ำ ชาวประมงต้องออกเรือไกลขึ้นแต่กลับจับปลาได้น้อยลง ผู้คนจึงเริ่มตระหนักว่ากำไรที่ได้จากการทำลายป่านั้นเป็นเพียงกำไรระยะสั้น ขณะที่ความเสียหายกลับยืดเยื้อยาวนาน\n\nปัจจุบันหลายชุมชนร่วมกันปลูกป่าชายเลนขึ้นใหม่ ทว่าการปลูกให้ได้ผลไม่ใช่เพียงการนำกล้าไม้ไปปักลงในเลน ผู้ปลูกต้องเลือกพันธุ์ไม้ให้เหมาะกับระดับน้ำและชนิดของดินในแต่ละจุด และต้องดูแลกล้าไม้ในช่วงปีแรก ๆ ที่ยังอ่อนแอ บางพื้นที่เคยปลูกโกงกางเพียงชนิดเดียวเรียงเป็นแถวยาว ผลปรากฏว่ากล้าไม้ตายเกือบหมดเพราะอยู่ในจุดที่น้ำท่วมขังนานเกินไป บทเรียนนี้สอนว่าการฟื้นฟูธรรมชาติต้องอาศัยความเข้าใจธรรมชาติ มิใช่อาศัยเพียงความตั้งใจดี","table":null,"lang":"th","stem":"ใจความสำคัญของย่อหน้าที่สองคือข้อใด","choices":["รากของโกงกางมีลักษณะคล้ายขาหยั่ง","ป่าชายเลนช่วยป้องกันชายฝั่งและเป็นแหล่งอนุบาลสัตว์น้ำ","ชาวประมงพื้นบ้านชอบทำอาหารริมทะเล","ป่าชายเลนถูกถางเพื่อทำบ่อเลี้ยงกุ้ง"],"answer":1,"explanation":{"en":"Paragraph 2 explains the mangrove's hidden roles: trapping sediment, softening waves before they reach villages, and sheltering young shrimp, shellfish, crabs and fish. The prop roots belong to paragraph 1, clearing for shrimp ponds to paragraph 3, and the 'kitchen' is a metaphor, not real cooking.","th":"ย่อหน้าที่สองกล่าวถึงบทบาทของป่าชายเลน คือดักตะกอน ลดความรุนแรงของคลื่น และเป็นที่อนุบาลสัตว์น้ำวัยอ่อน ส่วนเรื่องรากค้ำจุนอยู่ในย่อหน้าแรก เรื่องการถางป่าทำบ่อกุ้งอยู่ในย่อหน้าที่สาม และ \"ห้องครัว\" เป็นการเปรียบเทียบ ไม่ใช่การทำอาหารจริง"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Interpreting meaning in context","th":"การตีความหมายตามบริบท"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ป่าชายเลนเป็นระบบนิเวศที่อยู่ตรงรอยต่อระหว่างแผ่นดินกับทะเล บริเวณปากแม่น้ำและชายฝั่งที่น้ำทะเลท่วมถึงในช่วงน้ำขึ้นและลดลงในช่วงน้ำลง พืชที่ขึ้นอยู่ในป่าชนิดนี้จึงต้องปรับตัวให้อยู่รอดในดินเลนที่อ่อนนุ่ม ขาดออกซิเจน และมีความเค็มเปลี่ยนแปลงอยู่ตลอดเวลา โกงกางมีรากค้ำจุนแตกออกจากลำต้นโค้งลงปักดินคล้ายขาหยั่ง ช่วยพยุงต้นไม่ให้ล้มเมื่อคลื่นซัด ส่วนแสมและลำพูมีรากหายใจโผล่พ้นเลนขึ้นมาเป็นแท่งเล็ก ๆ เพื่อรับอากาศในช่วงที่น้ำลด\n\nนอกจากรูปร่างที่แปลกตาแล้ว ป่าชายเลนยังมีบทบาทสำคัญที่คนจำนวนมากมองข้าม รากที่สานกันแน่นทำหน้าที่เหมือนตาข่ายดักตะกอนที่ไหลมากับน้ำ ทำให้แผ่นดินค่อย ๆ งอกออกไปในทะเล และลดความรุนแรงของคลื่นลมก่อนจะถึงหมู่บ้านริมฝั่ง ใต้ร่มเงาของต้นไม้ยังเป็นที่วางไข่และอนุบาลสัตว์น้ำวัยอ่อน ทั้งกุ้ง หอย ปู และปลาอีกหลายชนิด ชาวประมงพื้นบ้านจึงเปรียบป่าชายเลนว่าเป็น \"ห้องครัวของทะเล\" เพราะหากไม่มีป่า สัตว์น้ำที่พวกเขาจับได้ในทะเลก็จะลดลงตามไปด้วย\n\nอย่างไรก็ตาม ในช่วงหลายสิบปีที่ผ่านมา ป่าชายเลนหลายแห่งถูกถางเพื่อทำบ่อเลี้ยงกุ้ง สร้างท่าเรือ และขยายชุมชน ผลที่ตามมาไม่ได้เกิดขึ้นทันที แต่ค่อย ๆ ปรากฏให้เห็น ชายฝั่งบางแห่งถูกกัดเซาะลึกเข้ามาหลายสิบเมตร บ้านเรือนต้องย้ายหนีน้ำ ชาวประมงต้องออกเรือไกลขึ้นแต่กลับจับปลาได้น้อยลง ผู้คนจึงเริ่มตระหนักว่ากำไรที่ได้จากการทำลายป่านั้นเป็นเพียงกำไรระยะสั้น ขณะที่ความเสียหายกลับยืดเยื้อยาวนาน\n\nปัจจุบันหลายชุมชนร่วมกันปลูกป่าชายเลนขึ้นใหม่ ทว่าการปลูกให้ได้ผลไม่ใช่เพียงการนำกล้าไม้ไปปักลงในเลน ผู้ปลูกต้องเลือกพันธุ์ไม้ให้เหมาะกับระดับน้ำและชนิดของดินในแต่ละจุด และต้องดูแลกล้าไม้ในช่วงปีแรก ๆ ที่ยังอ่อนแอ บางพื้นที่เคยปลูกโกงกางเพียงชนิดเดียวเรียงเป็นแถวยาว ผลปรากฏว่ากล้าไม้ตายเกือบหมดเพราะอยู่ในจุดที่น้ำท่วมขังนานเกินไป บทเรียนนี้สอนว่าการฟื้นฟูธรรมชาติต้องอาศัยความเข้าใจธรรมชาติ มิใช่อาศัยเพียงความตั้งใจดี","table":null,"lang":"th","stem":"ที่ชาวประมงเปรียบป่าชายเลนว่าเป็น \"ห้องครัวของทะเล\" หมายความว่าอย่างไร","choices":["ป่าชายเลนเป็นที่ที่ชาวประมงใช้ประกอบอาหาร","ป่าชายเลนมีกลิ่นเหมือนอาหารทะเล","ป่าชายเลนเป็นที่เก็บเครื่องมือประมง","ป่าชายเลนเป็นแหล่งกำเนิดและเลี้ยงดูสัตว์น้ำที่เป็นอาหารของคน"],"answer":3,"explanation":{"en":"The text says young shrimp, shellfish, crabs and fish hatch and grow under the trees, and that without the forest fishermen's catch would fall. So the 'kitchen' is where the sea's food is produced. The other readings take the metaphor literally.","th":"บทอ่านกล่าวว่าใต้ร่มไม้เป็นที่วางไข่และอนุบาลสัตว์น้ำ และถ้าไม่มีป่า สัตว์น้ำที่จับได้ก็จะลดลง \"ห้องครัว\" จึงหมายถึงแหล่งผลิตอาหารของทะเล ตัวเลือกอื่นตีความคำเปรียบตามตัวอักษร"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ป่าชายเลนเป็นระบบนิเวศที่อยู่ตรงรอยต่อระหว่างแผ่นดินกับทะเล บริเวณปากแม่น้ำและชายฝั่งที่น้ำทะเลท่วมถึงในช่วงน้ำขึ้นและลดลงในช่วงน้ำลง พืชที่ขึ้นอยู่ในป่าชนิดนี้จึงต้องปรับตัวให้อยู่รอดในดินเลนที่อ่อนนุ่ม ขาดออกซิเจน และมีความเค็มเปลี่ยนแปลงอยู่ตลอดเวลา โกงกางมีรากค้ำจุนแตกออกจากลำต้นโค้งลงปักดินคล้ายขาหยั่ง ช่วยพยุงต้นไม่ให้ล้มเมื่อคลื่นซัด ส่วนแสมและลำพูมีรากหายใจโผล่พ้นเลนขึ้นมาเป็นแท่งเล็ก ๆ เพื่อรับอากาศในช่วงที่น้ำลด\n\nนอกจากรูปร่างที่แปลกตาแล้ว ป่าชายเลนยังมีบทบาทสำคัญที่คนจำนวนมากมองข้าม รากที่สานกันแน่นทำหน้าที่เหมือนตาข่ายดักตะกอนที่ไหลมากับน้ำ ทำให้แผ่นดินค่อย ๆ งอกออกไปในทะเล และลดความรุนแรงของคลื่นลมก่อนจะถึงหมู่บ้านริมฝั่ง ใต้ร่มเงาของต้นไม้ยังเป็นที่วางไข่และอนุบาลสัตว์น้ำวัยอ่อน ทั้งกุ้ง หอย ปู และปลาอีกหลายชนิด ชาวประมงพื้นบ้านจึงเปรียบป่าชายเลนว่าเป็น \"ห้องครัวของทะเล\" เพราะหากไม่มีป่า สัตว์น้ำที่พวกเขาจับได้ในทะเลก็จะลดลงตามไปด้วย\n\nอย่างไรก็ตาม ในช่วงหลายสิบปีที่ผ่านมา ป่าชายเลนหลายแห่งถูกถางเพื่อทำบ่อเลี้ยงกุ้ง สร้างท่าเรือ และขยายชุมชน ผลที่ตามมาไม่ได้เกิดขึ้นทันที แต่ค่อย ๆ ปรากฏให้เห็น ชายฝั่งบางแห่งถูกกัดเซาะลึกเข้ามาหลายสิบเมตร บ้านเรือนต้องย้ายหนีน้ำ ชาวประมงต้องออกเรือไกลขึ้นแต่กลับจับปลาได้น้อยลง ผู้คนจึงเริ่มตระหนักว่ากำไรที่ได้จากการทำลายป่านั้นเป็นเพียงกำไรระยะสั้น ขณะที่ความเสียหายกลับยืดเยื้อยาวนาน\n\nปัจจุบันหลายชุมชนร่วมกันปลูกป่าชายเลนขึ้นใหม่ ทว่าการปลูกให้ได้ผลไม่ใช่เพียงการนำกล้าไม้ไปปักลงในเลน ผู้ปลูกต้องเลือกพันธุ์ไม้ให้เหมาะกับระดับน้ำและชนิดของดินในแต่ละจุด และต้องดูแลกล้าไม้ในช่วงปีแรก ๆ ที่ยังอ่อนแอ บางพื้นที่เคยปลูกโกงกางเพียงชนิดเดียวเรียงเป็นแถวยาว ผลปรากฏว่ากล้าไม้ตายเกือบหมดเพราะอยู่ในจุดที่น้ำท่วมขังนานเกินไป บทเรียนนี้สอนว่าการฟื้นฟูธรรมชาติต้องอาศัยความเข้าใจธรรมชาติ มิใช่อาศัยเพียงความตั้งใจดี","table":null,"lang":"th","stem":"ข้อใดอนุมานได้จากย่อหน้าที่สาม","choices":["เพราะผลเสียจากการทำลายป่าชายเลนเกิดขึ้นช้า ผู้คนในอดีตจึงมองไม่เห็นความเสียหายในทันที","การเลี้ยงกุ้งเป็นอาชีพที่ผิดกฎหมายทุกพื้นที่","ชาวประมงจับปลาได้มากขึ้นหลังจากป่าชายเลนถูกถาง","ชายฝั่งทุกแห่งในประเทศถูกกัดเซาะลึกหลายสิบเมตร"],"answer":0,"explanation":{"en":"The paragraph says the effects 'did not happen at once but appeared gradually', and that people only 'began to realise' later. This implies the slow damage hid the true cost. The text never says shrimp farming is illegal, says catches fell (not rose), and mentions only 'some' coasts.","th":"ย่อหน้าที่สามกล่าวว่าผลเสีย \"ไม่ได้เกิดขึ้นทันที แต่ค่อย ๆ ปรากฏ\" และผู้คน \"จึงเริ่มตระหนัก\" ภายหลัง จึงอนุมานได้ว่าความเสียหายที่เกิดช้าทำให้คนไม่เห็นผลเสียตั้งแต่แรก บทอ่านไม่ได้บอกว่าการเลี้ยงกุ้งผิดกฎหมาย บอกว่าจับปลาได้น้อยลง และกล่าวถึง \"ชายฝั่งบางแห่ง\" เท่านั้น"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ป่าชายเลนเป็นระบบนิเวศที่อยู่ตรงรอยต่อระหว่างแผ่นดินกับทะเล บริเวณปากแม่น้ำและชายฝั่งที่น้ำทะเลท่วมถึงในช่วงน้ำขึ้นและลดลงในช่วงน้ำลง พืชที่ขึ้นอยู่ในป่าชนิดนี้จึงต้องปรับตัวให้อยู่รอดในดินเลนที่อ่อนนุ่ม ขาดออกซิเจน และมีความเค็มเปลี่ยนแปลงอยู่ตลอดเวลา โกงกางมีรากค้ำจุนแตกออกจากลำต้นโค้งลงปักดินคล้ายขาหยั่ง ช่วยพยุงต้นไม่ให้ล้มเมื่อคลื่นซัด ส่วนแสมและลำพูมีรากหายใจโผล่พ้นเลนขึ้นมาเป็นแท่งเล็ก ๆ เพื่อรับอากาศในช่วงที่น้ำลด\n\nนอกจากรูปร่างที่แปลกตาแล้ว ป่าชายเลนยังมีบทบาทสำคัญที่คนจำนวนมากมองข้าม รากที่สานกันแน่นทำหน้าที่เหมือนตาข่ายดักตะกอนที่ไหลมากับน้ำ ทำให้แผ่นดินค่อย ๆ งอกออกไปในทะเล และลดความรุนแรงของคลื่นลมก่อนจะถึงหมู่บ้านริมฝั่ง ใต้ร่มเงาของต้นไม้ยังเป็นที่วางไข่และอนุบาลสัตว์น้ำวัยอ่อน ทั้งกุ้ง หอย ปู และปลาอีกหลายชนิด ชาวประมงพื้นบ้านจึงเปรียบป่าชายเลนว่าเป็น \"ห้องครัวของทะเล\" เพราะหากไม่มีป่า สัตว์น้ำที่พวกเขาจับได้ในทะเลก็จะลดลงตามไปด้วย\n\nอย่างไรก็ตาม ในช่วงหลายสิบปีที่ผ่านมา ป่าชายเลนหลายแห่งถูกถางเพื่อทำบ่อเลี้ยงกุ้ง สร้างท่าเรือ และขยายชุมชน ผลที่ตามมาไม่ได้เกิดขึ้นทันที แต่ค่อย ๆ ปรากฏให้เห็น ชายฝั่งบางแห่งถูกกัดเซาะลึกเข้ามาหลายสิบเมตร บ้านเรือนต้องย้ายหนีน้ำ ชาวประมงต้องออกเรือไกลขึ้นแต่กลับจับปลาได้น้อยลง ผู้คนจึงเริ่มตระหนักว่ากำไรที่ได้จากการทำลายป่านั้นเป็นเพียงกำไรระยะสั้น ขณะที่ความเสียหายกลับยืดเยื้อยาวนาน\n\nปัจจุบันหลายชุมชนร่วมกันปลูกป่าชายเลนขึ้นใหม่ ทว่าการปลูกให้ได้ผลไม่ใช่เพียงการนำกล้าไม้ไปปักลงในเลน ผู้ปลูกต้องเลือกพันธุ์ไม้ให้เหมาะกับระดับน้ำและชนิดของดินในแต่ละจุด และต้องดูแลกล้าไม้ในช่วงปีแรก ๆ ที่ยังอ่อนแอ บางพื้นที่เคยปลูกโกงกางเพียงชนิดเดียวเรียงเป็นแถวยาว ผลปรากฏว่ากล้าไม้ตายเกือบหมดเพราะอยู่ในจุดที่น้ำท่วมขังนานเกินไป บทเรียนนี้สอนว่าการฟื้นฟูธรรมชาติต้องอาศัยความเข้าใจธรรมชาติ มิใช่อาศัยเพียงความตั้งใจดี","table":null,"lang":"th","stem":"ผู้เขียนยกตัวอย่างการปลูกโกงกางชนิดเดียวที่ล้มเหลว เพื่อสนับสนุนความคิดใด","choices":["โกงกางเป็นพืชที่ไม่เหมาะกับการปลูกในป่าชายเลน","ไม่ควรมีการปลูกป่าชายเลนขึ้นใหม่อีก","ชุมชนควรปลูกป่าให้เป็นแถวตรงเพื่อความสวยงาม","การฟื้นฟูป่าต้องอาศัยความรู้เรื่องสภาพพื้นที่ ไม่ใช่เจตนาดีเพียงอย่างเดียว"],"answer":3,"explanation":{"en":"The failed planting is followed directly by the lesson: restoring nature needs an understanding of nature, not just good intentions. The seedlings died because they were in a spot flooded too long, not because mangrove trees are unsuitable, and the author supports replanting done properly.","th":"ตัวอย่างนี้ตามด้วยข้อสรุปว่า \"การฟื้นฟูธรรมชาติต้องอาศัยความเข้าใจธรรมชาติ มิใช่อาศัยเพียงความตั้งใจดี\" กล้าไม้ตายเพราะปลูกในจุดที่น้ำท่วมขังนานเกินไป ไม่ใช่เพราะโกงกางไม่เหมาะกับป่าชายเลน และผู้เขียนสนับสนุนการปลูกป่าที่ทำอย่างถูกวิธี"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Author's purpose and tone","th":"จุดประสงค์และน้ำเสียงของผู้เขียน"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ป่าชายเลนเป็นระบบนิเวศที่อยู่ตรงรอยต่อระหว่างแผ่นดินกับทะเล บริเวณปากแม่น้ำและชายฝั่งที่น้ำทะเลท่วมถึงในช่วงน้ำขึ้นและลดลงในช่วงน้ำลง พืชที่ขึ้นอยู่ในป่าชนิดนี้จึงต้องปรับตัวให้อยู่รอดในดินเลนที่อ่อนนุ่ม ขาดออกซิเจน และมีความเค็มเปลี่ยนแปลงอยู่ตลอดเวลา โกงกางมีรากค้ำจุนแตกออกจากลำต้นโค้งลงปักดินคล้ายขาหยั่ง ช่วยพยุงต้นไม่ให้ล้มเมื่อคลื่นซัด ส่วนแสมและลำพูมีรากหายใจโผล่พ้นเลนขึ้นมาเป็นแท่งเล็ก ๆ เพื่อรับอากาศในช่วงที่น้ำลด\n\nนอกจากรูปร่างที่แปลกตาแล้ว ป่าชายเลนยังมีบทบาทสำคัญที่คนจำนวนมากมองข้าม รากที่สานกันแน่นทำหน้าที่เหมือนตาข่ายดักตะกอนที่ไหลมากับน้ำ ทำให้แผ่นดินค่อย ๆ งอกออกไปในทะเล และลดความรุนแรงของคลื่นลมก่อนจะถึงหมู่บ้านริมฝั่ง ใต้ร่มเงาของต้นไม้ยังเป็นที่วางไข่และอนุบาลสัตว์น้ำวัยอ่อน ทั้งกุ้ง หอย ปู และปลาอีกหลายชนิด ชาวประมงพื้นบ้านจึงเปรียบป่าชายเลนว่าเป็น \"ห้องครัวของทะเล\" เพราะหากไม่มีป่า สัตว์น้ำที่พวกเขาจับได้ในทะเลก็จะลดลงตามไปด้วย\n\nอย่างไรก็ตาม ในช่วงหลายสิบปีที่ผ่านมา ป่าชายเลนหลายแห่งถูกถางเพื่อทำบ่อเลี้ยงกุ้ง สร้างท่าเรือ และขยายชุมชน ผลที่ตามมาไม่ได้เกิดขึ้นทันที แต่ค่อย ๆ ปรากฏให้เห็น ชายฝั่งบางแห่งถูกกัดเซาะลึกเข้ามาหลายสิบเมตร บ้านเรือนต้องย้ายหนีน้ำ ชาวประมงต้องออกเรือไกลขึ้นแต่กลับจับปลาได้น้อยลง ผู้คนจึงเริ่มตระหนักว่ากำไรที่ได้จากการทำลายป่านั้นเป็นเพียงกำไรระยะสั้น ขณะที่ความเสียหายกลับยืดเยื้อยาวนาน\n\nปัจจุบันหลายชุมชนร่วมกันปลูกป่าชายเลนขึ้นใหม่ ทว่าการปลูกให้ได้ผลไม่ใช่เพียงการนำกล้าไม้ไปปักลงในเลน ผู้ปลูกต้องเลือกพันธุ์ไม้ให้เหมาะกับระดับน้ำและชนิดของดินในแต่ละจุด และต้องดูแลกล้าไม้ในช่วงปีแรก ๆ ที่ยังอ่อนแอ บางพื้นที่เคยปลูกโกงกางเพียงชนิดเดียวเรียงเป็นแถวยาว ผลปรากฏว่ากล้าไม้ตายเกือบหมดเพราะอยู่ในจุดที่น้ำท่วมขังนานเกินไป บทเรียนนี้สอนว่าการฟื้นฟูธรรมชาติต้องอาศัยความเข้าใจธรรมชาติ มิใช่อาศัยเพียงความตั้งใจดี","table":null,"lang":"th","stem":"จุดประสงค์สำคัญของผู้เขียนบทความนี้คือข้อใด","choices":["ให้ความรู้ถึงคุณค่าของป่าชายเลน และชี้ให้เห็นว่าการฟื้นฟูต้องทำอย่างถูกวิธี","ชักชวนให้ผู้อ่านไปท่องเที่ยวป่าชายเลน","โฆษณาการเลี้ยงกุ้งที่ได้กำไรสูง","ตำหนิชาวประมงพื้นบ้านที่ทำลายป่า"],"answer":0,"explanation":{"en":"The article describes how mangroves survive, what they do for coasts and fish, what happened when they were cleared, and how to replant them well — informing readers and pointing to sound restoration. It does not promote tourism or shrimp farming, and it blames clearing for ponds, ports and towns, not small-scale fishermen.","th":"บทความอธิบายการปรับตัวของป่าชายเลน ประโยชน์ต่อชายฝั่งและสัตว์น้ำ ผลเสียเมื่อป่าถูกทำลาย และแนวทางปลูกป่าที่ถูกต้อง จึงมุ่งให้ความรู้และชี้แนวทางการฟื้นฟู ไม่ได้ชวนเที่ยวหรือโฆษณาการเลี้ยงกุ้ง และไม่ได้ตำหนิชาวประมงพื้นบ้าน ซึ่งเป็นผู้ได้รับผลกระทบ"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ภูมิได้จักรยานคันเก่าของพ่อมาในวันที่อายุครบสิบสองปี มันเป็นจักรยานสีเขียวที่สีลอกเป็นดวง ๆ โซ่ฝืด และเบรกหลังแทบไม่ทำงาน ภูมิมองมันแล้วถอนหายใจ เพื่อนในห้องหลายคนมีจักรยานใหม่เอี่ยมที่เปลี่ยนเกียร์ได้หลายระดับ เขานึกในใจว่าหากขี่คันนี้ไปโรงเรียน คงถูกเพื่อนล้อไม่เว้นแต่ละวัน\n\nตาของภูมิเดินมาเห็นสีหน้าของหลานจึงไม่พูดอะไร เพียงหยิบกล่องเครื่องมือเก่าออกมาวางไว้ข้างจักรยาน แล้วนั่งลงบนม้านั่งไม้ใต้ต้นมะม่วง \"ช่วยตาหน่อยสิ ตามือไม่ค่อยดีแล้ว\" ภูมิจำใจนั่งลงข้าง ๆ ตาสอนให้เขาถอดโซ่ออกมาแช่น้ำมัน ใช้แปรงสีฟันเก่าขัดคราบสนิมทีละข้อ ตาไม่เคยรีบ บางครั้งก็นั่งนิ่งมองชิ้นส่วนในมือนานจนภูมิอดใจไม่ไหว \"ทำไมตาไม่ซื้อโซ่ใหม่ล่ะครับ เร็วกว่าตั้งเยอะ\" ตาหัวเราะเบา ๆ \"ของบางอย่างซื้อใหม่ได้ แต่ความเข้าใจซื้อไม่ได้นะหลาน\"\n\nทุกเย็นหลังเลิกเรียน ภูมิกลับมาซ่อมจักรยานกับตา สัปดาห์แรกเขาทำน็อตหายไปสองตัว สัปดาห์ที่สองเขาประกอบเบรกกลับด้านจนต้องรื้อใหม่ทั้งหมด แต่ยิ่งทำ เขายิ่งรู้ว่าล้อหมุนได้เพราะอะไร เบรกหยุดล้อได้อย่างไร และเสียงดังกริ๊ก ๆ ที่น่ารำคาญนั้นมาจากตรงไหน วันหนึ่งเขาพบว่าตัวเองนั่งลืมเวลาไปเกือบสองชั่วโมงโดยไม่ได้แตะโทรศัพท์เลย\n\nต้นเดือนถัดมา ภูมิขี่จักรยานสีเขียวที่เขาทาสีใหม่เองไปโรงเรียน ระหว่างทาง เขาเห็นต้น เพื่อนสนิท ยืนหน้าเสียอยู่ข้างจักรยานคันใหม่ที่โซ่หลุด ภูมิจอดรถ ใช้เวลาไม่ถึงห้านาทีก็ใส่โซ่กลับเข้าที่ได้ ต้นมองเพื่อนด้วยสายตาทึ่ง \"นายทำเป็นตั้งแต่เมื่อไร\" ภูมิยิ้ม นึกถึงม้านั่งไม้ใต้ต้นมะม่วงและมือที่สั่นเล็กน้อยของตา แล้วตอบสั้น ๆ ว่า \"ตั้งแต่ไม่รีบน่ะ\"","table":null,"lang":"th","stem":"เมื่อได้รับจักรยานในตอนแรก ภูมิรู้สึกอย่างไร","choices":["ดีใจที่ได้จักรยานของพ่อ","ภูมิใจที่จะได้ซ่อมจักรยานเอง","ผิดหวังและกังวลว่าจะถูกเพื่อนล้อ","โกรธตาที่ไม่ซื้อจักรยานใหม่ให้"],"answer":2,"explanation":{"en":"Phum sighs at the bike and thinks his classmates, who have new bikes, will tease him every day — disappointment and worry. He is not yet proud or happy, and he does not blame his grandfather; the grandfather only appears afterwards.","th":"ภูมิถอนหายใจเมื่อมองจักรยาน และคิดว่าถ้าขี่ไปโรงเรียนคงถูกเพื่อนล้อทุกวัน แสดงความผิดหวังและกังวล เขายังไม่ได้ดีใจหรือภูมิใจ และไม่ได้โกรธตา เพราะตาเพิ่งปรากฏตัวหลังจากนั้น"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ภูมิได้จักรยานคันเก่าของพ่อมาในวันที่อายุครบสิบสองปี มันเป็นจักรยานสีเขียวที่สีลอกเป็นดวง ๆ โซ่ฝืด และเบรกหลังแทบไม่ทำงาน ภูมิมองมันแล้วถอนหายใจ เพื่อนในห้องหลายคนมีจักรยานใหม่เอี่ยมที่เปลี่ยนเกียร์ได้หลายระดับ เขานึกในใจว่าหากขี่คันนี้ไปโรงเรียน คงถูกเพื่อนล้อไม่เว้นแต่ละวัน\n\nตาของภูมิเดินมาเห็นสีหน้าของหลานจึงไม่พูดอะไร เพียงหยิบกล่องเครื่องมือเก่าออกมาวางไว้ข้างจักรยาน แล้วนั่งลงบนม้านั่งไม้ใต้ต้นมะม่วง \"ช่วยตาหน่อยสิ ตามือไม่ค่อยดีแล้ว\" ภูมิจำใจนั่งลงข้าง ๆ ตาสอนให้เขาถอดโซ่ออกมาแช่น้ำมัน ใช้แปรงสีฟันเก่าขัดคราบสนิมทีละข้อ ตาไม่เคยรีบ บางครั้งก็นั่งนิ่งมองชิ้นส่วนในมือนานจนภูมิอดใจไม่ไหว \"ทำไมตาไม่ซื้อโซ่ใหม่ล่ะครับ เร็วกว่าตั้งเยอะ\" ตาหัวเราะเบา ๆ \"ของบางอย่างซื้อใหม่ได้ แต่ความเข้าใจซื้อไม่ได้นะหลาน\"\n\nทุกเย็นหลังเลิกเรียน ภูมิกลับมาซ่อมจักรยานกับตา สัปดาห์แรกเขาทำน็อตหายไปสองตัว สัปดาห์ที่สองเขาประกอบเบรกกลับด้านจนต้องรื้อใหม่ทั้งหมด แต่ยิ่งทำ เขายิ่งรู้ว่าล้อหมุนได้เพราะอะไร เบรกหยุดล้อได้อย่างไร และเสียงดังกริ๊ก ๆ ที่น่ารำคาญนั้นมาจากตรงไหน วันหนึ่งเขาพบว่าตัวเองนั่งลืมเวลาไปเกือบสองชั่วโมงโดยไม่ได้แตะโทรศัพท์เลย\n\nต้นเดือนถัดมา ภูมิขี่จักรยานสีเขียวที่เขาทาสีใหม่เองไปโรงเรียน ระหว่างทาง เขาเห็นต้น เพื่อนสนิท ยืนหน้าเสียอยู่ข้างจักรยานคันใหม่ที่โซ่หลุด ภูมิจอดรถ ใช้เวลาไม่ถึงห้านาทีก็ใส่โซ่กลับเข้าที่ได้ ต้นมองเพื่อนด้วยสายตาทึ่ง \"นายทำเป็นตั้งแต่เมื่อไร\" ภูมิยิ้ม นึกถึงม้านั่งไม้ใต้ต้นมะม่วงและมือที่สั่นเล็กน้อยของตา แล้วตอบสั้น ๆ ว่า \"ตั้งแต่ไม่รีบน่ะ\"","table":null,"lang":"th","stem":"การที่ตาพูดว่า \"ช่วยตาหน่อยสิ ตามือไม่ค่อยดีแล้ว\" ตามีเจตนาใดมากที่สุด","choices":["ต้องการให้ภูมิซ่อมจักรยานแทนเพราะตาทำไม่ได้แล้ว","หาวิธีให้ภูมิได้ลงมือซ่อมและเรียนรู้ด้วยตนเองโดยไม่ต้องบังคับ","ต้องการบ่นเรื่องสุขภาพให้หลานฟัง","ต้องการให้ภูมิยอมแพ้และซื้อจักรยานคันใหม่"],"answer":1,"explanation":{"en":"The grandfather saw Phum's face and 'said nothing', then quietly set out the tools and asked for help. Instead of lecturing, he gave Phum a reason to join in. He keeps teaching and working alongside Phum, so he is not simply handing the job over, and the story never suggests buying a new bike.","th":"ตาเห็นสีหน้าหลานแล้ว \"ไม่พูดอะไร\" แต่หยิบเครื่องมือมาวางและขอให้ช่วย แทนการสั่งสอนตรง ๆ ตาสร้างเหตุผลให้ภูมิเข้ามาลงมือเอง และตายังคงนั่งสอนอยู่ด้วยตลอด จึงไม่ใช่การโยนงานให้ทำแทน และเรื่องไม่ได้ชี้ไปที่การซื้อจักรยานใหม่"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Interpreting meaning in context","th":"การตีความหมายตามบริบท"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ภูมิได้จักรยานคันเก่าของพ่อมาในวันที่อายุครบสิบสองปี มันเป็นจักรยานสีเขียวที่สีลอกเป็นดวง ๆ โซ่ฝืด และเบรกหลังแทบไม่ทำงาน ภูมิมองมันแล้วถอนหายใจ เพื่อนในห้องหลายคนมีจักรยานใหม่เอี่ยมที่เปลี่ยนเกียร์ได้หลายระดับ เขานึกในใจว่าหากขี่คันนี้ไปโรงเรียน คงถูกเพื่อนล้อไม่เว้นแต่ละวัน\n\nตาของภูมิเดินมาเห็นสีหน้าของหลานจึงไม่พูดอะไร เพียงหยิบกล่องเครื่องมือเก่าออกมาวางไว้ข้างจักรยาน แล้วนั่งลงบนม้านั่งไม้ใต้ต้นมะม่วง \"ช่วยตาหน่อยสิ ตามือไม่ค่อยดีแล้ว\" ภูมิจำใจนั่งลงข้าง ๆ ตาสอนให้เขาถอดโซ่ออกมาแช่น้ำมัน ใช้แปรงสีฟันเก่าขัดคราบสนิมทีละข้อ ตาไม่เคยรีบ บางครั้งก็นั่งนิ่งมองชิ้นส่วนในมือนานจนภูมิอดใจไม่ไหว \"ทำไมตาไม่ซื้อโซ่ใหม่ล่ะครับ เร็วกว่าตั้งเยอะ\" ตาหัวเราะเบา ๆ \"ของบางอย่างซื้อใหม่ได้ แต่ความเข้าใจซื้อไม่ได้นะหลาน\"\n\nทุกเย็นหลังเลิกเรียน ภูมิกลับมาซ่อมจักรยานกับตา สัปดาห์แรกเขาทำน็อตหายไปสองตัว สัปดาห์ที่สองเขาประกอบเบรกกลับด้านจนต้องรื้อใหม่ทั้งหมด แต่ยิ่งทำ เขายิ่งรู้ว่าล้อหมุนได้เพราะอะไร เบรกหยุดล้อได้อย่างไร และเสียงดังกริ๊ก ๆ ที่น่ารำคาญนั้นมาจากตรงไหน วันหนึ่งเขาพบว่าตัวเองนั่งลืมเวลาไปเกือบสองชั่วโมงโดยไม่ได้แตะโทรศัพท์เลย\n\nต้นเดือนถัดมา ภูมิขี่จักรยานสีเขียวที่เขาทาสีใหม่เองไปโรงเรียน ระหว่างทาง เขาเห็นต้น เพื่อนสนิท ยืนหน้าเสียอยู่ข้างจักรยานคันใหม่ที่โซ่หลุด ภูมิจอดรถ ใช้เวลาไม่ถึงห้านาทีก็ใส่โซ่กลับเข้าที่ได้ ต้นมองเพื่อนด้วยสายตาทึ่ง \"นายทำเป็นตั้งแต่เมื่อไร\" ภูมิยิ้ม นึกถึงม้านั่งไม้ใต้ต้นมะม่วงและมือที่สั่นเล็กน้อยของตา แล้วตอบสั้น ๆ ว่า \"ตั้งแต่ไม่รีบน่ะ\"","table":null,"lang":"th","stem":"คำพูดของตาที่ว่า \"ของบางอย่างซื้อใหม่ได้ แต่ความเข้าใจซื้อไม่ได้\" สะท้อนแนวคิดใด","choices":["ของเก่ามีค่ามากกว่าของใหม่เสมอ","ไม่ควรใช้เงินซื้อสิ่งของใด ๆ","ความรู้ความเข้าใจที่แท้จริงเกิดจากการลงมือทำด้วยตนเอง","คนแก่เข้าใจเรื่องจักรยานมากกว่าคนหนุ่ม"],"answer":2,"explanation":{"en":"A new chain can be bought, but understanding how the bike works can only come from working on it — and the next paragraph shows Phum gaining exactly that understanding. The grandfather is not saying old is always better or that money should never be spent.","th":"โซ่ใหม่ซื้อได้ แต่ความเข้าใจว่าจักรยานทำงานอย่างไรต้องได้จากการลงมือทำเอง ซึ่งย่อหน้าต่อมาแสดงให้เห็นว่าภูมิได้ความเข้าใจนั้นจริง ตาไม่ได้หมายความว่าของเก่าดีกว่าเสมอ หรือห้ามใช้เงินซื้อของ"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ภูมิได้จักรยานคันเก่าของพ่อมาในวันที่อายุครบสิบสองปี มันเป็นจักรยานสีเขียวที่สีลอกเป็นดวง ๆ โซ่ฝืด และเบรกหลังแทบไม่ทำงาน ภูมิมองมันแล้วถอนหายใจ เพื่อนในห้องหลายคนมีจักรยานใหม่เอี่ยมที่เปลี่ยนเกียร์ได้หลายระดับ เขานึกในใจว่าหากขี่คันนี้ไปโรงเรียน คงถูกเพื่อนล้อไม่เว้นแต่ละวัน\n\nตาของภูมิเดินมาเห็นสีหน้าของหลานจึงไม่พูดอะไร เพียงหยิบกล่องเครื่องมือเก่าออกมาวางไว้ข้างจักรยาน แล้วนั่งลงบนม้านั่งไม้ใต้ต้นมะม่วง \"ช่วยตาหน่อยสิ ตามือไม่ค่อยดีแล้ว\" ภูมิจำใจนั่งลงข้าง ๆ ตาสอนให้เขาถอดโซ่ออกมาแช่น้ำมัน ใช้แปรงสีฟันเก่าขัดคราบสนิมทีละข้อ ตาไม่เคยรีบ บางครั้งก็นั่งนิ่งมองชิ้นส่วนในมือนานจนภูมิอดใจไม่ไหว \"ทำไมตาไม่ซื้อโซ่ใหม่ล่ะครับ เร็วกว่าตั้งเยอะ\" ตาหัวเราะเบา ๆ \"ของบางอย่างซื้อใหม่ได้ แต่ความเข้าใจซื้อไม่ได้นะหลาน\"\n\nทุกเย็นหลังเลิกเรียน ภูมิกลับมาซ่อมจักรยานกับตา สัปดาห์แรกเขาทำน็อตหายไปสองตัว สัปดาห์ที่สองเขาประกอบเบรกกลับด้านจนต้องรื้อใหม่ทั้งหมด แต่ยิ่งทำ เขายิ่งรู้ว่าล้อหมุนได้เพราะอะไร เบรกหยุดล้อได้อย่างไร และเสียงดังกริ๊ก ๆ ที่น่ารำคาญนั้นมาจากตรงไหน วันหนึ่งเขาพบว่าตัวเองนั่งลืมเวลาไปเกือบสองชั่วโมงโดยไม่ได้แตะโทรศัพท์เลย\n\nต้นเดือนถัดมา ภูมิขี่จักรยานสีเขียวที่เขาทาสีใหม่เองไปโรงเรียน ระหว่างทาง เขาเห็นต้น เพื่อนสนิท ยืนหน้าเสียอยู่ข้างจักรยานคันใหม่ที่โซ่หลุด ภูมิจอดรถ ใช้เวลาไม่ถึงห้านาทีก็ใส่โซ่กลับเข้าที่ได้ ต้นมองเพื่อนด้วยสายตาทึ่ง \"นายทำเป็นตั้งแต่เมื่อไร\" ภูมิยิ้ม นึกถึงม้านั่งไม้ใต้ต้นมะม่วงและมือที่สั่นเล็กน้อยของตา แล้วตอบสั้น ๆ ว่า \"ตั้งแต่ไม่รีบน่ะ\"","table":null,"lang":"th","stem":"คำตอบของภูมิที่ว่า \"ตั้งแต่ไม่รีบน่ะ\" ในตอนจบ แสดงให้เห็นสิ่งใด","choices":["ภูมิไม่อยากบอกความจริงกับเพื่อน","ภูมิเข้าใจแล้วว่าความอดทนและการค่อย ๆ เรียนรู้ทำให้เขามีความสามารถนี้","ภูมิคิดว่าการซ่อมจักรยานเป็นเรื่องง่ายที่ใครก็ทำได้","ภูมิต้องการอวดว่าจักรยานของตนดีกว่าของเพื่อน"],"answer":1,"explanation":{"en":"Earlier Phum was impatient ('a new chain is much faster') while his grandfather 'never rushed'. His answer echoes that lesson: the skill came from slowing down and learning patiently. He is remembering his grandfather fondly, not hiding the truth, boasting, or calling it easy.","th":"ตอนต้นภูมิใจร้อน (ซื้อโซ่ใหม่เร็วกว่า) ส่วนตา \"ไม่เคยรีบ\" คำตอบตอนจบจึงสะท้อนบทเรียนจากตาว่าความสามารถนี้มาจากการไม่เร่งรีบและอดทนเรียนรู้ ภูมิกำลังนึกถึงตาด้วยความซาบซึ้ง ไม่ได้ปิดบังความจริง ไม่ได้อวด และไม่ได้คิดว่าเป็นเรื่องง่าย"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Recognising verse forms","th":"การวิเคราะห์ลักษณะคำประพันธ์"},"topic":{"en":"Reading poetry","th":"การอ่านบทร้อยกรอง"},"passage":"เช้าตรู่ริมคุ้งน้ำ          เรือน้อยลำเล็กล่องมา\nผักปลาใส่ตะกร้า          ส่งยิ้มทักทายกันไป\n\nยายเล่าเมื่อวัยเยาว์          น้ำใสเงาสะท้อนไพร\nปลาว่ายให้เห็นได้          ก้นคลองสะอาดทุกแห่ง\n\nวันนี้น้ำขุ่นข้น          ถุงขวดปนกลิ่นเหม็นแรง\nปลาหนีหายจากแหล่ง          ยายมองนิ่งน้ำตาคลอ\n\nหลานจึงชวนเพื่อนพ้อง          ช่วยกันลงเก็บไม่รอ\nทุกบ้านร่วมใจก่อ          ร้านรับขยะชุมชน\n\nผ่านไปหนึ่งปีเศษ          คลองทั้งเขตใสเพราะคน\nปลากลับมาว่ายวน          ยายยิ้มได้อีกครั้งหนึ่ง","table":null,"lang":"th","stem":"บทร้อยกรองนี้แต่งด้วยคำประพันธ์ชนิดใด","choices":["กลอนสุภาพ","กาพย์ฉบัง 16","กาพย์ยานี 11","โคลงสี่สุภาพ"],"answer":2,"explanation":{"en":"Each line has a 5-syllable first half and a 6-syllable second half (11 syllables), with two lines per stanza — the pattern of กาพย์ยานี 11. กลอนสุภาพ has about 8 syllables per half-line, กาพย์ฉบัง 16 has 6-4-6, and โคลงสี่สุภาพ has four lines with fixed เอก–โท tones.","th":"แต่ละบาทมีวรรคหน้า 5 คำ วรรคหลัง 6 คำ รวม 11 คำ บทละ 2 บาท ตรงกับลักษณะของกาพย์ยานี 11 ส่วนกลอนสุภาพมีวรรคละประมาณ 8 คำ กาพย์ฉบัง 16 มีวรรค 6-4-6 และโคลงสี่สุภาพมี 4 บาท และบังคับเอกโท"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Recognising verse forms","th":"การวิเคราะห์ลักษณะคำประพันธ์"},"topic":{"en":"Reading poetry","th":"การอ่านบทร้อยกรอง"},"passage":"เช้าตรู่ริมคุ้งน้ำ          เรือน้อยลำเล็กล่องมา\nผักปลาใส่ตะกร้า          ส่งยิ้มทักทายกันไป\n\nยายเล่าเมื่อวัยเยาว์          น้ำใสเงาสะท้อนไพร\nปลาว่ายให้เห็นได้          ก้นคลองสะอาดทุกแห่ง\n\nวันนี้น้ำขุ่นข้น          ถุงขวดปนกลิ่นเหม็นแรง\nปลาหนีหายจากแหล่ง          ยายมองนิ่งน้ำตาคลอ\n\nหลานจึงชวนเพื่อนพ้อง          ช่วยกันลงเก็บไม่รอ\nทุกบ้านร่วมใจก่อ          ร้านรับขยะชุมชน\n\nผ่านไปหนึ่งปีเศษ          คลองทั้งเขตใสเพราะคน\nปลากลับมาว่ายวน          ยายยิ้มได้อีกครั้งหนึ่ง","table":null,"lang":"th","stem":"คำใดในบทที่ 2 รับสัมผัสระหว่างบทกับคำว่า \"ไป\" ซึ่งเป็นคำสุดท้ายของบทที่ 1","choices":["เยาว์","ได้","แห่ง","ไพร"],"answer":3,"explanation":{"en":"In กาพย์ยานี the last word of a stanza rhymes with the last word of the second half-line (วรรคที่ 2) of the next stanza. In stanza 2 that word is ไพร, which rhymes with ไป. ได้ rhymes with ไพร inside stanza 2, เยาว์ ends the first half-line, and แห่ง ends stanza 2.","th":"สัมผัสระหว่างบทของกาพย์ยานี คือคำสุดท้ายของบทแรกส่งสัมผัสไปยังคำสุดท้ายของวรรคที่ 2 ของบทถัดไป ในบทที่ 2 คำนั้นคือ ไพร ซึ่งสัมผัสกับ ไป ส่วน ได้ เป็นสัมผัสภายในบทที่ 2 เยาว์ เป็นคำท้ายวรรคแรก และ แห่ง เป็นคำท้ายบทที่ 2"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Identifying the main idea","th":"การจับใจความสำคัญ"},"topic":{"en":"Reading poetry","th":"การอ่านบทร้อยกรอง"},"passage":"เช้าตรู่ริมคุ้งน้ำ          เรือน้อยลำเล็กล่องมา\nผักปลาใส่ตะกร้า          ส่งยิ้มทักทายกันไป\n\nยายเล่าเมื่อวัยเยาว์          น้ำใสเงาสะท้อนไพร\nปลาว่ายให้เห็นได้          ก้นคลองสะอาดทุกแห่ง\n\nวันนี้น้ำขุ่นข้น          ถุงขวดปนกลิ่นเหม็นแรง\nปลาหนีหายจากแหล่ง          ยายมองนิ่งน้ำตาคลอ\n\nหลานจึงชวนเพื่อนพ้อง          ช่วยกันลงเก็บไม่รอ\nทุกบ้านร่วมใจก่อ          ร้านรับขยะชุมชน\n\nผ่านไปหนึ่งปีเศษ          คลองทั้งเขตใสเพราะคน\nปลากลับมาว่ายวน          ยายยิ้มได้อีกครั้งหนึ่ง","table":null,"lang":"th","stem":"บทที่ 3 สะท้อนปัญหาใด","choices":["น้ำท่วมบ้านเรือนริมคลอง","การค้าขายทางเรือที่ซบเซาลง","มลพิษทางน้ำจากขยะที่ทำให้สัตว์น้ำสูญเสียแหล่งที่อยู่","ผู้สูงอายุไม่มีคนดูแล"],"answer":2,"explanation":{"en":"Stanza 3 shows murky water, bags and bottles, a strong smell and fish 'fleeing their home' — water pollution from rubbish destroying the fish habitat. Grandma's tears are a reaction to this, not a sign that she is neglected, and there is no flood or trade problem.","th":"บทที่ 3 กล่าวถึงน้ำขุ่น ถุงและขวดลอยปน กลิ่นเหม็น และปลาหนีหายจากแหล่ง แสดงปัญหามลพิษทางน้ำจากขยะที่ทำลายที่อยู่ของสัตว์น้ำ น้ำตาของยายเป็นความเศร้าต่อสภาพคลอง ไม่ได้แสดงว่ายายขาดคนดูแล และไม่มีเรื่องน้ำท่วมหรือการค้า"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading poetry","th":"การอ่านบทร้อยกรอง"},"passage":"เช้าตรู่ริมคุ้งน้ำ          เรือน้อยลำเล็กล่องมา\nผักปลาใส่ตะกร้า          ส่งยิ้มทักทายกันไป\n\nยายเล่าเมื่อวัยเยาว์          น้ำใสเงาสะท้อนไพร\nปลาว่ายให้เห็นได้          ก้นคลองสะอาดทุกแห่ง\n\nวันนี้น้ำขุ่นข้น          ถุงขวดปนกลิ่นเหม็นแรง\nปลาหนีหายจากแหล่ง          ยายมองนิ่งน้ำตาคลอ\n\nหลานจึงชวนเพื่อนพ้อง          ช่วยกันลงเก็บไม่รอ\nทุกบ้านร่วมใจก่อ          ร้านรับขยะชุมชน\n\nผ่านไปหนึ่งปีเศษ          คลองทั้งเขตใสเพราะคน\nปลากลับมาว่ายวน          ยายยิ้มได้อีกครั้งหนึ่ง","table":null,"lang":"th","stem":"คำว่า \"อีกครั้งหนึ่ง\" ในวรรคสุดท้าย สื่อความหมายใด","choices":["ยายยิ้มเพียงครั้งเดียวตลอดทั้งปี","ยายจะยิ้มอีกเฉพาะเมื่อได้ขายผักปลา","คลองจะสกปรกอีกครั้งในไม่ช้า","ยายเคยมีความสุขกับคลองที่สะอาดในอดีต และกลับมามีความสุขอีกเมื่อคลองฟื้นคืน"],"answer":3,"explanation":{"en":"Stanza 2 shows Grandma's happy memories of a clear canal, and stanza 3 her tears at its pollution. 'Smiling again' links the restored canal back to that earlier happiness. Nothing suggests she smiled only once, that it depends on selling goods, or that the canal will get dirty again.","th":"บทที่ 2 เป็นความทรงจำที่มีความสุขของยายเมื่อคลองยังใส และบทที่ 3 ยายน้ำตาคลอเมื่อคลองสกปรก \"ยิ้มได้อีกครั้งหนึ่ง\" จึงหมายถึงความสุขเดิมกลับคืนมาเมื่อคลองฟื้นตัว ไม่มีส่วนใดบอกว่ายายยิ้มครั้งเดียว ยิ้มเพราะขายของ หรือคลองจะสกปรกอีก"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Identifying the main idea","th":"การจับใจความสำคัญ"},"topic":{"en":"Reading poetry","th":"การอ่านบทร้อยกรอง"},"passage":"เช้าตรู่ริมคุ้งน้ำ          เรือน้อยลำเล็กล่องมา\nผักปลาใส่ตะกร้า          ส่งยิ้มทักทายกันไป\n\nยายเล่าเมื่อวัยเยาว์          น้ำใสเงาสะท้อนไพร\nปลาว่ายให้เห็นได้          ก้นคลองสะอาดทุกแห่ง\n\nวันนี้น้ำขุ่นข้น          ถุงขวดปนกลิ่นเหม็นแรง\nปลาหนีหายจากแหล่ง          ยายมองนิ่งน้ำตาคลอ\n\nหลานจึงชวนเพื่อนพ้อง          ช่วยกันลงเก็บไม่รอ\nทุกบ้านร่วมใจก่อ          ร้านรับขยะชุมชน\n\nผ่านไปหนึ่งปีเศษ          คลองทั้งเขตใสเพราะคน\nปลากลับมาว่ายวน          ยายยิ้มได้อีกครั้งหนึ่ง","table":null,"lang":"th","stem":"ข้อคิดสำคัญของบทร้อยกรองนี้คือข้อใด","choices":["เด็กควรเชื่อฟังคำสั่งของผู้ใหญ่ทุกเรื่อง","ธรรมชาติฟื้นตัวได้เองเสมอโดยไม่ต้องทำอะไร","การค้าขายทางเรือดีกว่าการค้าขายทางบก","ปัญหาสิ่งแวดล้อมของชุมชนแก้ไขได้ด้วยความร่วมมือของทุกคน"],"answer":3,"explanation":{"en":"The turning point is stanza 4: the grandchild gathers friends, every household joins in and a community rubbish shop is set up; stanza 5 credits the clear canal to people ('ใสเพราะคน'). So cooperation solves the problem. The canal did not recover by itself, and the children act on their own initiative, not because they were ordered to.","th":"จุดเปลี่ยนของเรื่องอยู่ในบทที่ 4 ที่หลานชวนเพื่อน ทุกบ้านร่วมใจ และตั้งร้านรับขยะชุมชน บทที่ 5 ยังบอกว่าคลองใส \"เพราะคน\" ข้อคิดจึงเป็นเรื่องความร่วมมือ คลองไม่ได้ฟื้นเอง และเด็ก ๆ ลงมือเองโดยไม่มีใครสั่ง"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"e","skill":{"en":"Interpreting meaning in context","th":"การตีความหมายตามบริบท"},"topic":{"en":"Reading poetry","th":"การอ่านบทร้อยกรอง"},"passage":"ความรู้เปรียบเมล็ดพันธุ์อันน้อยนิด          หากเพาะจิตด้วยเพียรจะเติบใหญ่\nรดด้วยครูผู้รักและห่วงใย          มีแสงไฟจากตำราพาเติบกล้า\n\nแต่บางคนเร่งร้อนอยากได้ผล          ไม่อดทนรอวันฝนพร่างฟ้า\nถอนต้นอ่อนดูรากทุกเวลา          สุดท้ายกล้าก็ตายไปเปล่าเปล่า\n\nจงหมั่นเรียนหมั่นถามอย่างตั้งใจ          แม้ช้าไปบ้างอย่าท้อเลยเรา\nวันหนึ่งต้นไม้จะให้ร่มเงา          แก่ผู้เยาว์ผู้เหนื่อยล้าทุกหนทาง","table":null,"lang":"th","stem":"ในบทที่ 1 ผู้แต่งเปรียบ \"ความรู้\" กับสิ่งใด","choices":["เมล็ดพันธุ์ที่ต้องได้รับการดูแลจึงจะเติบโต","แสงไฟที่ส่องทางในความมืด","ครูผู้รักและห่วงใยศิษย์","ร่มเงาของต้นไม้ใหญ่"],"answer":0,"explanation":{"en":"The first line says knowledge is like a tiny seed that grows big if nurtured with effort. Teachers are the 'water' and books the 'light' that help the seed grow — they are the seed's helpers, not what knowledge is compared to.","th":"วรรคแรกกล่าวว่า \"ความรู้เปรียบเมล็ดพันธุ์อันน้อยนิด\" ที่จะเติบใหญ่เมื่อเพาะด้วยความเพียร ส่วนครูเปรียบเป็นน้ำที่รด และตำราเปรียบเป็นแสงไฟ ซึ่งเป็นสิ่งที่ช่วยให้เมล็ดเติบโต ไม่ใช่สิ่งที่ความรู้ถูกเปรียบด้วย"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading poetry","th":"การอ่านบทร้อยกรอง"},"passage":"ความรู้เปรียบเมล็ดพันธุ์อันน้อยนิด          หากเพาะจิตด้วยเพียรจะเติบใหญ่\nรดด้วยครูผู้รักและห่วงใย          มีแสงไฟจากตำราพาเติบกล้า\n\nแต่บางคนเร่งร้อนอยากได้ผล          ไม่อดทนรอวันฝนพร่างฟ้า\nถอนต้นอ่อนดูรากทุกเวลา          สุดท้ายกล้าก็ตายไปเปล่าเปล่า\n\nจงหมั่นเรียนหมั่นถามอย่างตั้งใจ          แม้ช้าไปบ้างอย่าท้อเลยเรา\nวันหนึ่งต้นไม้จะให้ร่มเงา          แก่ผู้เยาว์ผู้เหนื่อยล้าทุกหนทาง","table":null,"lang":"th","stem":"วรรค \"ถอนต้นอ่อนดูรากทุกเวลา\" ผู้แต่งต้องการตำหนิพฤติกรรมใดของผู้เรียน","choices":["ไม่ชอบปลูกต้นไม้","ใจร้อนอยากเห็นผลเร็ว จนขัดขวางการเรียนรู้ของตนเอง","ไม่ยอมถามครูเมื่อไม่เข้าใจ","อ่านหนังสือมากเกินไปจนเหนื่อย"],"answer":1,"explanation":{"en":"Pulling up a seedling to check its roots kills it. In the poem it stands for learners who are 'in a hurry for results' (เร่งร้อนอยากได้ผล) and keep checking for quick success instead of letting learning grow, so their effort comes to nothing. It is a metaphor, not literally about gardening.","th":"การถอนต้นอ่อนขึ้นมาดูรากบ่อย ๆ ทำให้ต้นกล้าตาย ในบทกลอนเปรียบกับผู้ที่ \"เร่งร้อนอยากได้ผล\" ไม่อดทนรอให้ความรู้เติบโต จนสุดท้ายการเรียนสูญเปล่า เป็นการเปรียบเทียบ ไม่ได้หมายถึงการปลูกต้นไม้จริง"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading poetry","th":"การอ่านบทร้อยกรอง"},"passage":"ความรู้เปรียบเมล็ดพันธุ์อันน้อยนิด          หากเพาะจิตด้วยเพียรจะเติบใหญ่\nรดด้วยครูผู้รักและห่วงใย          มีแสงไฟจากตำราพาเติบกล้า\n\nแต่บางคนเร่งร้อนอยากได้ผล          ไม่อดทนรอวันฝนพร่างฟ้า\nถอนต้นอ่อนดูรากทุกเวลา          สุดท้ายกล้าก็ตายไปเปล่าเปล่า\n\nจงหมั่นเรียนหมั่นถามอย่างตั้งใจ          แม้ช้าไปบ้างอย่าท้อเลยเรา\nวันหนึ่งต้นไม้จะให้ร่มเงา          แก่ผู้เยาว์ผู้เหนื่อยล้าทุกหนทาง","table":null,"lang":"th","stem":"\"วันหนึ่งต้นไม้จะให้ร่มเงา แก่ผู้เยาว์ผู้เหนื่อยล้าทุกหนทาง\" แสดงความคิดใด","choices":["ผู้ที่สั่งสมความรู้จนเติบโตจะนำความรู้ไปเป็นประโยชน์แก่ผู้อื่นได้","ควรปลูกต้นไม้ริมทางให้คนเดินทางได้พัก","ผู้ใหญ่ควรพักผ่อนใต้ต้นไม้","ความรู้มีไว้เพื่อประโยชน์ของตนเองเท่านั้น"],"answer":0,"explanation":{"en":"The 'tree' is knowledge that has grown through patient study. When it gives shade to the young and the weary, it means a knowledgeable person can help others. The line is figurative, and it contradicts the idea that knowledge is only for oneself.","th":"\"ต้นไม้\" คือความรู้ที่เติบโตจากความเพียร การให้ร่มเงาแก่ผู้เยาว์และผู้เหนื่อยล้าจึงหมายถึงผู้มีความรู้สามารถช่วยเหลือผู้อื่นได้ เป็นการกล่าวเชิงเปรียบเทียบ และขัดกับความคิดว่าความรู้มีไว้เพื่อตนเองเท่านั้น"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Author's purpose and tone","th":"จุดประสงค์และน้ำเสียงของผู้เขียน"},"topic":{"en":"Reading poetry","th":"การอ่านบทร้อยกรอง"},"passage":"ความรู้เปรียบเมล็ดพันธุ์อันน้อยนิด          หากเพาะจิตด้วยเพียรจะเติบใหญ่\nรดด้วยครูผู้รักและห่วงใย          มีแสงไฟจากตำราพาเติบกล้า\n\nแต่บางคนเร่งร้อนอยากได้ผล          ไม่อดทนรอวันฝนพร่างฟ้า\nถอนต้นอ่อนดูรากทุกเวลา          สุดท้ายกล้าก็ตายไปเปล่าเปล่า\n\nจงหมั่นเรียนหมั่นถามอย่างตั้งใจ          แม้ช้าไปบ้างอย่าท้อเลยเรา\nวันหนึ่งต้นไม้จะให้ร่มเงา          แก่ผู้เยาว์ผู้เหนื่อยล้าทุกหนทาง","table":null,"lang":"th","stem":"น้ำเสียงของผู้แต่งในบทที่ 3 เป็นอย่างไร","choices":["ประชดประชัน","เศร้าโศกสิ้นหวัง","โกรธเคือง","ให้กำลังใจและสั่งสอน"],"answer":3,"explanation":{"en":"Stanza 3 urges 'study and ask diligently' and says 'even if you are slow, don't be discouraged', then promises a good result — an encouraging, advising tone. Stanza 2 criticises impatience, but stanza 3 is hopeful, not sarcastic, despairing or angry.","th":"บทที่ 3 ใช้คำว่า \"จงหมั่นเรียนหมั่นถาม\" และ \"แม้ช้าไปบ้างอย่าท้อเลยเรา\" แล้วชี้ผลดีในอนาคต จึงมีน้ำเสียงให้กำลังใจและสั่งสอน แม้บทที่ 2 จะตำหนิความใจร้อน แต่บทที่ 3 มีความหวัง ไม่ได้ประชด เศร้า หรือโกรธ"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Evaluating arguments and facts","th":"การประเมินเหตุผลและข้อเท็จจริง"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ทุกวันนี้ข้อมูลข่าวสารเดินทางเร็วกว่าที่เคยเป็นมา ภาพหรือข้อความเพียงชิ้นเดียวอาจถูกส่งต่อนับหมื่นครั้งภายในไม่กี่ชั่วโมง ผลสำรวจของโรงเรียนแห่งหนึ่งพบว่านักเรียนร้อยละ 68 เคยส่งต่อข่าวโดยยังไม่ได้อ่านเนื้อหาจนจบ ตัวเลขนี้น่าตกใจ แต่ผมคิดว่าไม่ใช่เรื่องแปลก เพราะสื่อสังคมออนไลน์ทำให้การกดแชร์ง่ายกว่าการอ่านอย่างตั้งใจ\n\nหลายคนเชื่อว่าการแก้ปัญหาข่าวลวงเป็นหน้าที่ของรัฐหรือบริษัทเทคโนโลยีเพียงฝ่ายเดียว ความคิดนี้ถูกเพียงครึ่งเดียว กฎหมายและระบบคัดกรองย่อมช่วยได้ แต่ไม่มีระบบใดตามทันข่าวปลอมที่เกิดขึ้นใหม่ทุกนาที ด่านสุดท้ายที่แท้จริงจึงอยู่ที่ปลายนิ้วของผู้ใช้แต่ละคน\n\nการตรวจสอบข่าวไม่จำเป็นต้องยุ่งยาก เริ่มจากถามตัวเองสามข้อ ข้อแรก ใครเป็นผู้เผยแพร่ และเขามีความรู้หรือมีส่วนได้เสียในเรื่องนั้นหรือไม่ ข้อสอง ข่าวนี้มีแหล่งอื่นที่น่าเชื่อถือรายงานตรงกันหรือไม่ และข้อสาม พาดหัวกระตุ้นให้เรารู้สึกโกรธหรือกลัวอย่างรุนแรงหรือเปล่า เพราะข่าวลวงจำนวนมากอาศัยอารมณ์ของผู้อ่านเป็นเชื้อเพลิง หากตอบคำถามใดไม่ได้ ทางเลือกที่ดีที่สุดคือ \"หยุด\" ไว้ก่อน การไม่แชร์ไม่ได้ทำให้ใครเสียหาย แต่การแชร์ข่าวผิดอาจทำร้ายคนบริสุทธิ์ได้\n\nบางคนอาจแย้งว่าการตรวจสอบทุกข่าวเสียเวลาเกินไป ผมเห็นว่าข้อแย้งนี้ฟังขึ้นหากเรามองว่าการแชร์เป็นเรื่องเล็ก แต่เมื่อข่าวผิดเพียงชิ้นเดียวสามารถทำให้ร้านค้าเล็ก ๆ ต้องปิดตัว หรือทำให้ผู้ป่วยหลงเชื่อวิธีรักษาที่อันตราย เวลาไม่กี่นาทีที่ใช้ตรวจสอบก็นับว่าคุ้มค่าอย่างยิ่ง ในโลกที่ใครก็เป็นสื่อได้ เราทุกคนจึงต้องรับผิดชอบเหมือนเป็นบรรณาธิการของตัวเอง","table":null,"lang":"th","stem":"ข้อใดเป็นข้อเท็จจริงที่ผู้เขียนนำมาอ้าง ไม่ใช่ความคิดเห็นของผู้เขียน","choices":["ด่านสุดท้ายที่แท้จริงในการป้องกันข่าวลวงอยู่ที่ปลายนิ้วของผู้ใช้แต่ละคน","ผลสำรวจของโรงเรียนแห่งหนึ่งพบว่านักเรียนร้อยละ 68 เคยส่งต่อข่าวโดยยังไม่ได้อ่านจนจบ","เวลาไม่กี่นาทีที่ใช้ตรวจสอบข่าวนับว่าคุ้มค่าอย่างยิ่ง","ความคิดที่ว่าการแก้ปัญหาข่าวลวงเป็นหน้าที่ของรัฐฝ่ายเดียวนั้นถูกเพียงครึ่งเดียว"],"answer":1,"explanation":{"en":"The survey result (68% of students at one school) is reported data that could be checked, so it is a fact cited by the author. 'The real last line of defence is the user', 'a few minutes is well worth it' and 'that belief is only half right' are the author's judgements — opinions.","th":"ผลสำรวจที่พบว่านักเรียนร้อยละ 68 เคยส่งต่อข่าวโดยไม่อ่านจนจบ เป็นข้อมูลที่ตรวจสอบได้ จึงเป็นข้อเท็จจริงที่ผู้เขียนนำมาอ้าง ส่วน \"ด่านสุดท้ายที่แท้จริงอยู่ที่ผู้ใช้\" \"คุ้มค่าอย่างยิ่ง\" และ \"ถูกเพียงครึ่งเดียว\" เป็นการตัดสินของผู้เขียน จึงเป็นความคิดเห็น"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Author's purpose and tone","th":"จุดประสงค์และน้ำเสียงของผู้เขียน"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ทุกวันนี้ข้อมูลข่าวสารเดินทางเร็วกว่าที่เคยเป็นมา ภาพหรือข้อความเพียงชิ้นเดียวอาจถูกส่งต่อนับหมื่นครั้งภายในไม่กี่ชั่วโมง ผลสำรวจของโรงเรียนแห่งหนึ่งพบว่านักเรียนร้อยละ 68 เคยส่งต่อข่าวโดยยังไม่ได้อ่านเนื้อหาจนจบ ตัวเลขนี้น่าตกใจ แต่ผมคิดว่าไม่ใช่เรื่องแปลก เพราะสื่อสังคมออนไลน์ทำให้การกดแชร์ง่ายกว่าการอ่านอย่างตั้งใจ\n\nหลายคนเชื่อว่าการแก้ปัญหาข่าวลวงเป็นหน้าที่ของรัฐหรือบริษัทเทคโนโลยีเพียงฝ่ายเดียว ความคิดนี้ถูกเพียงครึ่งเดียว กฎหมายและระบบคัดกรองย่อมช่วยได้ แต่ไม่มีระบบใดตามทันข่าวปลอมที่เกิดขึ้นใหม่ทุกนาที ด่านสุดท้ายที่แท้จริงจึงอยู่ที่ปลายนิ้วของผู้ใช้แต่ละคน\n\nการตรวจสอบข่าวไม่จำเป็นต้องยุ่งยาก เริ่มจากถามตัวเองสามข้อ ข้อแรก ใครเป็นผู้เผยแพร่ และเขามีความรู้หรือมีส่วนได้เสียในเรื่องนั้นหรือไม่ ข้อสอง ข่าวนี้มีแหล่งอื่นที่น่าเชื่อถือรายงานตรงกันหรือไม่ และข้อสาม พาดหัวกระตุ้นให้เรารู้สึกโกรธหรือกลัวอย่างรุนแรงหรือเปล่า เพราะข่าวลวงจำนวนมากอาศัยอารมณ์ของผู้อ่านเป็นเชื้อเพลิง หากตอบคำถามใดไม่ได้ ทางเลือกที่ดีที่สุดคือ \"หยุด\" ไว้ก่อน การไม่แชร์ไม่ได้ทำให้ใครเสียหาย แต่การแชร์ข่าวผิดอาจทำร้ายคนบริสุทธิ์ได้\n\nบางคนอาจแย้งว่าการตรวจสอบทุกข่าวเสียเวลาเกินไป ผมเห็นว่าข้อแย้งนี้ฟังขึ้นหากเรามองว่าการแชร์เป็นเรื่องเล็ก แต่เมื่อข่าวผิดเพียงชิ้นเดียวสามารถทำให้ร้านค้าเล็ก ๆ ต้องปิดตัว หรือทำให้ผู้ป่วยหลงเชื่อวิธีรักษาที่อันตราย เวลาไม่กี่นาทีที่ใช้ตรวจสอบก็นับว่าคุ้มค่าอย่างยิ่ง ในโลกที่ใครก็เป็นสื่อได้ เราทุกคนจึงต้องรับผิดชอบเหมือนเป็นบรรณาธิการของตัวเอง","table":null,"lang":"th","stem":"จุดประสงค์หลักของผู้เขียนคือข้อใด","choices":["รายงานผลสำรวจการใช้สื่อสังคมออนไลน์ของนักเรียน","เรียกร้องให้รัฐออกกฎหมายลงโทษผู้ปล่อยข่าวลวง","โน้มน้าวให้ผู้อ่านตรวจสอบข่าวก่อนส่งต่อ และรับผิดชอบต่อสิ่งที่ตนแชร์","อธิบายวิธีการทำงานของบริษัทเทคโนโลยี"],"answer":2,"explanation":{"en":"The author gives reasons, offers three checking questions, answers an objection and ends with 'we must all act as our own editors' — a persuasive piece urging readers to check before sharing. The survey is only supporting evidence, and the author says laws alone are not enough.","th":"ผู้เขียนให้เหตุผล เสนอคำถามสามข้อในการตรวจสอบ ตอบข้อโต้แย้ง และจบด้วย \"เราทุกคนต้องรับผิดชอบเหมือนเป็นบรรณาธิการของตัวเอง\" จึงเป็นงานเขียนโน้มน้าวให้ตรวจสอบก่อนแชร์ ผลสำรวจเป็นเพียงหลักฐานประกอบ และผู้เขียนเห็นว่ากฎหมายอย่างเดียวไม่เพียงพอ"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"m","skill":{"en":"Interpreting meaning in context","th":"การตีความหมายตามบริบท"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ทุกวันนี้ข้อมูลข่าวสารเดินทางเร็วกว่าที่เคยเป็นมา ภาพหรือข้อความเพียงชิ้นเดียวอาจถูกส่งต่อนับหมื่นครั้งภายในไม่กี่ชั่วโมง ผลสำรวจของโรงเรียนแห่งหนึ่งพบว่านักเรียนร้อยละ 68 เคยส่งต่อข่าวโดยยังไม่ได้อ่านเนื้อหาจนจบ ตัวเลขนี้น่าตกใจ แต่ผมคิดว่าไม่ใช่เรื่องแปลก เพราะสื่อสังคมออนไลน์ทำให้การกดแชร์ง่ายกว่าการอ่านอย่างตั้งใจ\n\nหลายคนเชื่อว่าการแก้ปัญหาข่าวลวงเป็นหน้าที่ของรัฐหรือบริษัทเทคโนโลยีเพียงฝ่ายเดียว ความคิดนี้ถูกเพียงครึ่งเดียว กฎหมายและระบบคัดกรองย่อมช่วยได้ แต่ไม่มีระบบใดตามทันข่าวปลอมที่เกิดขึ้นใหม่ทุกนาที ด่านสุดท้ายที่แท้จริงจึงอยู่ที่ปลายนิ้วของผู้ใช้แต่ละคน\n\nการตรวจสอบข่าวไม่จำเป็นต้องยุ่งยาก เริ่มจากถามตัวเองสามข้อ ข้อแรก ใครเป็นผู้เผยแพร่ และเขามีความรู้หรือมีส่วนได้เสียในเรื่องนั้นหรือไม่ ข้อสอง ข่าวนี้มีแหล่งอื่นที่น่าเชื่อถือรายงานตรงกันหรือไม่ และข้อสาม พาดหัวกระตุ้นให้เรารู้สึกโกรธหรือกลัวอย่างรุนแรงหรือเปล่า เพราะข่าวลวงจำนวนมากอาศัยอารมณ์ของผู้อ่านเป็นเชื้อเพลิง หากตอบคำถามใดไม่ได้ ทางเลือกที่ดีที่สุดคือ \"หยุด\" ไว้ก่อน การไม่แชร์ไม่ได้ทำให้ใครเสียหาย แต่การแชร์ข่าวผิดอาจทำร้ายคนบริสุทธิ์ได้\n\nบางคนอาจแย้งว่าการตรวจสอบทุกข่าวเสียเวลาเกินไป ผมเห็นว่าข้อแย้งนี้ฟังขึ้นหากเรามองว่าการแชร์เป็นเรื่องเล็ก แต่เมื่อข่าวผิดเพียงชิ้นเดียวสามารถทำให้ร้านค้าเล็ก ๆ ต้องปิดตัว หรือทำให้ผู้ป่วยหลงเชื่อวิธีรักษาที่อันตราย เวลาไม่กี่นาทีที่ใช้ตรวจสอบก็นับว่าคุ้มค่าอย่างยิ่ง ในโลกที่ใครก็เป็นสื่อได้ เราทุกคนจึงต้องรับผิดชอบเหมือนเป็นบรรณาธิการของตัวเอง","table":null,"lang":"th","stem":"ข้อความ \"เราทุกคนจึงต้องรับผิดชอบเหมือนเป็นบรรณาธิการของตัวเอง\" หมายความว่าอย่างไร","choices":["ทุกคนควรเปิดสำนักพิมพ์ของตนเอง","ทุกคนควรเขียนข่าวเองแทนการอ่านข่าวจากผู้อื่น","ผู้ใช้ทุกคนต้องคัดกรองและตรวจสอบความถูกต้องของข้อมูลก่อนเผยแพร่","ทุกคนต้องแก้ไขคำผิดในข่าวที่ได้รับ"],"answer":2,"explanation":{"en":"An editor decides what is accurate enough to publish. Since 'anyone can be a medium', each user must do that job — check and filter information before passing it on. The sentence is a comparison, not advice to open a publishing house, write one's own news or correct typos.","th":"บรรณาธิการคือผู้ตรวจสอบและตัดสินว่าข้อมูลใดถูกต้องพอจะเผยแพร่ เมื่อ \"ใครก็เป็นสื่อได้\" ผู้ใช้แต่ละคนจึงต้องทำหน้าที่นี้ คือตรวจสอบและคัดกรองก่อนส่งต่อ ข้อความนี้เป็นการเปรียบเทียบ ไม่ได้แนะนำให้ตั้งสำนักพิมพ์ เขียนข่าวเอง หรือแก้คำผิด"}},{"kind":"m1","program":"satit","subject":"thai","format":"mcq","difficulty":"h","skill":{"en":"Evaluating arguments and facts","th":"การประเมินเหตุผลและข้อเท็จจริง"},"topic":{"en":"Reading prose","th":"การอ่านบทร้อยแก้ว"},"passage":"ทุกวันนี้ข้อมูลข่าวสารเดินทางเร็วกว่าที่เคยเป็นมา ภาพหรือข้อความเพียงชิ้นเดียวอาจถูกส่งต่อนับหมื่นครั้งภายในไม่กี่ชั่วโมง ผลสำรวจของโรงเรียนแห่งหนึ่งพบว่านักเรียนร้อยละ 68 เคยส่งต่อข่าวโดยยังไม่ได้อ่านเนื้อหาจนจบ ตัวเลขนี้น่าตกใจ แต่ผมคิดว่าไม่ใช่เรื่องแปลก เพราะสื่อสังคมออนไลน์ทำให้การกดแชร์ง่ายกว่าการอ่านอย่างตั้งใจ\n\nหลายคนเชื่อว่าการแก้ปัญหาข่าวลวงเป็นหน้าที่ของรัฐหรือบริษัทเทคโนโลยีเพียงฝ่ายเดียว ความคิดนี้ถูกเพียงครึ่งเดียว กฎหมายและระบบคัดกรองย่อมช่วยได้ แต่ไม่มีระบบใดตามทันข่าวปลอมที่เกิดขึ้นใหม่ทุกนาที ด่านสุดท้ายที่แท้จริงจึงอยู่ที่ปลายนิ้วของผู้ใช้แต่ละคน\n\nการตรวจสอบข่าวไม่จำเป็นต้องยุ่งยาก เริ่มจากถามตัวเองสามข้อ ข้อแรก ใครเป็นผู้เผยแพร่ และเขามีความรู้หรือมีส่วนได้เสียในเรื่องนั้นหรือไม่ ข้อสอง ข่าวนี้มีแหล่งอื่นที่น่าเชื่อถือรายงานตรงกันหรือไม่ และข้อสาม พาดหัวกระตุ้นให้เรารู้สึกโกรธหรือกลัวอย่างรุนแรงหรือเปล่า เพราะข่าวลวงจำนวนมากอาศัยอารมณ์ของผู้อ่านเป็นเชื้อเพลิง หากตอบคำถามใดไม่ได้ ทางเลือกที่ดีที่สุดคือ \"หยุด\" ไว้ก่อน การไม่แชร์ไม่ได้ทำให้ใครเสียหาย แต่การแชร์ข่าวผิดอาจทำร้ายคนบริสุทธิ์ได้\n\nบางคนอาจแย้งว่าการตรวจสอบทุกข่าวเสียเวลาเกินไป ผมเห็นว่าข้อแย้งนี้ฟังขึ้นหากเรามองว่าการแชร์เป็นเรื่องเล็ก แต่เมื่อข่าวผิดเพียงชิ้นเดียวสามารถทำให้ร้านค้าเล็ก ๆ ต้องปิดตัว หรือทำให้ผู้ป่วยหลงเชื่อวิธีรักษาที่อันตราย เวลาไม่กี่นาทีที่ใช้ตรวจสอบก็นับว่าคุ้มค่าอย่างยิ่ง ในโลกที่ใครก็เป็นสื่อได้ เราทุกคนจึงต้องรับผิดชอบเหมือนเป็นบรรณาธิการของตัวเอง","table":null,"lang":"th","stem":"ในย่อหน้าสุดท้าย ผู้เขียนยกข้อแย้งว่า \"การตรวจสอบทุกข่าวเสียเวลาเกินไป\" ขึ้นมา เพื่อจุดประสงค์ใด","choices":["แสดงว่าผู้เขียนเปลี่ยนใจเห็นด้วยกับข้อแย้งนั้น","ยอมรับข้อแย้งบางส่วนแล้วหักล้าง เพื่อให้เหตุผลของตนหนักแน่นขึ้น","ชี้ว่าการตรวจสอบข่าวเป็นเรื่องที่ไม่จำเป็น","สรุปว่าการแชร์ข่าวเป็นเรื่องเล็กน้อย"],"answer":1,"explanation":{"en":"The author grants the objection 'sounds reasonable if sharing is seen as minor', then rebuts it with examples of serious harm (a shop closing, a patient misled), concluding that a few minutes of checking is worth it. Raising and refuting a counter-argument strengthens the case; the author does not change his mind.","th":"ผู้เขียนยอมรับว่าข้อแย้ง \"ฟังขึ้นหากมองว่าการแชร์เป็นเรื่องเล็ก\" แล้วหักล้างด้วยตัวอย่างความเสียหายร้ายแรง เช่น ร้านค้าปิดตัว ผู้ป่วยหลงเชื่อ จึงสรุปว่าเวลาไม่กี่นาทีคุ้มค่า การยกข้อโต้แย้งแล้วหักล้างทำให้เหตุผลหนักแน่นขึ้น ผู้เขียนไม่ได้เปลี่ยนความคิด"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"e","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Prepositions, quantifiers and function words","th":"คำบุพบท คำบอกปริมาณ และคำไวยากรณ์"},"passage":"","table":null,"lang":"en","stem":"You ___ wear a helmet when you ride a motorbike. It's the law.","choices":["mustn't","must","needn't","might"],"answer":1,"explanation":{"en":"'It's the law' shows an obligation, so 'must' is right. 'Mustn't' means it is forbidden, 'needn't' means it is not necessary, and 'might' only shows possibility.","th":"\"It's the law\" แสดงว่าเป็นข้อบังคับ จึงใช้ must ส่วน mustn't แปลว่า ห้าม needn't แปลว่า ไม่จำเป็น และ might แสดงความเป็นไปได้เท่านั้น"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Verb tenses","th":"กาลของกริยา"},"passage":"","table":null,"lang":"en","stem":"By the time we arrived at the cinema, the film ___.","choices":["has already started","had already started","already starts","was already start"],"answer":1,"explanation":{"en":"Two past actions: the film started BEFORE we arrived. The earlier past action uses the past perfect, 'had already started'. 'Has started' is present perfect and does not fit a past story; 'was already start' is not a correct form.","th":"มีเหตุการณ์ในอดีตสองเหตุการณ์ หนังเริ่มก่อนที่เราจะไปถึง เหตุการณ์ที่เกิดก่อนใช้ past perfect คือ had already started ส่วน has started เป็น present perfect ไม่เข้ากับเรื่องในอดีต และ was already start เป็นรูปที่ผิด"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Sentence structure (conditionals, passive, relative clauses)","th":"โครงสร้างประโยค (เงื่อนไข กรรมวาจก คุณานุประโยค)"},"passage":"","table":null,"lang":"en","stem":"If I ___ more free time, I would learn to play the guitar.","choices":["have","will have","would have","had"],"answer":3,"explanation":{"en":"'Would learn' shows an unreal present situation (second conditional): If + past simple, would + verb. So 'If I had more free time'. 'Have' and 'will have' belong to the first conditional, and 'would' is not used in the if-clause.","th":"ประโยคใช้ would learn แสดงเงื่อนไขที่ไม่เป็นจริงในปัจจุบัน (conditional แบบที่ 2) โครงสร้างคือ If + past simple, would + V1 จึงใช้ had ส่วน have และ will have เป็นแบบที่ 1 และไม่ใช้ would ในอนุประโยค if"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Sentence structure (conditionals, passive, relative clauses)","th":"โครงสร้างประโยค (เงื่อนไข กรรมวาจก คุณานุประโยค)"},"passage":"","table":null,"lang":"en","stem":"If you had told me about the problem earlier, I ___ you.","choices":["could help","can help","could have helped","will have helped"],"answer":2,"explanation":{"en":"'If you had told me' is about the past and did not happen (third conditional), so the result clause needs could/would + have + past participle: 'could have helped'. The other forms do not match a past, unreal condition.","th":"\"If you had told me\" เป็นเงื่อนไขในอดีตที่ไม่ได้เกิดขึ้นจริง (conditional แบบที่ 3) ผลจึงต้องใช้ could/would + have + V3 คือ could have helped รูปอื่นไม่สอดคล้องกับเงื่อนไขในอดีต"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Sentence structure (conditionals, passive, relative clauses)","th":"โครงสร้างประโยค (เงื่อนไข กรรมวาจก คุณานุประโยค)"},"passage":"","table":null,"lang":"en","stem":"The new bridge ___ by local engineers next year.","choices":["will be built","will build","is building","has built"],"answer":0,"explanation":{"en":"The bridge does not build anything — it is built — and 'by local engineers' names who does the action, so a passive is needed. 'Next year' shows the future: will be + past participle = 'will be built'.","th":"สะพานเป็นสิ่งที่ถูกสร้าง และมี by local engineers บอกผู้กระทำ จึงต้องใช้ passive voice และ next year บอกอนาคต จึงใช้ will be + V3 คือ will be built"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Sentence structure (conditionals, passive, relative clauses)","th":"โครงสร้างประโยค (เงื่อนไข กรรมวาจก คุณานุประโยค)"},"passage":"","table":null,"lang":"en","stem":"The girl ___ bicycle was stolen reported it to the police.","choices":["who","which","whose","whom"],"answer":2,"explanation":{"en":"The bicycle belongs to the girl, so we need the possessive relative pronoun 'whose' (= her). 'Who' and 'whom' refer to the person herself, and 'which' is for things; none of them can be followed directly by 'bicycle' to show possession.","th":"จักรยานเป็นของเด็กผู้หญิง จึงต้องใช้ whose ซึ่งแสดงความเป็นเจ้าของ ส่วน who และ whom ใช้แทนตัวบุคคล และ which ใช้แทนสิ่งของ ไม่สามารถแสดงความเป็นเจ้าของหน้าคำนาม bicycle ได้"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"e","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Word forms and parts of speech","th":"รูปคำและชนิดของคำ"},"passage":"","table":null,"lang":"en","stem":"This is ___ book I have ever read.","choices":["more interesting","the more interesting","the most interesting","most interesting"],"answer":2,"explanation":{"en":"'I have ever read' compares this book with all others, so we need the superlative with 'the': 'the most interesting'. 'More interesting' compares only two things and needs 'than'.","th":"\"I have ever read\" เปรียบเทียบกับหนังสือทุกเล่ม จึงต้องใช้ขั้นสูงสุด the most interesting ส่วน more interesting เป็นขั้นกว่า ใช้เปรียบเทียบสองสิ่งและต้องมี than"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"e","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Prepositions, quantifiers and function words","th":"คำบุพบท คำบอกปริมาณ และคำไวยากรณ์"},"passage":"","table":null,"lang":"en","stem":"There isn't ___ milk left in the fridge.","choices":["some","any","many","a few"],"answer":1,"explanation":{"en":"Milk is uncountable, and in negative sentences we use 'any'. 'Many' and 'a few' are for countable nouns, and 'some' is normally used in positive sentences.","th":"milk เป็นนามนับไม่ได้ และในประโยคปฏิเสธใช้ any ส่วน many และ a few ใช้กับนามนับได้ และ some มักใช้ในประโยคบอกเล่า"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Word forms and parts of speech","th":"รูปคำและชนิดของคำ"},"passage":"","table":null,"lang":"en","stem":"I'm really looking forward to ___ you at the camp next week.","choices":["see","seeing","saw","be seen"],"answer":1,"explanation":{"en":"In 'look forward to', 'to' is a preposition, not part of an infinitive, so it is followed by a gerund (-ing): 'looking forward to seeing you'. Using the base form 'see' is a very common mistake.","th":"ในวลี look forward to คำว่า to เป็นบุพบท ไม่ใช่ส่วนของ infinitive จึงต้องตามด้วย V-ing คือ seeing การใช้ see เป็นข้อผิดพลาดที่พบบ่อย"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Word forms and parts of speech","th":"รูปคำและชนิดของคำ"},"passage":"","table":null,"lang":"en","stem":"Mint stopped ___ to her friend as soon as the teacher walked in.","choices":["to talk","talk","talking","talked"],"answer":2,"explanation":{"en":"'Stop + -ing' means to end an activity; 'stop + to + verb' means to pause in order to do something. Mint ended her chat because the teacher arrived, so 'stopped talking' is right. 'Stopped to talk' would mean she began talking when the teacher came in, which does not make sense here.","th":"stop + V-ing หมายถึง หยุดทำสิ่งนั้น ส่วน stop + to + V หมายถึง หยุดเพื่อไปทำอีกสิ่งหนึ่ง มินต์หยุดคุยเพราะครูเข้ามา จึงใช้ stopped talking ถ้าใช้ stopped to talk จะหมายถึงหยุดเพื่อคุย ซึ่งไม่สมเหตุสมผล"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Sentence structure (conditionals, passive, relative clauses)","th":"โครงสร้างประโยค (เงื่อนไข กรรมวาจก คุณานุประโยค)"},"passage":"","table":null,"lang":"en","stem":"Mai asked me, \"Where do you live?\" Which sentence reports her question correctly?","choices":["Mai asked me where did I live.","Mai asked me where do you live.","Mai asked me that where I lived.","Mai asked me where I lived."],"answer":3,"explanation":{"en":"In reported questions the word order becomes a statement (subject before verb), 'do' disappears, the tense moves back (live → lived) and the pronoun changes (you → I). 'That' is not used before a question word.","th":"ในคำถามแบบรายงาน ต้องเรียงแบบประโยคบอกเล่า (ประธานก่อนกริยา) ตัด do ออก ถอยกาล (live → lived) และเปลี่ยนสรรพนาม (you → I) และไม่ใช้ that หน้าคำแสดงคำถาม"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Verb tenses","th":"กาลของกริยา"},"passage":"","table":null,"lang":"en","stem":"You've finished your homework, ___?","choices":["didn't you","have you","haven't you","don't you"],"answer":2,"explanation":{"en":"The statement is positive and uses the auxiliary 'have' ('You've finished'), so the tag is negative with the same auxiliary: 'haven't you?'. 'Didn't' and 'don't' use the wrong auxiliary; 'have you' is not negative.","th":"ประโยคหลักเป็นบอกเล่าและใช้กริยาช่วย have (You've finished) question tag จึงเป็นปฏิเสธและใช้กริยาช่วยตัวเดียวกัน คือ haven't you"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"e","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Prepositions, quantifiers and function words","th":"คำบุพบท คำบอกปริมาณ และคำไวยากรณ์"},"passage":"","table":null,"lang":"en","stem":"The meeting starts ___ 9 a.m. ___ Monday.","choices":["at / on","on / at","in / on","at / in"],"answer":0,"explanation":{"en":"We use 'at' for clock times (at 9 a.m.) and 'on' for days (on Monday). 'In' is for months, years and parts of the day.","th":"ใช้ at กับเวลาที่เป็นนาฬิกา (at 9 a.m.) และ on กับวัน (on Monday) ส่วน in ใช้กับเดือน ปี และช่วงเวลาของวัน"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Applying grammar rules","th":"การใช้หลักไวยากรณ์"},"topic":{"en":"Verb tenses","th":"กาลของกริยา"},"passage":"","table":null,"lang":"en","stem":"Neither the teacher nor the students ___ aware of the change to the timetable.","choices":["was","were","is","has been"],"answer":1,"explanation":{"en":"With 'neither … nor', the verb agrees with the noun closest to it. That noun is 'the students' (plural), and the context is past, so 'were' is correct. 'Was', 'is' and 'has been' are singular.","th":"เมื่อใช้ neither … nor กริยาจะผันตามคำนามที่อยู่ใกล้กริยาที่สุด คือ the students ซึ่งเป็นพหูพจน์ และบริบทเป็นอดีต จึงใช้ were ส่วน was, is และ has been เป็นรูปเอกพจน์"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"e","skill":{"en":"Choosing words in context","th":"การเลือกใช้คำศัพท์ตามบริบท"},"topic":{"en":"Vocabulary in context","th":"คำศัพท์ในบริบท"},"passage":"","table":null,"lang":"en","stem":"The opposite of \"ancient\" is ___.","choices":["old","modern","huge","quiet"],"answer":1,"explanation":{"en":"'Ancient' means very old, from long ago, so its opposite is 'modern' (new, of the present time). 'Old' is a synonym, not an opposite.","th":"ancient แปลว่า เก่าแก่ โบราณ คำตรงข้ามคือ modern (ทันสมัย) ส่วน old มีความหมายใกล้เคียง ไม่ใช่คำตรงข้าม"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Choosing words in context","th":"การเลือกใช้คำศัพท์ตามบริบท"},"topic":{"en":"Word forms and parts of speech","th":"รูปคำและชนิดของคำ"},"passage":"","table":null,"lang":"en","stem":"The scientist made an important ___ about how the virus spreads.","choices":["discover","discovered","discovering","discovery"],"answer":3,"explanation":{"en":"After 'an important' we need a noun: 'discovery'. 'Discover' is a verb, and 'discovered' and 'discovering' are verb forms.","th":"หลัง an important ต้องเป็นคำนาม คือ discovery ส่วน discover เป็นกริยา และ discovered, discovering เป็นรูปกริยา"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Choosing words in context","th":"การเลือกใช้คำศัพท์ตามบริบท"},"topic":{"en":"Word forms and parts of speech","th":"รูปคำและชนิดของคำ"},"passage":"","table":null,"lang":"en","stem":"He spoke so ___ that everyone at the back of the hall could hear him.","choices":["clear","clearness","clearly","clarity"],"answer":2,"explanation":{"en":"The word describes HOW he spoke (the verb), so it must be an adverb: 'clearly'. 'Clear' is an adjective, and 'clearness' and 'clarity' are nouns.","th":"คำที่ขยายกริยา spoke ว่าพูดอย่างไร ต้องเป็นคำกริยาวิเศษณ์ คือ clearly ส่วน clear เป็นคุณศัพท์ และ clearness, clarity เป็นคำนาม"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Choosing words in context","th":"การเลือกใช้คำศัพท์ตามบริบท"},"topic":{"en":"Vocabulary in context","th":"คำศัพท์ในบริบท"},"passage":"","table":null,"lang":"en","stem":"After the six-hour hike, we were completely ___ and went straight to bed.","choices":["exhausted","excited","amazed","annoyed"],"answer":0,"explanation":{"en":"A long hike followed by going straight to bed shows extreme tiredness: 'exhausted'. Being excited or amazed would not explain going straight to sleep, and nothing in the sentence suggests being annoyed.","th":"การเดินป่า 6 ชั่วโมงแล้วเข้านอนทันทีแสดงถึงความเหนื่อยมาก จึงใช้ exhausted ส่วน excited (ตื่นเต้น) และ amazed (ทึ่ง) ไม่ได้อธิบายการเข้านอนทันที และไม่มีอะไรบ่งชี้ว่า annoyed (รำคาญ)"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Choosing words in context","th":"การเลือกใช้คำศัพท์ตามบริบท"},"topic":{"en":"Vocabulary in context","th":"คำศัพท์ในบริบท"},"passage":"","table":null,"lang":"en","stem":"The football match was ___ because of the heavy rain, so we stayed at home.","choices":["called off","called up","put on","taken after"],"answer":0,"explanation":{"en":"'Call off' means cancel, which fits heavy rain and staying at home. 'Call up' means telephone or summon, 'put on' means organise a show or wear clothes, and 'take after' means resemble a family member.","th":"call off แปลว่า ยกเลิก เข้ากับเหตุฝนตกหนักและการอยู่บ้าน ส่วน call up แปลว่า โทรหาหรือเรียกตัว put on แปลว่า จัดการแสดงหรือสวมใส่ และ take after แปลว่า มีลักษณะเหมือนญาติ"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Choosing words in context","th":"การเลือกใช้คำศัพท์ตามบริบท"},"topic":{"en":"Vocabulary in context","th":"คำศัพท์ในบริบท"},"passage":"","table":null,"lang":"en","stem":"Please ___ attention to the safety instructions before the experiment begins.","choices":["make","do","take","pay"],"answer":3,"explanation":{"en":"The fixed expression (collocation) is 'pay attention to'. We do not say 'make', 'do' or 'take' attention.","th":"วลีที่ใช้คู่กันเสมอ (collocation) คือ pay attention to แปลว่า ให้ความสนใจ ไม่ใช้ make, do หรือ take กับ attention"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Choosing words in context","th":"การเลือกใช้คำศัพท์ตามบริบท"},"topic":{"en":"Vocabulary in context","th":"คำศัพท์ในบริบท"},"passage":"","table":null,"lang":"en","stem":"\"The instructions were so complicated that nobody could follow them.\" The word \"complicated\" is closest in meaning to ___.","choices":["very short","clearly written","difficult to understand","badly printed"],"answer":2,"explanation":{"en":"The result 'nobody could follow them' shows the instructions were hard to understand, which is what 'complicated' means. 'Clearly written' is the opposite, and length or printing quality are not mentioned.","th":"ผลที่ว่า \"ไม่มีใครทำตามได้\" แสดงว่าคำแนะนำเข้าใจยาก ซึ่งตรงกับความหมายของ complicated ส่วน clearly written มีความหมายตรงข้าม และประโยคไม่ได้พูดถึงความยาวหรือคุณภาพการพิมพ์"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"e","skill":{"en":"Choosing words in context","th":"การเลือกใช้คำศัพท์ตามบริบท"},"topic":{"en":"Vocabulary in context","th":"คำศัพท์ในบริบท"},"passage":"","table":null,"lang":"en","stem":"A doctor who takes care of sick animals is called a ___.","choices":["dentist","pilot","chemist","vet"],"answer":3,"explanation":{"en":"A vet (veterinarian) treats animals. A dentist looks after teeth, a pilot flies planes and a chemist works with chemicals or sells medicine.","th":"vet (สัตวแพทย์) คือหมอรักษาสัตว์ ส่วน dentist คือทันตแพทย์ pilot คือนักบิน และ chemist คือนักเคมีหรือเภสัชกร"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"e","skill":{"en":"Responding appropriately in dialogue","th":"การตอบสนองในบทสนทนาอย่างเหมาะสม"},"topic":{"en":"Everyday conversation","th":"บทสนทนาในชีวิตประจำวัน"},"passage":"","table":null,"lang":"en","stem":"A: \"Thank you so much for helping me carry these boxes.\"\nB: \"___\"","choices":["Yes, please.","Same to you.","You're welcome.","Excuse me."],"answer":2,"explanation":{"en":"'You're welcome' is the normal reply to 'thank you'. 'Yes, please' accepts an offer, 'Same to you' returns a wish such as 'Have a nice day', and 'Excuse me' gets attention or apologises.","th":"You're welcome เป็นคำตอบเมื่อมีคนขอบคุณ ส่วน Yes, please ใช้ตอบรับข้อเสนอ Same to you ใช้ตอบคำอวยพร และ Excuse me ใช้ขอโทษหรือเรียกความสนใจ"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Responding appropriately in dialogue","th":"การตอบสนองในบทสนทนาอย่างเหมาะสม"},"topic":{"en":"Everyday conversation","th":"บทสนทนาในชีวิตประจำวัน"},"passage":"","table":null,"lang":"en","stem":"A: \"Would you mind opening the window?\"\nB: \"___\"","choices":["Yes, please. Thank you.","I'd love to, but I'm full.","Not at all. It's really hot in here.","Never mind. It's my fault."],"answer":2,"explanation":{"en":"'Would you mind…?' literally asks 'Do you object?', so agreeing to help is 'Not at all' (= I don't mind, I'll do it). 'Yes, please' answers an offer, not a request; the other two do not fit the situation.","th":"Would you mind…? แปลตรงตัวว่า \"คุณรังเกียจไหมถ้า…\" การตอบตกลงจึงใช้ Not at all (ไม่รังเกียจเลย) ส่วน Yes, please ใช้ตอบรับข้อเสนอ ไม่ใช่คำขอ และอีกสองข้อไม่เข้ากับสถานการณ์"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Responding appropriately in dialogue","th":"การตอบสนองในบทสนทนาอย่างเหมาะสม"},"topic":{"en":"Everyday conversation","th":"บทสนทนาในชีวิตประจำวัน"},"passage":"","table":null,"lang":"en","stem":"Shop assistant: \"That's 850 baht altogether. How would you like to pay?\"\nCustomer: \"___\"","choices":["Every Monday.","It costs 850 baht.","By credit card, please.","I'd like a large one."],"answer":2,"explanation":{"en":"'How would you like to pay?' asks for a method of payment, so 'By credit card' answers it. 'Every Monday' answers 'how often', the price has already been given, and 'a large one' answers a question about size.","th":"How would you like to pay? ถามวิธีชำระเงิน จึงตอบว่า By credit card ส่วน Every Monday ตอบคำถามเรื่องความถี่ ราคาบอกไปแล้ว และ a large one ตอบเรื่องขนาด"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Responding appropriately in dialogue","th":"การตอบสนองในบทสนทนาอย่างเหมาะสม"},"topic":{"en":"Everyday conversation","th":"บทสนทนาในชีวิตประจำวัน"},"passage":"","table":null,"lang":"en","stem":"A: \"I failed my maths test again, even though I studied for hours.\"\nB: \"___\"","choices":["That's a shame. Maybe we could study together next time?","Congratulations! You must be very proud.","I'm glad to hear that.","Don't mention it."],"answer":0,"explanation":{"en":"A is upset about bad news, so B should show sympathy and offer help: 'That's a shame. Maybe we could study together…'. Congratulating or saying 'I'm glad' would be rude here, and 'Don't mention it' is a reply to thanks.","th":"A กำลังเสียใจกับข่าวร้าย B ควรแสดงความเห็นใจและเสนอความช่วยเหลือ คือ That's a shame. Maybe we could study together… การแสดงความยินดีหรือบอกว่าดีใจถือว่าไม่เหมาะสม และ Don't mention it ใช้ตอบคำขอบคุณ"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Responding appropriately in dialogue","th":"การตอบสนองในบทสนทนาอย่างเหมาะสม"},"topic":{"en":"Everyday conversation","th":"บทสนทนาในชีวิตประจำวัน"},"passage":"","table":null,"lang":"en","stem":"A: \"Excuse me, how do I get to the post office?\"\nB: \"___\"","choices":["It opens at eight in the morning.","Go straight on and take the second turning on the left.","Yes, I've been there many times.","You can post your letter tomorrow."],"answer":1,"explanation":{"en":"'How do I get to…?' asks for directions, so B should give them. The opening time, B's own experience and when to post a letter do not tell A how to get there.","th":"How do I get to…? เป็นการถามทาง B จึงต้องบอกทาง ส่วนเวลาเปิดทำการ ประสบการณ์ของ B และเวลาส่งจดหมาย ไม่ได้บอกวิธีไปที่ทำการไปรษณีย์"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Responding appropriately in dialogue","th":"การตอบสนองในบทสนทนาอย่างเหมาะสม"},"topic":{"en":"Everyday conversation","th":"บทสนทนาในชีวิตประจำวัน"},"passage":"","table":null,"lang":"en","stem":"A: \"Shall we go to the beach this weekend?\"\nB: \"___ The weather forecast says it will rain all weekend.\"","choices":["What a great idea!","I'm not sure that's a good idea.","Sure, I'll bring my sunglasses.","Yes, let's go right now."],"answer":1,"explanation":{"en":"B's second sentence (rain all weekend) is a reason NOT to go, so B must be politely doubtful: 'I'm not sure that's a good idea.' Agreeing enthusiastically or bringing sunglasses contradicts the forecast, and 'right now' ignores 'this weekend'.","th":"ประโยคที่สองของ B (ฝนจะตกทั้งสุดสัปดาห์) เป็นเหตุผลที่ไม่ควรไป B จึงต้องแสดงความไม่เห็นด้วยอย่างสุภาพ คือ I'm not sure that's a good idea ส่วนการตอบรับอย่างกระตือรือร้นหรือการเตรียมแว่นกันแดดขัดกับพยากรณ์อากาศ"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"e","skill":{"en":"Completing a text coherently","th":"การเติมข้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Cloze passage","th":"บทความเติมคำ"},"passage":"Read the passage and choose the best answer for each numbered blank.\n\nLast year, students at a school in Bangkok decided to turn an empty rooftop (1) ___ a vegetable garden. At first, many teachers were doubtful. The roof was hot, and there was no soil. (2) ___, the students did not give up. They researched how to grow plants in containers and asked a local farmer for advice. Every student in the club was responsible (3) ___ watering the plants on a different day of the week. They also collected food waste from the canteen and turned it into compost, (4) ___ reduced the amount of rubbish the school threw away.\n\nAfter three months, the garden (5) ___ more than twenty kilograms of vegetables. The canteen cooked them for lunch, and students said the food tasted fresher than ever. The project was so (6) ___ that two other schools have asked the club to help them start gardens of their own. \"We learned that you don't need a lot of space to make a difference,\" said the club's leader. \"You just need a plan and people who are willing (7) ___ together.\"","table":null,"lang":"en","stem":"Which word best fits blank (1)?","choices":["into","onto","at","with"],"answer":0,"explanation":{"en":"The pattern is 'turn something into something else' (change it). The rooftop was changed into a garden.","th":"โครงสร้าง turn A into B หมายถึง เปลี่ยน A ให้เป็น B ดาดฟ้าถูกเปลี่ยนเป็นสวนผัก จึงใช้ into"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Completing a text coherently","th":"การเติมข้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Cloze passage","th":"บทความเติมคำ"},"passage":"Read the passage and choose the best answer for each numbered blank.\n\nLast year, students at a school in Bangkok decided to turn an empty rooftop (1) ___ a vegetable garden. At first, many teachers were doubtful. The roof was hot, and there was no soil. (2) ___, the students did not give up. They researched how to grow plants in containers and asked a local farmer for advice. Every student in the club was responsible (3) ___ watering the plants on a different day of the week. They also collected food waste from the canteen and turned it into compost, (4) ___ reduced the amount of rubbish the school threw away.\n\nAfter three months, the garden (5) ___ more than twenty kilograms of vegetables. The canteen cooked them for lunch, and students said the food tasted fresher than ever. The project was so (6) ___ that two other schools have asked the club to help them start gardens of their own. \"We learned that you don't need a lot of space to make a difference,\" said the club's leader. \"You just need a plan and people who are willing (7) ___ together.\"","table":null,"lang":"en","stem":"Which word best fits blank (2)?","choices":["Therefore","Because","However","Moreover"],"answer":2,"explanation":{"en":"The previous sentences give problems (doubtful teachers, a hot roof, no soil), and the next clause says the students did not give up — a contrast, so 'However'. 'Therefore' shows a result, 'Moreover' adds a similar point, and 'Because' cannot start this clause.","th":"ประโยคก่อนหน้ากล่าวถึงอุปสรรค (ครูไม่มั่นใจ หลังคาร้อน ไม่มีดิน) แต่ประโยคถัดมาบอกว่านักเรียนไม่ยอมแพ้ เป็นความขัดแย้ง จึงใช้ However ส่วน Therefore แสดงผล Moreover เพิ่มเติมข้อมูลไปทางเดียวกัน และ Because ใช้ขึ้นต้นตรงนี้ไม่ได้"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Completing a text coherently","th":"การเติมข้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Cloze passage","th":"บทความเติมคำ"},"passage":"Read the passage and choose the best answer for each numbered blank.\n\nLast year, students at a school in Bangkok decided to turn an empty rooftop (1) ___ a vegetable garden. At first, many teachers were doubtful. The roof was hot, and there was no soil. (2) ___, the students did not give up. They researched how to grow plants in containers and asked a local farmer for advice. Every student in the club was responsible (3) ___ watering the plants on a different day of the week. They also collected food waste from the canteen and turned it into compost, (4) ___ reduced the amount of rubbish the school threw away.\n\nAfter three months, the garden (5) ___ more than twenty kilograms of vegetables. The canteen cooked them for lunch, and students said the food tasted fresher than ever. The project was so (6) ___ that two other schools have asked the club to help them start gardens of their own. \"We learned that you don't need a lot of space to make a difference,\" said the club's leader. \"You just need a plan and people who are willing (7) ___ together.\"","table":null,"lang":"en","stem":"Which word best fits blank (3)?","choices":["of","for","to","with"],"answer":1,"explanation":{"en":"The adjective 'responsible' is followed by 'for' + noun or -ing: 'responsible for watering'.","th":"คำคุณศัพท์ responsible ตามด้วยบุพบท for + คำนาม/V-ing จึงเป็น responsible for watering"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Completing a text coherently","th":"การเติมข้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Cloze passage","th":"บทความเติมคำ"},"passage":"Read the passage and choose the best answer for each numbered blank.\n\nLast year, students at a school in Bangkok decided to turn an empty rooftop (1) ___ a vegetable garden. At first, many teachers were doubtful. The roof was hot, and there was no soil. (2) ___, the students did not give up. They researched how to grow plants in containers and asked a local farmer for advice. Every student in the club was responsible (3) ___ watering the plants on a different day of the week. They also collected food waste from the canteen and turned it into compost, (4) ___ reduced the amount of rubbish the school threw away.\n\nAfter three months, the garden (5) ___ more than twenty kilograms of vegetables. The canteen cooked them for lunch, and students said the food tasted fresher than ever. The project was so (6) ___ that two other schools have asked the club to help them start gardens of their own. \"We learned that you don't need a lot of space to make a difference,\" said the club's leader. \"You just need a plan and people who are willing (7) ___ together.\"","table":null,"lang":"en","stem":"Which word best fits blank (4)?","choices":["who","which","what","where"],"answer":1,"explanation":{"en":"After a comma, a non-defining relative clause that refers back to a whole idea (turning waste into compost) uses 'which'. 'Who' is for people, 'where' for places, and 'what' cannot introduce a relative clause after a noun or idea.","th":"หลังเครื่องหมายจุลภาค อนุประโยคที่ขยายความทั้งข้อความก่อนหน้า (การทำปุ๋ยหมักจากเศษอาหาร) ใช้ which ส่วน who ใช้กับคน where ใช้กับสถานที่ และ what ใช้เป็นคำเชื่อมขยายคำนามไม่ได้"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Completing a text coherently","th":"การเติมข้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Cloze passage","th":"บทความเติมคำ"},"passage":"Read the passage and choose the best answer for each numbered blank.\n\nLast year, students at a school in Bangkok decided to turn an empty rooftop (1) ___ a vegetable garden. At first, many teachers were doubtful. The roof was hot, and there was no soil. (2) ___, the students did not give up. They researched how to grow plants in containers and asked a local farmer for advice. Every student in the club was responsible (3) ___ watering the plants on a different day of the week. They also collected food waste from the canteen and turned it into compost, (4) ___ reduced the amount of rubbish the school threw away.\n\nAfter three months, the garden (5) ___ more than twenty kilograms of vegetables. The canteen cooked them for lunch, and students said the food tasted fresher than ever. The project was so (6) ___ that two other schools have asked the club to help them start gardens of their own. \"We learned that you don't need a lot of space to make a difference,\" said the club's leader. \"You just need a plan and people who are willing (7) ___ together.\"","table":null,"lang":"en","stem":"Which word best fits blank (5)?","choices":["has produced","produced","produces","will produce"],"answer":1,"explanation":{"en":"The story is set in the past ('Last year', 'said', 'cooked'), and 'after three months' is a finished past time, so the past simple 'produced' fits. The present perfect, present and future do not match the past narrative.","th":"เรื่องเล่าเป็นอดีต (Last year, said, cooked) และ after three months เป็นช่วงเวลาในอดีตที่จบแล้ว จึงใช้ past simple คือ produced ส่วน present perfect, present และ future ไม่สอดคล้องกับเรื่องเล่าในอดีต"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Completing a text coherently","th":"การเติมข้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Cloze passage","th":"บทความเติมคำ"},"passage":"Read the passage and choose the best answer for each numbered blank.\n\nLast year, students at a school in Bangkok decided to turn an empty rooftop (1) ___ a vegetable garden. At first, many teachers were doubtful. The roof was hot, and there was no soil. (2) ___, the students did not give up. They researched how to grow plants in containers and asked a local farmer for advice. Every student in the club was responsible (3) ___ watering the plants on a different day of the week. They also collected food waste from the canteen and turned it into compost, (4) ___ reduced the amount of rubbish the school threw away.\n\nAfter three months, the garden (5) ___ more than twenty kilograms of vegetables. The canteen cooked them for lunch, and students said the food tasted fresher than ever. The project was so (6) ___ that two other schools have asked the club to help them start gardens of their own. \"We learned that you don't need a lot of space to make a difference,\" said the club's leader. \"You just need a plan and people who are willing (7) ___ together.\"","table":null,"lang":"en","stem":"Which word best fits blank (6)?","choices":["successful","success","succeed","successfully"],"answer":0,"explanation":{"en":"In 'so + ___ + that', the gap after the linking verb 'was' needs an adjective: 'so successful that'. 'Success' is a noun, 'succeed' a verb and 'successfully' an adverb.","th":"โครงสร้าง was so + ___ + that ต้องใช้คำคุณศัพท์ คือ successful ส่วน success เป็นคำนาม succeed เป็นกริยา และ successfully เป็นคำกริยาวิเศษณ์"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Completing a text coherently","th":"การเติมข้อความให้สอดคล้องกับบริบท"},"topic":{"en":"Cloze passage","th":"บทความเติมคำ"},"passage":"Read the passage and choose the best answer for each numbered blank.\n\nLast year, students at a school in Bangkok decided to turn an empty rooftop (1) ___ a vegetable garden. At first, many teachers were doubtful. The roof was hot, and there was no soil. (2) ___, the students did not give up. They researched how to grow plants in containers and asked a local farmer for advice. Every student in the club was responsible (3) ___ watering the plants on a different day of the week. They also collected food waste from the canteen and turned it into compost, (4) ___ reduced the amount of rubbish the school threw away.\n\nAfter three months, the garden (5) ___ more than twenty kilograms of vegetables. The canteen cooked them for lunch, and students said the food tasted fresher than ever. The project was so (6) ___ that two other schools have asked the club to help them start gardens of their own. \"We learned that you don't need a lot of space to make a difference,\" said the club's leader. \"You just need a plan and people who are willing (7) ___ together.\"","table":null,"lang":"en","stem":"Which word best fits blank (7)?","choices":["to work","working","work","worked"],"answer":0,"explanation":{"en":"'Willing' is followed by a to-infinitive: 'willing to work together'.","th":"คำว่า willing ตามด้วย to + V1 จึงเป็น willing to work together"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"e","skill":{"en":"Identifying the main idea","th":"การจับใจความสำคัญ"},"topic":{"en":"Reading: animals and nature","th":"การอ่าน: สัตว์และธรรมชาติ"},"passage":"The octopus is often called the master of disguise. In less than a second, it can change the colour, pattern and even the texture of its skin to match the rocks, sand or coral around it. For many years, scientists have tried to understand how an animal that is thought to be colour-blind can match its surroundings so well.\n\nThe secret lies in thousands of tiny cells in the octopus's skin called chromatophores. Each one is a small bag of coloured pigment — such as red, yellow, brown or black — surrounded by tiny muscles. When the muscles pull, the bag stretches and the colour spreads out, like a drop of ink on wet paper. When the muscles relax, the bag shrinks to a dot that is almost invisible. Because these muscles are controlled directly by nerves, the octopus can change its appearance almost instantly.\n\nColour is only part of the story. The octopus can also raise small bumps on its skin, called papillae, to copy the rough surface of a rock or the shape of seaweed. Some species go even further. The mimic octopus, found in the waters of South-East Asia, can change its body shape and the way it moves so that it looks like a poisonous lionfish or a sea snake. Animals that might want to eat it usually keep away.\n\nSo how does the octopus know which colours to use? Recent research suggests that its skin itself may be able to detect light. Scientists have found light-sensitive proteins, similar to those found in eyes, in the skin of some species. This does not mean that the octopus \"sees\" with its skin, but it may help to explain one of the ocean's most remarkable tricks.","table":null,"lang":"en","stem":"What is the passage mainly about?","choices":["How an octopus changes its appearance to hide or protect itself","Why octopuses are colour-blind","Where the mimic octopus lives","How scientists study the eyes of sea animals"],"answer":0,"explanation":{"en":"Every paragraph explains part of the octopus's disguise: colour cells, skin bumps, copying other animals and how it may sense light. Colour-blindness, the mimic octopus's home and eyes are only small details.","th":"ทุกย่อหน้าอธิบายการพรางตัวของปลาหมึกยักษ์ ทั้งเซลล์สี ปุ่มบนผิวหนัง การเลียนแบบสัตว์อื่น และการรับรู้แสง ส่วนเรื่องตาบอดสี ถิ่นที่อยู่ของ mimic octopus และดวงตาเป็นเพียงรายละเอียดย่อย"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Locating details","th":"การหารายละเอียดจากบทอ่าน"},"topic":{"en":"Reading: animals and nature","th":"การอ่าน: สัตว์และธรรมชาติ"},"passage":"The octopus is often called the master of disguise. In less than a second, it can change the colour, pattern and even the texture of its skin to match the rocks, sand or coral around it. For many years, scientists have tried to understand how an animal that is thought to be colour-blind can match its surroundings so well.\n\nThe secret lies in thousands of tiny cells in the octopus's skin called chromatophores. Each one is a small bag of coloured pigment — such as red, yellow, brown or black — surrounded by tiny muscles. When the muscles pull, the bag stretches and the colour spreads out, like a drop of ink on wet paper. When the muscles relax, the bag shrinks to a dot that is almost invisible. Because these muscles are controlled directly by nerves, the octopus can change its appearance almost instantly.\n\nColour is only part of the story. The octopus can also raise small bumps on its skin, called papillae, to copy the rough surface of a rock or the shape of seaweed. Some species go even further. The mimic octopus, found in the waters of South-East Asia, can change its body shape and the way it moves so that it looks like a poisonous lionfish or a sea snake. Animals that might want to eat it usually keep away.\n\nSo how does the octopus know which colours to use? Recent research suggests that its skin itself may be able to detect light. Scientists have found light-sensitive proteins, similar to those found in eyes, in the skin of some species. This does not mean that the octopus \"sees\" with its skin, but it may help to explain one of the ocean's most remarkable tricks.","table":null,"lang":"en","stem":"According to the passage, what happens when the muscles around a chromatophore pull?","choices":["The bag shrinks to a tiny dot.","The bag of pigment stretches and the colour spreads out.","Small bumps appear on the skin.","The octopus becomes colour-blind."],"answer":1,"explanation":{"en":"Paragraph 2 says: 'When the muscles pull, the bag stretches and the colour spreads out.' The bag shrinks when the muscles relax, and the bumps are made by papillae, not chromatophores.","th":"ย่อหน้าที่ 2 กล่าวว่า เมื่อกล้ามเนื้อดึง ถุงสีจะยืดออกและสีกระจายออก ส่วนการหดเป็นจุดเล็กเกิดเมื่อกล้ามเนื้อคลายตัว และปุ่มบนผิวเกิดจาก papillae ไม่ใช่ chromatophores"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Word meaning from context","th":"การหาความหมายของคำจากบริบท"},"topic":{"en":"Reading: animals and nature","th":"การอ่าน: สัตว์และธรรมชาติ"},"passage":"The octopus is often called the master of disguise. In less than a second, it can change the colour, pattern and even the texture of its skin to match the rocks, sand or coral around it. For many years, scientists have tried to understand how an animal that is thought to be colour-blind can match its surroundings so well.\n\nThe secret lies in thousands of tiny cells in the octopus's skin called chromatophores. Each one is a small bag of coloured pigment — such as red, yellow, brown or black — surrounded by tiny muscles. When the muscles pull, the bag stretches and the colour spreads out, like a drop of ink on wet paper. When the muscles relax, the bag shrinks to a dot that is almost invisible. Because these muscles are controlled directly by nerves, the octopus can change its appearance almost instantly.\n\nColour is only part of the story. The octopus can also raise small bumps on its skin, called papillae, to copy the rough surface of a rock or the shape of seaweed. Some species go even further. The mimic octopus, found in the waters of South-East Asia, can change its body shape and the way it moves so that it looks like a poisonous lionfish or a sea snake. Animals that might want to eat it usually keep away.\n\nSo how does the octopus know which colours to use? Recent research suggests that its skin itself may be able to detect light. Scientists have found light-sensitive proteins, similar to those found in eyes, in the skin of some species. This does not mean that the octopus \"sees\" with its skin, but it may help to explain one of the ocean's most remarkable tricks.","table":null,"lang":"en","stem":"In paragraph 1, the word \"texture\" refers to ___.","choices":["the temperature of the skin","the size of the octopus","how the surface of the skin feels or looks — smooth or rough","the smell of the water"],"answer":2,"explanation":{"en":"Texture is how rough or smooth a surface is. Paragraph 3 confirms this: the octopus raises bumps 'to copy the rough surface of a rock'.","th":"texture หมายถึง ลักษณะพื้นผิวว่าเรียบหรือขรุขระ ย่อหน้าที่ 3 ยืนยันว่าปลาหมึกยกปุ่มบนผิว \"เพื่อเลียนแบบผิวขรุขระของหิน\""}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading: animals and nature","th":"การอ่าน: สัตว์และธรรมชาติ"},"passage":"The octopus is often called the master of disguise. In less than a second, it can change the colour, pattern and even the texture of its skin to match the rocks, sand or coral around it. For many years, scientists have tried to understand how an animal that is thought to be colour-blind can match its surroundings so well.\n\nThe secret lies in thousands of tiny cells in the octopus's skin called chromatophores. Each one is a small bag of coloured pigment — such as red, yellow, brown or black — surrounded by tiny muscles. When the muscles pull, the bag stretches and the colour spreads out, like a drop of ink on wet paper. When the muscles relax, the bag shrinks to a dot that is almost invisible. Because these muscles are controlled directly by nerves, the octopus can change its appearance almost instantly.\n\nColour is only part of the story. The octopus can also raise small bumps on its skin, called papillae, to copy the rough surface of a rock or the shape of seaweed. Some species go even further. The mimic octopus, found in the waters of South-East Asia, can change its body shape and the way it moves so that it looks like a poisonous lionfish or a sea snake. Animals that might want to eat it usually keep away.\n\nSo how does the octopus know which colours to use? Recent research suggests that its skin itself may be able to detect light. Scientists have found light-sensitive proteins, similar to those found in eyes, in the skin of some species. This does not mean that the octopus \"sees\" with its skin, but it may help to explain one of the ocean's most remarkable tricks.","table":null,"lang":"en","stem":"Why does the mimic octopus make itself look like a lionfish or a sea snake?","choices":["It wants to hunt lionfish and sea snakes.","It cannot change its colour like other octopuses.","Lionfish and sea snakes are its closest relatives.","Predators avoid animals that they believe are dangerous."],"answer":3,"explanation":{"en":"The passage says these animals are poisonous and that 'animals that might want to eat it usually keep away'. So the octopus copies dangerous animals to scare off predators. Nothing says it hunts them, cannot change colour or is related to them.","th":"บทอ่านกล่าวว่าสัตว์เหล่านี้มีพิษ และ \"สัตว์ที่อาจจะกินมันมักจะอยู่ห่าง\" จึงอนุมานได้ว่าปลาหมึกเลียนแบบสัตว์อันตรายเพื่อให้ผู้ล่าหนีไป ไม่มีข้อความว่าปลาหมึกล่าสัตว์เหล่านั้น เปลี่ยนสีไม่ได้ หรือเป็นญาติกัน"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading: animals and nature","th":"การอ่าน: สัตว์และธรรมชาติ"},"passage":"The octopus is often called the master of disguise. In less than a second, it can change the colour, pattern and even the texture of its skin to match the rocks, sand or coral around it. For many years, scientists have tried to understand how an animal that is thought to be colour-blind can match its surroundings so well.\n\nThe secret lies in thousands of tiny cells in the octopus's skin called chromatophores. Each one is a small bag of coloured pigment — such as red, yellow, brown or black — surrounded by tiny muscles. When the muscles pull, the bag stretches and the colour spreads out, like a drop of ink on wet paper. When the muscles relax, the bag shrinks to a dot that is almost invisible. Because these muscles are controlled directly by nerves, the octopus can change its appearance almost instantly.\n\nColour is only part of the story. The octopus can also raise small bumps on its skin, called papillae, to copy the rough surface of a rock or the shape of seaweed. Some species go even further. The mimic octopus, found in the waters of South-East Asia, can change its body shape and the way it moves so that it looks like a poisonous lionfish or a sea snake. Animals that might want to eat it usually keep away.\n\nSo how does the octopus know which colours to use? Recent research suggests that its skin itself may be able to detect light. Scientists have found light-sensitive proteins, similar to those found in eyes, in the skin of some species. This does not mean that the octopus \"sees\" with its skin, but it may help to explain one of the ocean's most remarkable tricks.","table":null,"lang":"en","stem":"What does the last paragraph suggest?","choices":["Scientists have proved that the octopus sees with its skin.","Scientists are not yet sure how the octopus chooses its colours, but light-sensing skin may be part of the answer.","The octopus uses its eyes to see every colour clearly.","Light-sensitive proteins are found only in octopus skin."],"answer":1,"explanation":{"en":"The paragraph uses cautious words — 'suggests', 'may be able', 'may help to explain' — and says this 'does not mean that the octopus sees with its skin'. So the answer is still uncertain. The text also says the proteins are 'similar to those found in eyes', so they are not found only in octopus skin.","th":"ย่อหน้าสุดท้ายใช้คำที่ไม่ยืนยันแน่ชัด เช่น suggests, may be able, may help และบอกว่า \"ไม่ได้หมายความว่าปลาหมึกมองเห็นด้วยผิวหนัง\" แสดงว่านักวิทยาศาสตร์ยังไม่แน่ใจ และโปรตีนนี้ \"คล้ายกับที่พบในดวงตา\" จึงไม่ได้พบเฉพาะในผิวปลาหมึก"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"e","skill":{"en":"Locating details","th":"การหารายละเอียดจากบทอ่าน"},"topic":{"en":"Reading: personal narrative","th":"การอ่าน: เรื่องเล่าประสบการณ์"},"passage":"When my mum suggested that I volunteer at an animal shelter during the school holidays, I agreed mainly because my best friend, Ploy, was going too. I imagined spending my days playing with cute puppies. I was wrong.\n\nOn the first morning, the manager, Khun Dao, handed us gloves and buckets. \"The animals need clean homes before they need cuddles,\" she said with a smile. For three hours we scrubbed floors, washed food bowls and carried heavy bags of rice. By lunchtime my arms ached, and I was beginning to regret my decision.\n\nIn the last cage sat a thin brown dog with one torn ear. Unlike the others, he did not bark or jump up when we walked past. He just pressed himself into the corner and watched us. \"That's Mango,\" Khun Dao explained. \"He was found by the road three weeks ago. He doesn't trust people yet.\"\n\nEvery day after that, I finished my jobs quickly so that I could sit outside Mango's cage. I didn't try to touch him. I just read my book aloud, sometimes for half an hour. On the fifth day, he moved from the corner to the middle of the cage. On the eighth day, he took a piece of chicken from my hand. On the twelfth day, when I opened the door, he walked out and leaned his whole body against my legs.\n\nAt the end of the holidays, a kind family adopted Mango. I cried when he left, but they were happy tears. Ploy says I talk about the shelter more than anything else now, and she is right. I went there expecting to have fun, but I came home having learned something much more valuable: trust cannot be forced. It has to be earned, one small step at a time.","table":null,"lang":"en","stem":"Why did the writer first agree to volunteer at the shelter?","choices":["Because she wanted to adopt a dog","Because Khun Dao asked her to help","Because her best friend was going too","Because she enjoyed cleaning"],"answer":2,"explanation":{"en":"The first sentence says she agreed 'mainly because my best friend, Ploy, was going too'. She had not met Khun Dao yet, did not plan to adopt, and found the cleaning tiring.","th":"ประโยคแรกบอกว่าผู้เขียนตกลง \"เพราะเพื่อนสนิท ปลอย ไปด้วย\" ตอนนั้นยังไม่รู้จักคุณดาว ไม่ได้ตั้งใจรับเลี้ยงสุนัข และรู้สึกว่างานทำความสะอาดเหนื่อย"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Word meaning from context","th":"การหาความหมายของคำจากบริบท"},"topic":{"en":"Reading: personal narrative","th":"การอ่าน: เรื่องเล่าประสบการณ์"},"passage":"When my mum suggested that I volunteer at an animal shelter during the school holidays, I agreed mainly because my best friend, Ploy, was going too. I imagined spending my days playing with cute puppies. I was wrong.\n\nOn the first morning, the manager, Khun Dao, handed us gloves and buckets. \"The animals need clean homes before they need cuddles,\" she said with a smile. For three hours we scrubbed floors, washed food bowls and carried heavy bags of rice. By lunchtime my arms ached, and I was beginning to regret my decision.\n\nIn the last cage sat a thin brown dog with one torn ear. Unlike the others, he did not bark or jump up when we walked past. He just pressed himself into the corner and watched us. \"That's Mango,\" Khun Dao explained. \"He was found by the road three weeks ago. He doesn't trust people yet.\"\n\nEvery day after that, I finished my jobs quickly so that I could sit outside Mango's cage. I didn't try to touch him. I just read my book aloud, sometimes for half an hour. On the fifth day, he moved from the corner to the middle of the cage. On the eighth day, he took a piece of chicken from my hand. On the twelfth day, when I opened the door, he walked out and leaned his whole body against my legs.\n\nAt the end of the holidays, a kind family adopted Mango. I cried when he left, but they were happy tears. Ploy says I talk about the shelter more than anything else now, and she is right. I went there expecting to have fun, but I came home having learned something much more valuable: trust cannot be forced. It has to be earned, one small step at a time.","table":null,"lang":"en","stem":"What does Khun Dao mean when she says, \"The animals need clean homes before they need cuddles\"?","choices":["The animals do not like being touched.","The volunteers should clean their own homes first.","Only clean animals can be cuddled.","Cleaning and caring for the animals' needs comes before playing with them."],"answer":3,"explanation":{"en":"She hands out gloves and buckets as she says it, and the volunteers then spend three hours cleaning. She means the basic care work is the priority; playing comes later.","th":"คุณดาวพูดขณะยื่นถุงมือและถังน้ำให้ และอาสาสมัครก็ทำความสะอาดอยู่สามชั่วโมง ประโยคนี้จึงหมายถึงงานดูแลพื้นฐานต้องมาก่อน การเล่นกับสัตว์มาทีหลัง"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading: personal narrative","th":"การอ่าน: เรื่องเล่าประสบการณ์"},"passage":"When my mum suggested that I volunteer at an animal shelter during the school holidays, I agreed mainly because my best friend, Ploy, was going too. I imagined spending my days playing with cute puppies. I was wrong.\n\nOn the first morning, the manager, Khun Dao, handed us gloves and buckets. \"The animals need clean homes before they need cuddles,\" she said with a smile. For three hours we scrubbed floors, washed food bowls and carried heavy bags of rice. By lunchtime my arms ached, and I was beginning to regret my decision.\n\nIn the last cage sat a thin brown dog with one torn ear. Unlike the others, he did not bark or jump up when we walked past. He just pressed himself into the corner and watched us. \"That's Mango,\" Khun Dao explained. \"He was found by the road three weeks ago. He doesn't trust people yet.\"\n\nEvery day after that, I finished my jobs quickly so that I could sit outside Mango's cage. I didn't try to touch him. I just read my book aloud, sometimes for half an hour. On the fifth day, he moved from the corner to the middle of the cage. On the eighth day, he took a piece of chicken from my hand. On the twelfth day, when I opened the door, he walked out and leaned his whole body against my legs.\n\nAt the end of the holidays, a kind family adopted Mango. I cried when he left, but they were happy tears. Ploy says I talk about the shelter more than anything else now, and she is right. I went there expecting to have fun, but I came home having learned something much more valuable: trust cannot be forced. It has to be earned, one small step at a time.","table":null,"lang":"en","stem":"Why did the writer read aloud outside Mango's cage instead of trying to touch him?","choices":["Because she was not allowed to open the cage","Because she needed to finish her homework","To stop Mango from barking at other dogs","To let Mango get used to her without frightening him"],"answer":3,"explanation":{"en":"Mango 'doesn't trust people yet' and hid in the corner. By staying close but not touching him, she let him get used to her calmly — and he slowly came closer. Mango never barked, and nothing says she was forbidden to open the cage or doing homework.","th":"มังโก้ \"ยังไม่ไว้ใจคน\" และหลบอยู่มุมกรง การนั่งอยู่ใกล้ ๆ โดยไม่แตะต้องช่วยให้มันคุ้นเคยกับผู้เขียนโดยไม่ตกใจ และมันก็ค่อย ๆ เข้ามาใกล้ มังโก้ไม่ได้เห่า และไม่มีข้อความว่าห้ามเปิดกรงหรือผู้เขียนทำการบ้าน"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Locating details","th":"การหารายละเอียดจากบทอ่าน"},"topic":{"en":"Reading: personal narrative","th":"การอ่าน: เรื่องเล่าประสบการณ์"},"passage":"When my mum suggested that I volunteer at an animal shelter during the school holidays, I agreed mainly because my best friend, Ploy, was going too. I imagined spending my days playing with cute puppies. I was wrong.\n\nOn the first morning, the manager, Khun Dao, handed us gloves and buckets. \"The animals need clean homes before they need cuddles,\" she said with a smile. For three hours we scrubbed floors, washed food bowls and carried heavy bags of rice. By lunchtime my arms ached, and I was beginning to regret my decision.\n\nIn the last cage sat a thin brown dog with one torn ear. Unlike the others, he did not bark or jump up when we walked past. He just pressed himself into the corner and watched us. \"That's Mango,\" Khun Dao explained. \"He was found by the road three weeks ago. He doesn't trust people yet.\"\n\nEvery day after that, I finished my jobs quickly so that I could sit outside Mango's cage. I didn't try to touch him. I just read my book aloud, sometimes for half an hour. On the fifth day, he moved from the corner to the middle of the cage. On the eighth day, he took a piece of chicken from my hand. On the twelfth day, when I opened the door, he walked out and leaned his whole body against my legs.\n\nAt the end of the holidays, a kind family adopted Mango. I cried when he left, but they were happy tears. Ploy says I talk about the shelter more than anything else now, and she is right. I went there expecting to have fun, but I came home having learned something much more valuable: trust cannot be forced. It has to be earned, one small step at a time.","table":null,"lang":"en","stem":"Which of the following shows the correct order of Mango's progress?","choices":["moved to the middle of the cage → took food from her hand → leaned against her legs","took food from her hand → moved to the middle of the cage → leaned against her legs","leaned against her legs → took food from her hand → moved to the middle of the cage","moved to the middle of the cage → leaned against her legs → took food from her hand"],"answer":0,"explanation":{"en":"Paragraph 4 gives the days: day 5 he moved to the middle of the cage, day 8 he took chicken from her hand, day 12 he walked out and leaned against her legs.","th":"ย่อหน้าที่ 4 ระบุวัน: วันที่ 5 ขยับมากลางกรง วันที่ 8 กินไก่จากมือ วันที่ 12 เดินออกมาพิงขาผู้เขียน"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Identifying the main idea","th":"การจับใจความสำคัญ"},"topic":{"en":"Reading: personal narrative","th":"การอ่าน: เรื่องเล่าประสบการณ์"},"passage":"When my mum suggested that I volunteer at an animal shelter during the school holidays, I agreed mainly because my best friend, Ploy, was going too. I imagined spending my days playing with cute puppies. I was wrong.\n\nOn the first morning, the manager, Khun Dao, handed us gloves and buckets. \"The animals need clean homes before they need cuddles,\" she said with a smile. For three hours we scrubbed floors, washed food bowls and carried heavy bags of rice. By lunchtime my arms ached, and I was beginning to regret my decision.\n\nIn the last cage sat a thin brown dog with one torn ear. Unlike the others, he did not bark or jump up when we walked past. He just pressed himself into the corner and watched us. \"That's Mango,\" Khun Dao explained. \"He was found by the road three weeks ago. He doesn't trust people yet.\"\n\nEvery day after that, I finished my jobs quickly so that I could sit outside Mango's cage. I didn't try to touch him. I just read my book aloud, sometimes for half an hour. On the fifth day, he moved from the corner to the middle of the cage. On the eighth day, he took a piece of chicken from my hand. On the twelfth day, when I opened the door, he walked out and leaned his whole body against my legs.\n\nAt the end of the holidays, a kind family adopted Mango. I cried when he left, but they were happy tears. Ploy says I talk about the shelter more than anything else now, and she is right. I went there expecting to have fun, but I came home having learned something much more valuable: trust cannot be forced. It has to be earned, one small step at a time.","table":null,"lang":"en","stem":"What is the main lesson the writer learned?","choices":["Volunteering is always fun.","Trust has to be built slowly through patience.","Dogs are better pets than cats.","Friends should always do the same activities."],"answer":1,"explanation":{"en":"The final lines state it directly: 'trust cannot be forced. It has to be earned, one small step at a time.' The story shows volunteering was hard work, not always fun, and cats or friendship rules are never discussed.","th":"ตอนจบบอกไว้ชัดว่า \"ความไว้ใจบังคับกันไม่ได้ ต้องค่อย ๆ สร้างทีละก้าว\" เรื่องยังแสดงว่างานอาสาเหนื่อย ไม่ได้สนุกเสมอ และไม่ได้กล่าวถึงแมวหรือการทำกิจกรรมเหมือนเพื่อน"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Locating details","th":"การหารายละเอียดจากบทอ่าน"},"topic":{"en":"Reading: history and society","th":"การอ่าน: ประวัติศาสตร์และสังคม"},"passage":"Imagine carrying a bag of heavy metal coins every time you went shopping. For most of history, that is exactly what people had to do. Coins made of copper, silver or gold were valuable because the metal itself was valuable. However, they were heavy to carry over long distances and easy for thieves to steal.\n\nThe first widely used paper money appeared in China about a thousand years ago. Merchants in the province of Sichuan, who used heavy iron coins, began leaving their coins with trusted shops and receiving paper receipts in return. These receipts could be passed from person to person and exchanged for coins later. In the early eleventh century, the government took control of the system and began printing official notes.\n\nWhen the Italian traveller Marco Polo visited China in the thirteenth century, he was amazed that people accepted pieces of paper as payment. Many Europeans who read his descriptions found the idea hard to believe. It was not until 1661 that a bank in Sweden issued the first banknotes in Europe.\n\nPaper money works only if people trust it. A note has very little value as paper; it is valuable because everyone agrees that it can be exchanged for goods. When governments printed too much money, that trust could disappear quickly. In some countries, prices rose so fast that people needed piles of notes to buy a single loaf of bread.\n\nToday, the story is changing again. In many cities, people pay for coffee, bus tickets and even street food by tapping a card or scanning a code with their phones. Some experts predict that cash will one day disappear completely. Others argue that it will survive because it is private, simple and works even when the internet does not. Whichever side is right, one thing is clear: money is less about metal or paper than about trust.","table":null,"lang":"en","stem":"According to the passage, what was the main problem with metal coins?","choices":["They had no real value.","They were heavy to carry and easy to steal.","They could only be used in China.","They were printed by the government."],"answer":1,"explanation":{"en":"Paragraph 1 says coins 'were heavy to carry over long distances and easy for thieves to steal'. Their metal WAS valuable, and coins are not printed.","th":"ย่อหน้าแรกกล่าวว่าเหรียญ \"หนักเมื่อต้องพกไปไกลและถูกขโมยได้ง่าย\" ส่วนโลหะของเหรียญมีค่าจริง และเหรียญไม่ได้ถูกพิมพ์"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"m","skill":{"en":"Locating details","th":"การหารายละเอียดจากบทอ่าน"},"topic":{"en":"Reading: history and society","th":"การอ่าน: ประวัติศาสตร์และสังคม"},"passage":"Imagine carrying a bag of heavy metal coins every time you went shopping. For most of history, that is exactly what people had to do. Coins made of copper, silver or gold were valuable because the metal itself was valuable. However, they were heavy to carry over long distances and easy for thieves to steal.\n\nThe first widely used paper money appeared in China about a thousand years ago. Merchants in the province of Sichuan, who used heavy iron coins, began leaving their coins with trusted shops and receiving paper receipts in return. These receipts could be passed from person to person and exchanged for coins later. In the early eleventh century, the government took control of the system and began printing official notes.\n\nWhen the Italian traveller Marco Polo visited China in the thirteenth century, he was amazed that people accepted pieces of paper as payment. Many Europeans who read his descriptions found the idea hard to believe. It was not until 1661 that a bank in Sweden issued the first banknotes in Europe.\n\nPaper money works only if people trust it. A note has very little value as paper; it is valuable because everyone agrees that it can be exchanged for goods. When governments printed too much money, that trust could disappear quickly. In some countries, prices rose so fast that people needed piles of notes to buy a single loaf of bread.\n\nToday, the story is changing again. In many cities, people pay for coffee, bus tickets and even street food by tapping a card or scanning a code with their phones. Some experts predict that cash will one day disappear completely. Others argue that it will survive because it is private, simple and works even when the internet does not. Whichever side is right, one thing is clear: money is less about metal or paper than about trust.","table":null,"lang":"en","stem":"How did paper money begin in Sichuan?","choices":["The government printed notes to replace gold coins.","Merchants left their coins with trusted shops and received paper receipts.","Marco Polo brought the idea from Italy.","A bank in Sweden sent notes to China."],"answer":1,"explanation":{"en":"Paragraph 2 explains that merchants with heavy iron coins left them with trusted shops and got receipts that could be passed on. The government only took control later, Marco Polo came centuries afterwards, and Sweden's notes came in 1661.","th":"ย่อหน้าที่ 2 อธิบายว่าพ่อค้าที่ใช้เหรียญเหล็กหนัก ๆ นำเหรียญไปฝากร้านที่ไว้ใจได้และได้ใบรับกลับมา ซึ่งส่งต่อกันได้ รัฐบาลเข้ามาควบคุมภายหลัง มาร์โค โปโลมาหลังจากนั้นหลายร้อยปี และธนบัตรของสวีเดนเกิดในปี 1661"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Inference from a text","th":"การอนุมานจากบทอ่าน"},"topic":{"en":"Reading: history and society","th":"การอ่าน: ประวัติศาสตร์และสังคม"},"passage":"Imagine carrying a bag of heavy metal coins every time you went shopping. For most of history, that is exactly what people had to do. Coins made of copper, silver or gold were valuable because the metal itself was valuable. However, they were heavy to carry over long distances and easy for thieves to steal.\n\nThe first widely used paper money appeared in China about a thousand years ago. Merchants in the province of Sichuan, who used heavy iron coins, began leaving their coins with trusted shops and receiving paper receipts in return. These receipts could be passed from person to person and exchanged for coins later. In the early eleventh century, the government took control of the system and began printing official notes.\n\nWhen the Italian traveller Marco Polo visited China in the thirteenth century, he was amazed that people accepted pieces of paper as payment. Many Europeans who read his descriptions found the idea hard to believe. It was not until 1661 that a bank in Sweden issued the first banknotes in Europe.\n\nPaper money works only if people trust it. A note has very little value as paper; it is valuable because everyone agrees that it can be exchanged for goods. When governments printed too much money, that trust could disappear quickly. In some countries, prices rose so fast that people needed piles of notes to buy a single loaf of bread.\n\nToday, the story is changing again. In many cities, people pay for coffee, bus tickets and even street food by tapping a card or scanning a code with their phones. Some experts predict that cash will one day disappear completely. Others argue that it will survive because it is private, simple and works even when the internet does not. Whichever side is right, one thing is clear: money is less about metal or paper than about trust.","table":null,"lang":"en","stem":"Why did many Europeans probably find Marco Polo's descriptions hard to believe?","choices":["They did not believe Marco Polo had ever travelled.","Paper had not been invented in Europe.","Chinese paper money was made of iron.","They were used to money whose value came from the metal itself."],"answer":3,"explanation":{"en":"Paragraph 1 explains that coins were valued because their metal was valuable. For Europeans who used only such coins, paper with almost no value of its own being accepted as payment would seem strange. The passage gives no evidence for the other reasons.","th":"ย่อหน้าแรกอธิบายว่าเหรียญมีค่าเพราะโลหะมีค่า ชาวยุโรปที่ใช้แต่เหรียญจึงคงแปลกใจที่กระดาษซึ่งแทบไม่มีค่าในตัวเองใช้ชำระเงินได้ บทอ่านไม่มีหลักฐานสนับสนุนเหตุผลอื่น"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Locating details","th":"การหารายละเอียดจากบทอ่าน"},"topic":{"en":"Reading: history and society","th":"การอ่าน: ประวัติศาสตร์และสังคม"},"passage":"Imagine carrying a bag of heavy metal coins every time you went shopping. For most of history, that is exactly what people had to do. Coins made of copper, silver or gold were valuable because the metal itself was valuable. However, they were heavy to carry over long distances and easy for thieves to steal.\n\nThe first widely used paper money appeared in China about a thousand years ago. Merchants in the province of Sichuan, who used heavy iron coins, began leaving their coins with trusted shops and receiving paper receipts in return. These receipts could be passed from person to person and exchanged for coins later. In the early eleventh century, the government took control of the system and began printing official notes.\n\nWhen the Italian traveller Marco Polo visited China in the thirteenth century, he was amazed that people accepted pieces of paper as payment. Many Europeans who read his descriptions found the idea hard to believe. It was not until 1661 that a bank in Sweden issued the first banknotes in Europe.\n\nPaper money works only if people trust it. A note has very little value as paper; it is valuable because everyone agrees that it can be exchanged for goods. When governments printed too much money, that trust could disappear quickly. In some countries, prices rose so fast that people needed piles of notes to buy a single loaf of bread.\n\nToday, the story is changing again. In many cities, people pay for coffee, bus tickets and even street food by tapping a card or scanning a code with their phones. Some experts predict that cash will one day disappear completely. Others argue that it will survive because it is private, simple and works even when the internet does not. Whichever side is right, one thing is clear: money is less about metal or paper than about trust.","table":null,"lang":"en","stem":"What happened when governments printed too much money?","choices":["People lost trust in it, and prices rose very quickly.","Paper money became more valuable than gold.","People stopped buying bread.","Banks returned to using iron coins."],"answer":0,"explanation":{"en":"Paragraph 4 says that when governments printed too much money, 'that trust could disappear quickly' and prices rose so fast that people needed piles of notes for one loaf of bread. People still bought bread — it just cost far more.","th":"ย่อหน้าที่ 4 กล่าวว่าเมื่อรัฐบาลพิมพ์เงินมากเกินไป \"ความเชื่อมั่นก็หายไปอย่างรวดเร็ว\" และราคาสินค้าสูงขึ้นจนต้องใช้ธนบัตรกองใหญ่ซื้อขนมปังก้อนเดียว ผู้คนยังซื้อขนมปังอยู่ เพียงแต่ราคาแพงขึ้นมาก"}},{"kind":"m1","program":"satit","subject":"eng","format":"mcq","difficulty":"h","skill":{"en":"Identifying the main idea","th":"การจับใจความสำคัญ"},"topic":{"en":"Reading: history and society","th":"การอ่าน: ประวัติศาสตร์และสังคม"},"passage":"Imagine carrying a bag of heavy metal coins every time you went shopping. For most of history, that is exactly what people had to do. Coins made of copper, silver or gold were valuable because the metal itself was valuable. However, they were heavy to carry over long distances and easy for thieves to steal.\n\nThe first widely used paper money appeared in China about a thousand years ago. Merchants in the province of Sichuan, who used heavy iron coins, began leaving their coins with trusted shops and receiving paper receipts in return. These receipts could be passed from person to person and exchanged for coins later. In the early eleventh century, the government took control of the system and began printing official notes.\n\nWhen the Italian traveller Marco Polo visited China in the thirteenth century, he was amazed that people accepted pieces of paper as payment. Many Europeans who read his descriptions found the idea hard to believe. It was not until 1661 that a bank in Sweden issued the first banknotes in Europe.\n\nPaper money works only if people trust it. A note has very little value as paper; it is valuable because everyone agrees that it can be exchanged for goods. When governments printed too much money, that trust could disappear quickly. In some countries, prices rose so fast that people needed piles of notes to buy a single loaf of bread.\n\nToday, the story is changing again. In many cities, people pay for coffee, bus tickets and even street food by tapping a card or scanning a code with their phones. Some experts predict that cash will one day disappear completely. Others argue that it will survive because it is private, simple and works even when the internet does not. Whichever side is right, one thing is clear: money is less about metal or paper than about trust.","table":null,"lang":"en","stem":"Which statement best expresses the writer's main point?","choices":["Cash will certainly disappear in the near future.","Paper money was a mistake that caused rising prices.","China and Sweden invented money at the same time.","The value of money depends on people's trust rather than on what it is made of."],"answer":3,"explanation":{"en":"The writer returns to trust throughout and ends: 'money is less about metal or paper than about trust'. The writer presents both views on the future of cash without choosing one, does not call paper money a mistake, and gives very different dates for China and Sweden.","th":"ผู้เขียนเน้นเรื่องความเชื่อมั่นตลอดบท และสรุปว่า \"เงินไม่ได้อยู่ที่โลหะหรือกระดาษ แต่อยู่ที่ความเชื่อใจ\" ผู้เขียนเสนอทั้งสองความเห็นเรื่องอนาคตของเงินสดโดยไม่ตัดสิน ไม่ได้บอกว่าธนบัตรเป็นความผิดพลาด และจีนกับสวีเดนเริ่มใช้ธนบัตรในเวลาที่ห่างกันมาก"}}]};
